/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231107-5","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"総務委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","topics":[{"id":"topic-01","title":"先ほど申し上げましたとおり取り上げる順番を変更し、初めに、(2)八潮児童センターにおける公金紛失の対応","agenda":"先ほど申し上げましたとおり取り上げる順番を変更し、初めに、(2)八潮児童センターにおける公金紛失の対応","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"なかなかお金の管理というのは難しいかと思います。自分自身もちょっとどこかに置いておいたものがなかなか見つからないということも多々あります。非常に残念だと思います。事務的なもの金銭的なものが出てくるので、今後こういうふうにしたということですが、どう対応していくか。人間ですからやはり間違いはあるかと思います。今後注意して対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"令和５年職員の給与等に関する報告及び勧告の概要","agenda":"令和５年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"勧告の概要ということでお聞きしましたが、それについてはやはり大手ではなくて、一般区民の意見とすれば、今回公民比較の結果ということで職員の給与が人事委員会勧告で出されましたが、我々が聞いている話ですと、民間の中小企業レベルでは、零細企業もいらっしゃいます、個店のお店もありますが、逆に皆さん大変な中、このような給料はやはり頂いていない、所得がないというのが。","respondent":"崎村人事課長","answer":"ただ、今回公務員全般的に上がったのですけれども、この給与勧告については、基本的には人事院の指針に基づいて同種同等の業務を行う民間従業員の給与を広く把握して反映させるといったことですとか、また、企業規模でいいますと５０人以上。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"このまま減ってきて、というよりこれはどこかで回復できるのですか。それが非常に心配なのです。やはり人事というのは人を集めて、そういう方たちに区で働いていただくということが大事でして、区で働くということは多くの区民を支えるのだからそれだけ人材もいなければ駄目だということを考えると、非常に先行きが心配されるデータがあるのですけれども、そういうのは大丈夫なのですか。教えてください。","respondent":"崎村人事課長","answer":"初任給の引上げにつきましては、民間のほうでも例えば大卒ですと民間企業で大体５割弱の企業が初任給を引き上げているというようなところ、高卒でも６割弱の企業が引き上げているところ。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後にちょっと意見だけなのですが、皆さんもご存じのとおり、この品川区近辺、周りの区も含めて家賃がすごく高騰しているのです。私はぜひ若年層に対しては借上げ住宅とか、それから災害対策住宅を何とか確保して、若い人を品川区に職員として残して、それで区民のために働いてもらうように努力をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"意見","question":"今、須貝委員からこういう話があったので、ちょっとだけ触れようかなと思ったのです。だけれども、２０代の後半ぐらいから３０代の、２５歳から３５歳ぐらいまでの間、ここのやりがいがどうしても私は問題だと思っています。だからそう考えるのであれば、そういうところだってもう手を打ちますよとやっていくしかないわけだから、ぜひそこら辺を考えてほしいなというので、何か意見があればいただきます。","respondent":"崎村人事課長","answer":"今回の人事委員会の勧告の中で、職員のやりがいを高める環境づくりということも触れられておりますけれども、環境づくりについては、ここに述べられておりますテレワークですとか時差勤務制度については取り組んでいるところで、今後拡大していきたいと考えているところです。","id":"exchange-005"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"東京都のページに行ってしまうのは課長も分かって、東京都に「すいません、変えてください」と言って、だから品川区はデータを出さなくてはいけないわけだけれども、そうすると東京都のほうは囲ってあるわけではないですか。そこに至るかどうかは品川区ではなかなかできない。こういうのはどうしたらいいのですか。というか、どこで誰がやるのという意味で、どう思っていらっしゃるのかなと。","respondent":"辻広報広聴課長","answer":"やはりアクセシビリティ、そういったことで返事をするというような、区の中での調整は広報広聴課のほうでさせていただきました。ところが、都との関係ですとか、よそとの関係ということですと、そこまでは実態としては今はできていないところです。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここに書いてあるとおり、歴史と文化とかいうのを、いかに品川にはこういう歴史と文化と面白いことがあって、これから売り出してほしいということで、今、ケーブルテレビの方は結構食いついていただいて、取材を進めてもらっています。再来年の５月に完成させるのですけれども、ケーブルテレビの方々にその話をしたら結構乗っています。年間予算が３,０００万円ぐらいしかないから。要望です。","respondent":"辻広報広聴課長","answer":"私のほうに区内の方ですとかいろいろな方からいろいろな情報をいただいて、それを例えば広報しながわで取り上げようとか、今申し上げたように「いいわ！しながわ」で取り上げよう、ケーブルテレビの番組でとか、いろいろ考えるわけですが、まずそのネタですね。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"意見","question":"だから、せっかくそういうのだったら区のほうでそういう人を任命して、その人が取材を受けたらとか、もっとどんどん情報を取ってきてください、その人がもし取材を受けたり何なり、そういうのはどこでもオープンでいいよぐらいの、何かそういう制度みたいなのをつくるということも、結局そういう今の法律が駄目だから、法的に、それはしようがないのだけれども、だから、そういうのではないところのものを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"それならばシティプロモーション課というものをしっかり明確に作って、そこを推進していく。ただ、もう人も要らない。いや、品川区というより品川駅が品川区だと思っている方が多いので、品川というのは宣伝する意味があるのかどうか私には分からないのですが専門家にやはり入っていただいて一緒に取り組んでいくということは大事だと思うのですが、その辺広報広聴課長のご見解をお聞かせください。","respondent":"辻広報広聴課長","answer":"他自治体なんかで広報の専門家的な方を採用するというところもありますし、そういう検討をしたこともありますが、今のところそういう方は雇わないで、自分たちでこういう品川を作りたいという、こういう宣伝をしていきたいという意思の下に。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"今回の視察ではやはり事業部として立ち上げて、その方たちがどんどん率先して進めていく。コマーシャル、写真でもポスターでも、それから商品紹介など、やはりそういうところまで突き進めるには私は専門家がいないと難しいのではないかなと思います。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"２点目が定住人口を増やしていく。３つ目が、シビックプライドと言われている、今いる人たちのプライドを上げていくという、この３つがあると思います。だからこの政策なのだと。この点を、区長も代わられたということもありますので、もう少し目的と目標を、そしてそこからの事業ということで明確化していくということが大事ではないかと思いますけれども、ご見解を伺えればと思います。","respondent":"辻広報広聴課長","answer":"この右下の図にも示しているような大きな目標があって、それにひもづいたものがある。それぞれにＫＰＩなり目標の指標というのが必要になってくるかなとは思っておりますので、それはこれからいろいろ調整する中で課題となって考えていくところかなと考えています。","id":"exchange-011"},{"speaker":"大倉委員","kind":"確認","question":"すみません、ちょっと確認も含めて教えてください。目的のところで、当初のメインターゲットは若い女性だったと書いてありますけれども、今は違うのですか。どの世代が、例えば若い世代なのか、年配の方たちがさらに愛着を増やしていくのかとか、そういうような考え方はどうあるのか教えてください。","respondent":"辻広報広聴課長","answer":"住んでいる人が幸せなまちで盛り上げていこうとなれば観光にもつながっていくものですので、そこを起点として相乗効果で品川を活気づけていくというのがいいのかなと考えています。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。周りの品川区に最近引っ越してきましたとか、ここ何か月で引っ越してきましたという人とお話しすると、本当に品川区は住みやすいですよねというお話をすごくされています。何で引っ越してこられたか。大変かもしれないですが、そういう声を聞けるような何か取組とかというのはどうですかというのは、いかがでしょう。","respondent":"辻広報広聴課長","answer":"もうちょっと大きい量的な調査として、今、転入時のアンケートというお話ですが、紙のアンケートではなく、何かＱＲコードを読んでとか、そういった形などは今後もうちょっと気軽にアンケートなり、小さな単位での調査というのはできるかなと思いますので。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"ぜひいろいろなインターネットを使ってのアンケート、もう既に区もやられていたりするところもあるのかななんて思っています。行政の箱物を造るというところになりますけれども、そういった何か一つ大きな柱を行政以外で民間も活用しながらという考え方もできるのかなというところで、そういった民間活用とかというところの視点というのはどのようにお考えなのかというのを教えてください。","respondent":"辻広報広聴課長","answer":"これからのシティプロモーションの進め方というようなご質問かと思います。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"そうするととんがると最後には判断が結構大変になってくるなというところで、でもとんがらないとなかなかシティプロモーションとして埋もれちゃう部分があるかなと思っているので、ただそこの判断が難しいなと思っているのですが、ぜひチャレンジしてもらいたいと思っているのですけれども、その辺はハードルがあるものの、いろいろ前向きにやってもらいたいと思うのですがいかがですか。","respondent":"辻広報広聴課長","answer":"割と振り切ってやると目立ちやすいのですが、ではそれ以外の、スポーツ契約した後に高齢者の人のと、いろいろな面があり、そこにあまり気を遣い過ぎると総花的になって結局どこにも刺さらないというようなことはあるのかなとは認識しております。","id":"exchange-015"},{"speaker":"塚本副委員長","kind":"質問","question":"最初に、今の品川区の地域というのですかね、そんなところの認識をお伺いしたいと思います。こういうところでいくとやはりシビックプライドみたいな、そういったところのシティプロモーションというのに結構重きを置いたほうがいいのかななんて思うのですけれども、その点、今の品川区の今後のシティプロモーションについての考え方を伺いたいと思います。","respondent":"辻広報広聴課長","answer":"それで地域にそのままいる方ともまたつながりができていくというのが理想かなと思っていますので、そういうことを私たちだけが仕掛けるのでなくて、区民の方と一緒にできていくのが理想かなと思っています。そんな活動を来年度はしていきたいなと思っています。","id":"exchange-016"},{"speaker":"塚本副委員長","kind":"質問","question":"今後またそういう、今は品川区というのはそういう意味では選ばれる、住んでもらえる形になっているかなと思いますけれども、本当に長期的に見れば日本全体の人口は減っていくので、シティプロモーションは長期基本計画とかとは違って適宜計画の期間を決めないので、適宜な見直しというか、そういうのはどう入れるべきなのかなというようなことがひとつあると思うので、その点について最後にお聞きします。","respondent":"辻広報広聴課長","answer":"そういった意味では、それは今回の反省というか課題であったと思いますので、これだけ社会の状況や人々の考え方がいろいろ変わる状況の中では適宜、ＫＰＩを達成したからそれがオーケーか、そういうことではなくて、やり方や課題を見つけながら方向は柔軟に変えていくだとか。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"すみません、最後に１点だけ。中途でそういう方が来られてうまくいく場合と、その人が来てしまってどうするのだ、５年間と。任期付で一応５年間だけれども、それは品川区の職員の人もしっかりやれているから、しっかりやれるからこの部分はオーケーだよという考えで来られた。だから多分感想でも同じことを言うけれども、こういうことが起きていると私は思っているということだけお伝えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":26198,"voices":55}},{"id":"r05-20231108-14","meetingId":"r05-cm11","date":"2023年11月8日","dateIso":"2023-11-08","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松本委員","kind":"質問","question":"これは参考で載せていただいている手引きの素案なのですけれども、私がいろいろ聞いていたところでは、エレベーターについて、車椅子の方が乗られるときには、前から乗っていくので、降りるときに後ろが見えないということで、かごの奥に鏡をつけたほうがいいのではないかというふうなことについて、いろいろなところで聞いてきたのですけれども、そういったところは、今回は記載はないのでしょうか。","respondent":"山下新庁舎整備課長","answer":"こちらにつきましては、ただいま委員ご紹介あったように、車椅子等のご利用者の方が、もちろん後ろに目がついているわけでございませんので、なかなか視認性が難しいというところ、また、現在の庁舎におきましても、本庁舎でありましたり、第三庁舎でありましたり。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"今回、２４０件という、私の感覚ではすごく多い、障害者団体が７団体で、性的マイノリティ支援団体、あと、各世代でということなのですけれども、かなり多いご意見があったようですけれども、この内容は、例えば障害種別でも様々あると思うのですが、この素案には、まず網羅的に反映を、少し難しいところはあるかもしれません。２点、お伺いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"委員、今おっしゃられたところの網羅的というところが、どこまで完全にとか、完璧にというところでは、必ずしも１００％ということではないかもしれませんけれども、いただいたご意見を踏まえて、代表的なところではありますが、今回。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２４０件全てをというのは難しいと思うのですけれども、例えばですが、ここの資料の中には出てきていないところで、こういうご意見があったのだけれども、反映というところまでには踏み込めなかったというものがあれば、ご紹介をいただきたいということが１つです。それをお伺いします。","respondent":"山下新庁舎整備課長","answer":"反映という点で難しかった点ということですけれども、今回、配慮するですとか、そういうふうな形でつくっていく、設えていくという表現ではないところでは、主なご意見の３点目、「また」以下に記載をしておりますが。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回、リフトの話があって、確かに難しいなというのは私も今聞いていて素人ながら思ったところですが、今回の中で、カームダウン・クールダウンルームというような表現もあったりして、正に当事者の方からのご要望ということで、こういうものを設置するというようなことが検討の中に入ってくるというところで、当たり前なのかもしれませんが、あとはもう本当に面積との兼ね合いなのかなと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"今、ウェブサイト上で広く一般の方々にご覧いただいて意見をもらっているという段階だと思っておりまして、素案としてできているものは非常にそういう多くの意見が反映されたものだと理解しているのですが、これ、せっかくなので区民の方々にできるだけ見てもらえたほうがいいのではないかというふうに思っておりまして、これはページの。","respondent":"山下新庁舎整備課長","answer":"１点目の子育て世代ですとか、若者世代の方のヒアリング、何件ぐらいご意見をいただけたのかというところですけれども、子育て世代、オアシスルームの利用者につきましては、およそ２０人ほどの方、２０件という形でカウントしておりますけれども、ご意見を頂戴しまして。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうございました。オアシスルームの方々や若者世代の皆様の人数等を教えていただき、そして、その中で出てきた意見をこのように反映いただいているということが分かりまして、とてもよいことだと思いました。アクセシビリティの手引き以降も、新庁舎検討に当たって、様々ご意見を聞く機会があると思いますので、同じような形で進めていただきたいと要望いたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"先ほど課長からも、若い人の階段というのも、当然それがある中で、障害をお持ちの方も、それぞれ障害、機能が違うので、今、福祉のまちづくり条例の蹴上、踏面は確認できましたけれども、基本的にこれから高さとか基本設計に入っていく中で、これ、本当にいろいろ議論が、多分この階段に関しては、いろいろ議論があると思うので、それは今後、事細かく障害者団体。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"すみません、トイレのことで少し教えていただきたいのですけれども、意見の中にもオールジェンダートイレを導入してほしいというようなことで、今、世の中の要請として、こういったことに応えていくということは必要なことというふうに考えますけれども、こちらの資料の０８のトイレのところの図を見ると、これ、こういったオールジェンダーということの要望の解といいますか、答えとして。","respondent":"大友新庁舎建設担当課長","answer":"トイレとか更衣室などの性属性を示すピクトグラムにつきましては、基本的には文字を併記することと、補足的に配色で識別できることを検討するというところで考えているところではありますけれども、まだ現状、性別に関係なく入れるトイレにつきましては。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の段階では、これだというものがなかなかないのかもしれないですし、やってみると、いろいろなところから、いや、これでは困るというお話が出てきたりとかすることがいろいろ想定されるので、大変悩ましいところなのだろうなというふうに思うのですけれども、少なくとも個別に１つの個室を設けるということは、このオールジェンダーということを要望されている方々か、お一人かは分からないですけれども。","respondent":"山下新庁舎整備課長","answer":"やはり男性の介護をされている女性の方が男性トイレにご入室されるのは、なかなかハードルが高い、また逆もしかりという中で、性別のいかんを問わずご利用いただけるお手洗い、個室のトイレを複数設置することで。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問","question":"なので、その辺を逆に新庁舎全体で誰もが使いやすいではないですけれども、音とか、光ですとか、色ですとか、そういった精神面、心理面に作用するような落ち着いた雰囲気が、障害者にかかわらず、区民の皆様にとってはいいのではないかなと考えますが、その辺、お聞かせ願えますでしょうか。","respondent":"山下新庁舎整備課長","answer":"１点目のリフト、またそれはスペースを要するというところにつきましては、委員ご指摘のとおりでございまして、そういった点でもやはりハードル、課題があるのかなというふうに受け止めてありますので、手引き（素案）の中でも、今回、設置するとか、配慮するということではなく。","id":"exchange-010"},{"speaker":"筒井委員","kind":"確認","question":"トイレについてなのですけれども、このイメージ図ですと、かなり幅広い面積をとるのかなと。面積のことはほかの委員もありましたけれど、これ、全フロア、このような同程度の面積のトイレを設置するのか。トイレに限らずですけれど、この素案のいろいろなイメージ図、イメージ図と言っていいのですか、これはあくまでもイメージであって確定ではないということでしょうか、その確認をしたいです。","respondent":"山下新庁舎整備課長","answer":"したがいまして、０８トイレというところも、どうしても注釈でしたり、ご説明をしたい項目を書いていきますと、このような大きなトイレが１つ出来上がっているような見え方にはなっておりますけれども、全てのフロアにこの形が全部整うということでは必ずしもございませんで。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"性的マイノリティ支援団体のご意見として、トイレについては少し記載がされておるのですけれども、そのほかにも性的マイノリティ支援団体から何かこうしてほしいとか、そういったご意見、ご要望はあったのでしょうか。","respondent":"山下新庁舎整備課長","answer":"したがいまして、今回、プライバシーに配慮した鍵により施錠ができるよう配慮という形をとることで、それは性別を問わずご利用いただけるようなというところも含めた配慮をしてまいりたいと考えています。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"窓口カウンターのところで、私、ホームページに記載のイメージ図も見ているのですけれど、やはり今後、重層的支援体制も始まりますし、いろいろな方々が来て、そこでご相談とかお悩みをお話しされる機会もあるかと思うのですけれど、これ、隣接した個室相談ブースを設けるということなのですけれども、そうなる前に、窓口カウンターで隣の人に話が聞こえないような。","respondent":"山下新庁舎整備課長","answer":"窓口カウンターですけれども、先ほどと同様、手引き（素案）におきますこちらのイラストといいますか、絵については、あくまでも例示ということで、いわゆるハイカウンター、立って応対するようなところは、今現在の庁舎でもあまり仕切りはないかと思うのですけれども。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問・要望","question":"はい、分かりました。ぜひプライバシーに配慮した設えを積極的に検討していっていただきたいと思います。それで最後に、今のオープンハウスとか、電子申請フォームを用いて意見を募るということなのですけれど、まだまだ知らない方がいらっしゃるかなと考えていますので、もう１回広報をするとか、意見を募る期間の延長はお考えではないでしょうか。","respondent":"山下新庁舎整備課長","answer":"広報しながわは、先ほどご紹介申し上げましたとおり、１０月２１日号に掲載をしておりまして、こちらを重ねてというところまでは、現状考えてございませんけれども、ＳＮＳでの配信というところは重ねて行ってまいりたいと考えていますので、今週土曜日の武蔵小山と。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"私からは２点あるのですが、１点目は、駐車場についてなのですけれども、今、品川区役所にあるか分からないのですが、福祉車両車が止められるようなところの設置をぜひお願いしたいということと、一般のトイレ、小便器のほうなのですが、今、現庁舎では水が出ないものがあるのですけれども、ぜひそれも水洗になるのかどうかということをお聞きしたいなという、案がありましたら、お願いします。","respondent":"大友新庁舎建設担当課長","answer":"２点目、トイレが水洗になるのかどうかというところにつきましては、そこの部分についての決定は、まだ設計上進めていないところですので、これからの整備検討の中で検討してまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"駐車場のことについてですが、入り口の近くとか、エレベーター近くとか、ぜひ設置していただきたいと思います。今、水が出ない小便器ですけれども、やはり臭いがきつくて、やはり水の出るトイレのほうがいいかなというふうに思っておりますので、要望ではありますが、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"端的に３つお伺いします。２番目のこの素案について、ご意見をお伺いした２４０件を出していただいた団体とかについては、これはフィードバックを個別にしているのかどうか、こういう形でまとめましたということでお知らせをしているのか、それとも、一般の方と同じように、ホームページ等をご覧になって、追加があれば言ってくださいという形にしているのかというのが２つ目です。この３点を教えてください。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"トイレにつきまして、バリアフリートイレ、なぜ職員が使うものと、不特定多数の方が使うところで広さが３０cmほど違うのかというところなのですけれども、まず１点目として。障害者団体の皆様は、もちろん区内にいらっしゃるというところもございまして、明日以降になってまいるのですけれども、また素案の検討会と同様に、７団体の皆様が２回ぐらいに分かれまして、素案の報告ということで。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。１点目については分かりましたが、職員の方でも外国製の車椅子の方もいるかもしれませんので、その点も含めて、言っていることは分かりますよ、言っていることはよく分かりますし、十分な広さはそもそもあるのだからということは分かるのですけれども、あまり区別するのも申し訳ないかなというところもあって質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"せお副委員長","kind":"質問","question":"１点だけお伺いします。こちらで書かれているベビーケアルーム、授乳室なのですけれども、素案を見させていただいて、それも併せて少しお聞きしたいのですけれども、まず、いただいた資料で、主なご意見のところで、授乳室は安全でプライバシーに配慮した場所に設置してほしいと、これがあるのですけれども、まず、これ以外に授乳室に関して意見があったのかということを教えてください。","respondent":"山下新庁舎整備課長","answer":"今回の設置の場所につきましては、このアクセシビリティの手引き（素案）の中では、具体的な場所は当然これから設計していく中ですので、場所としてはお示ししておりませんけれども、考え方といたしましては。","id":"exchange-019"},{"speaker":"せお副委員長","kind":"質問・要望","question":"場所となると、また少し違ったところになるのかもしれませんね。すみません。民間はしようがないですけれども、できれば、そこは分けていただきたいという。場所をとるので、なかなか難しいとは思うのですけれども、そういった配慮もしていただければなということを要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"この第２回の委員会の中でもワークショップを取り組まれたということで、このワークショップの中身、ワークショップ中は、各委員から活発な意見交換とかがあったのでしょうかというところ、それから、今回、ワークショップをやってみて、今までの委員会ではワークショップ等はなかったのかなというところで、通常の委員会と比べて、各委員の方の意見がより出てきていたのかどうか。","respondent":"泉広町事業調整担当課長","answer":"委員の方とも顔見知りになったといいますか、お顔を合わせながらお話合いができたということで、今後の議論も活発に進むのではないかといったところの効果も生まれたのではないかというようなご意見もいただきまして、通常、確かにおっしゃるとおり。","id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうあります。もう１点、全体のスケジュールのところで、現在、対話型市場調査が進んでいるですが、今、進めている途中というところで、ご発言も限られるところもあるかと思いますが、コメントをいただけるところがあれば、お聞きできればと思います。","respondent":"泉広町事業調整担当課長","answer":"情報を出すに当たりましては、各事業者の方に事前に確認をとりながらというところを前提に、対話型市場調査と呼んでいるところがありますので、そういったところの内容を踏まえながら出していきたいというふうに考えておるところです。","id":"exchange-022"},{"speaker":"山本委員","kind":"確認","question":"今、進捗中ということで、なかなか中身のところは、きついのかなと思っているのですが、それなりの社数の応募があって、今、無事に進んでいるということだと思うのですけれども、確認をします。社数とか、何か中身以外のところで、ご説明いただけることがあれば、お願いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査に関しましては、ご質問の中身では、跡地でどういった活用をしていくのか、活用の用途でございましたり、また、その活用の範囲であったり、あとは、土地建物の権利の形態をどういった形が考え得るのかといったところを広くご意見をいただいたというところで。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。度々質問して失礼いたしました。ぜひ、まとめていただいた資料を待ちたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"私もこれはごもっともだなというふうにやはり思っていて、それが１つと、それについての対応方針が、これ、右側のところがどこがどう対応しているのかが少し分からないのですけれども、その次のページのところにある第５回の検討結果の取りまとめというところに具体的に反映されるのかなというところで、どの程度の検討委員会としての答申というか、その内容となっていくのかなというところで。","respondent":"泉広町事業調整担当課長","answer":"委員の意見がアウトプットにどのような形で活用されていくのかというご質問ですけれども、そちらにつきましては、４ページに記載しています、例えば、令和６年６月頃を予定していると書いています第５回検討委員会の取りまとめの上に、活用の基本的な考え方というところで。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１つ、これ、ページ数でいうと、２１ページの第１回ワークショップの実施結果というところで、ワークショップの中でいろいろなご意見が出た中で、庁舎跡地周辺のところに、少し小さい字ですが、「防災に強い」というような、３０年、４０年後に求めていくイメージとしてあるのですけれども、２２ページの公有地活用の事例のところを見ると。","respondent":"泉広町事業調整担当課長","answer":"最後の淀橋第二小学校跡地のところにつきましては、こちらは、例えば、にぎわいを創出したですとか、福祉施設が入ったですとか、そういった機能が区民のニーズをかなえるために入っていった事例といったところではなく、あくまで財政支出の抑制というところが。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"分かりました。どういう捉え方もできると思うので、第１回ワークショップの実施結果を踏まえてから抽出したような、そういうイメージだったのですが、そういうふうな書きぶりなのですけれども、というよりは、代表的なところを引っ張ってこられた、代表的というか、引っ張ってこられたのかなという印象だったので、あえて質問させていただきました。","respondent":"泉広町事業調整担当課長","answer":"面積の関係で類似の事例がどちらかといったところですけれども、まず、現庁舎の跡地という視点に立ちますと、第１回検討委員会のときに申しました現庁舎、第二庁舎なども含め、おおむね１万４,０００m2ほどあります。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。定住の意味が、今おっしゃっていただいたように、子育てとか、高齢者福祉とかというふうにくくっていただいていたほうが、多分読むほうも、というか、参考にするほうも分かりやすかったと思うので、その辺り、実質私も議論に参加しているわけではないので、皆さんがご理解していればいいのですけれども、その辺りも少し丁寧に説明したほうがいいのかと思って質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、このワークショップに集まった全体のバランス、要は、年齢の幅というか、今、実施検討のグループ討議の成果を見ていると、例えば、スケボーの施設をつくってほしいという方もいたり、高齢者施設をつくってほしいという方もいたり、ドッグランをつくってほしいという方もいたり、集まってきてくれた年齢の幅というか、バランスはどうだったのかなということが聞きたいのと、あと、ごめんなさい。","respondent":"泉広町事業調整担当課長","answer":"検討委員会の中で行ったグループ討議におけるファシリテーターにつきましては、今回、学識経験者ということで３名ご参加いただいてございまして、その学識経験者、大学の先生の方々にファシリテーター役を担っていただきまして。","id":"exchange-029"},{"speaker":"まつざわ委員","kind":"質問","question":"分かりました。学識経験者ですね、そうでした。例えば、権現地域の方であるとか、二葉の方である、大井の方であるという、このワークショップも全体を集めることは大事なのですけれども、例えば、いろいろ騒音でも何でもそうなのですけれども、一番そこら辺の方のお声をやはり聞いてあげるべきというか、聞いていかなければいけないのかなという感覚が私はあるのですけれども、そこら辺を教えてください。","respondent":"泉広町事業調整担当課長","answer":"どういった形になるかといったところはありますけれども、こういった形で区民の意見をお聞きする場面がありますので、様々な場面で、こういうところには広く周知をするとともに、その中でもご意見をいただいてまいりたいと思ってあります。","id":"exchange-030"},{"speaker":"松本委員","kind":"確認","question":"この事業手法というのは、活用の内容とはまた異なるというか、どういうふうに活用していくのかというところと異なって、恐らく従来方式なのか、ＤＢなのか、またＰＦＩなのかというところをお示しいただくのかなというところなのですけれども、それでいいのかという確認と、新庁舎のほうの基本計画の策定のときには、各方式のメリット・デメリットのようなものも示されていたかと思うのですけれども。","respondent":"泉広町事業調整担当課長","answer":"ただ、これは跡地活用の検討委員会の中では、先ほど申し上げたとおり、事業手法を何かメリット・デメリットをつくって選定していくというようなところは考えてございませんで、この庁舎跡地活用検討委員会が終わって、この検討委員会の中でしっかり区民ニーズを捉えた上で。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"今回は、そういうところまではやらないということなのですけれども、今後というところで、私などは、今回は今のお話だと信託とかというところで、単純な従来方式とかＰＦＩとかというところではない別の手法、定期借款なのかどうなのか、信託なのか、いろいろな、またもっと違う形まで想定されているかと思うのですけれども、基本計画のときに、かなり問題だなというふうに思ったのが、当区は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"なので、実施結果のところで、「緑豊か」というキーワードが、２０ページ、２１ページの総括のところに出てきてしまうのですけれども、これ、なぜ「庁舎跡地周辺」というふうに質問をしたのか、どういう効果を狙ってこういう質問をされたのか伺います。","respondent":"泉広町事業調整担当課長","answer":"ワークショップの質問の仕方、地区全体と跡地周辺に分けたところですけれども、まずは庁舎跡地周辺、今回の活用検討の範囲ということでお示しさせていただいた現庁舎跡地と、しながわ中央公園一帯というところで、まずは、そういったところをお示ししながらも、地区全体。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"一体的なまちづくりということで、その周辺ということを聞くということは必要かと思うのですけれども、ということは、庁舎跡地そのものについては、今後、聞いていく予定はあるのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"庁舎跡地周辺、また今後、第２回のワークショップを控えているわけですけれども、そちらの場面でも、庁舎跡地周辺で、例えば、どういう過ごし方を期待するのかですとか。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"庁舎跡地周辺のイメージというか、委員の人に庁舎跡地周辺のイメージを聞いたり、ご要望を聞いて、逆算して、庁舎跡地そのものをどうしていくのかというふうに決めていくという、そういう流れの認識でよろしいでしょうか。","respondent":"泉広町事業調整担当課長","answer":"今回行ってありますワークショップにつきましては、区民ニーズを、どういった形の区民ニーズがあるのかということを広く捉えていくという趣旨でやっているものでございまして、例えば、活用の範囲をどの範囲でやっていくのかというのは、先ほど申し上げた。","id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"先ほど、まつざわ委員からもご質問がありましたけれども、年齢層の幅は分かったのですけれども、区内のどの辺にお住まいだったりとかという、この近隣地域の方というご意見もありますでしょうし、私も住んでいる地域、その辺はうまくバランスがとれているのかどうか、それだけ確認をお願いします。","respondent":"泉広町事業調整担当課長","answer":"区民ワークショップに参加された方のお住まいの地区ですけれども、こちらは本当に幅広く来ていただきまして、当然、近隣の方からも来ていただいていますし、荏原ですとか、品川のほうの地区ですとか、本当に様々なところから集まっていただきまして。","id":"exchange-036"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"それと、先ほど、１１月１５日までに文言ということでしたけれども、少し考え方を当委員会でも整理をしたいのですが、例えば、裏面の環境性能についてというところで、「ＺＥＢ、ＣＡＳＢＥＥの目標水準について、適時適切なタイミングで公表すること」と(2)であるのですけれども、これ、前回の委員会で、一応この意味で公表はされたと思うのですが、そういう意味なのか、それと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"私からお聞きしましたけれども、あってもいいのかなと。今回でまだこのアクセシビリティも素案というところですし、環境性能についても、Ｎｅａｒｌｙ ＺＥＢからＺＥＢ Ｒｅａｄｙに変わったみたいなことも前回報告もあったのですが、これから基本設計を進めていく中で、どういう変更がまたあるかも分からないので、残しておいてもいいのかなというところで。ほかにご意見があればというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この基本計画についてはです。だから、それについて、基本設計においては、品川区新庁舎整備基本計画を忠実に遵守すること、これは私、前にも発言しているのですけれども、これは部長にも、課長にも確認しました。その点については、また文書は一文入れますけれども、今日は議論をしないのであれば、次回また皆さんのご意見も伺いたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"筒井委員","kind":"確認","question":"本当に基本的な確認なのですけれども、この取りまとめ、今までこの委員会で出た、それぞれ各委員からのご発言を議事録とかで確認して抽出されたと、それは正副のご判断で文章化してこのように記載したという理解でよろしいでしょうか。","respondent":"こんの委員長","answer":"はい、そのとおりです。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/994750?Template=document&Id=6158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":35585,"voices":113}},{"id":"r05-20231109-19","meetingId":"r05-cm11","date":"2023年11月9日","dateIso":"2023-11-09","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"品川区地域防災計画の素案","agenda":"品川区地域防災計画の素案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、今回示された被害想定では、下水道は被害が６％に減ったということで、ほとんどのところが被害がなく、そのまま使えるということになるのかと思うのですけれども、そうすると、さらにそれを１００％にしていくという計画があるのかどうかというところも伺いたいと思います。避難所のトイレの耐震化ということですが、伺いたいと思います。","respondent":"平原防災課長","answer":"下水道の被害ですけれども、こちらは被害想定上、かなり減少したということで、東京都下水道局による下水道整備が進展しているものと認識しております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校トイレは、各避難所で１か所はできているということですので。それで、今後さらにそれを広げて、複数の、最終的には全部のということになるかもしれませんが、避難所のトイレを使えるようにしていくお考えなのかどうかというところ、増やしていただきたいとは思うのですけれども、伺いたいと思います。では、続けて伺います。","respondent":"平原防災課長","answer":"実は区のオペレーションも、災害対応は災害対策本部なのですが、復興は復興本部というものがまた別に立って、息の長いものを行っていく形になりますので、そういったことは別で定まっていくのですが、今お話のございましたように。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"マンホールトイレは、今、そうすると公園と避難所を合わせて４００か所ぐらいあるということですか。それで実際足りているのかということだと思うのですけれども、必要数がもし出ているのであれば伺いたいのと、やはり、それをしっかり国でも基本方針に反映させていくということが言われておりますが、品川区としてはマンホールトイレの基本方針というのはあるのかどうかも含めて伺いたいと思います。","respondent":"平原防災課長","answer":"続きまして、マンホールトイレの４００基で足りるのかといったところですが、先ほども答弁させていただきましたが、マンホールトイレだけで何か全てをという形ではなくて、まず先ほど言いました耐震化されたトイレ、あるいは携帯トイレ、簡易トイレ、それから。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、しっかりと、トイレに困るようなことがないようにしていただきたいのと、あと構造上、学校の上層階でできるかどうかという話がありましたけれども、上層階がどこまでか分からないですが、小学校で３階ぐらいまではやっているというところもあるみたいなので、ぜひそういった形で進めて、さらに増やしていっていただきたいと思いますし、まちづくりのほうは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"東京都の中でも幾つか、モデル事業地区の地区防災計画が公開されていますが、品川区では地区防災計画の定められたところがないので、新しい取組だと思われています。今後の検討ではあると思われますが、今後の動きで具体的なところが決められているものがあれば、お聞きできればと思います。","respondent":"平原防災課長","answer":"実際には、どういう地区から進めるのかとか、そういう順序といいましょうか、どのぐらいのスパンでといいましょうか、そういったところについては、まだ決まっていないところですが、今後そういったところが計画上位置づけられましたら。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"地区防災計画の作成後、自治体から防災倉庫や資機材を助成・貸与もされているとのことでしたが、まず品川区の中で、１３地域に限らず、モデルとなる地区防災計画を作成する地域を抽出していただき、さらにモデル地域をホームページ等でどんどん公開するような流れをつくっていただきたいと思いますが、この辺についてさらにお考えを改めてお聞きできればと思います。","respondent":"平原防災課長","answer":"それが１３地区の単位なのか、さらにそれとはまた別の単位なのかといったところにつきましては、まだそこまで検討には至っていないのですけれども、ただ、やはり品川区の場合、防災協議会という単位で１３地区が対応しておりまして。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"それで、防災区民組織への意見照会では１００団体からお答えが来て、高齢者障害者団体については２３団体からということなのですが、例えばどのようなご意見があって、それが、防災計画の中で修正されたところがあるのかといったことについても伺いたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"もう一つは、先日も委員会でご説明させていただきましたが、避難行動要支援者の個別避難支援計画を今作成しておりますけれども、計画作成は進んできているのですが。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのご意見については、この修正の中で、先ほど１つは挙げられておりましたけれども、そういうふうに反映されていくということで、ぜひ反映していただきたいということなのですけれども、その確認でよろしいでしょうかということが１つ。一方で、持って帰るのも結構大変だったとは思うのですけれども、その辺についての配慮はどうなのでしょうか。","respondent":"平原防災課長","answer":"ですので、必ずしも電子上ではなく、実際に紙でと思っているのですが、何分、全部で１,１００ページぐらいに及ぶ計画ですので、貸出しといいましょうか、そこについては、今、私はこの場で把握していないのですけれども、持って帰るにしても重たいですし。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"何日間か、短い時間だったのですけれども。持ち帰れない方については、今までのいろいろな計画だと、もうその場で立って資料を読むしかないのかという感じだったのですけれども、持ち帰るのは大変という方については、どこかスペースを提供していただいて、じっくり見ていただくとか、そういう配慮もしていただきたいと思いますので、その点についていかがでしょうか。","respondent":"平原防災課長","answer":"頂きました意見につきましては、全てお答えを返させていただいて、反映した、あるいはもし仮に反映できないとすると、防災課としての、区としての考え方、さらには地域防災計画ではないところで見直すべきものがあれば、どういう方針で進めるのかといったところを。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、多くの方たちが意見を出しやすいような仕組みを考えていただきたいと思います。これは要望にとどめます。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、何度も申し上げますけれども、防災計画をまとめるのは大変だと思いますが、できる限り自助・共助ができるような仕組みづくりをやってほしいし、最後は公助によって住民をやはりバックアップしていただけるようにやっていただきたいと思います。そして、その地域の人が、その地域の住民をよく知っているわけですから、その地域の人と併せて、やはり自助・共助でその地域を守る。意見だけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。今回のこの素案を出される中で、まずちょっと確認させていただきたいのが、今後の会議の予定が、来年の２月、防災会議、計画案の審議となっておりますが、これが、決定して区民に周知されるのがいつになるのかということ。","respondent":"平原防災課長","answer":"２月の防災会議でご決定いただけましたら、こちらについては直ちに公表という形で、物理的な準備もありますので、即日というのはなかなか難しいかもしれませんけれども、速やかに公表してまいりたいと考えています。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"それが１点です。もう一点は、特に在宅避難の高層マンション、マンション、集合住宅に住んでいる方。トイレを使いたくなってしまうのですけれども、自分のところは漏れていないけれども、上下が漏れているという場合の、そこのチェック機能を今後どうしていくのかというところを、お考えが、検討されていることがあれば教えていただきたいと思います。","respondent":"平原防災課長","answer":"家庭内備蓄におけるトイレの重要性ですが、委員ご指摘のとおり、非常に重要なものと考えてございまして、先ほど、のだて委員からも、ご質問の中でトイレの量的な確保ということもございましたけれども、大多数の方が在宅避難になることを考えますと。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えば八潮団地などは、団地、号棟が自治会になっているということもあって、比較的そういうことが分かりやすい仕組みづくりがされていると思いますが、多くの民間の管理組合というところが、なかなか品川区との連携も取れているようで取れていない側面もあるかと思いますので、今後、大きなマンション、集合住宅に関して、管理組合のあるところはしっかり区と連携が取れる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"開設するのでどうぞ」というのをお知らせするのかというのを教えていただきたいと思いまして、お願いいたします。","respondent":"平原防災課長","answer":"例えば震度６弱以上という形になりましたら、見渡すところでは建物の倒壊がないかもしれないですけれども、広く町会の範囲内でやはり倒壊家屋が出ているという可能性もありますので、そういったところを、全員の把握ができるまで避難所を開設しないなどという形になりましたら。","id":"exchange-015"},{"speaker":"澤田委員","kind":"確認","question":"例えばニュースやラジオ、携帯などで確認して、それぞれ区民の方が、震度６弱以上であれば、もう即、向かうという形で考えていらっしゃるということでいいのでしょうか。","respondent":"平原防災課長","answer":"もちろん、ラジオやテレビ、最近でいきますとスマートフォンもありますし、震度６弱といいましょうか、震度５弱以上になりましたら、防災行政無線でも、ただいまの地震の震度はというような形で放送が入りますので、様々なもので情報を取っていただいて、「震度６弱以上だった。","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問","question":"私から、主な修正点の中の共助の在り方についてお聞きしたいと思うのですけれども、１つ目の、幅広い世代が参加する訓練の実施ということで、この幅広い世代、親子、また高齢者・障害者の方が訓練に参加するというのは、もちろん大切なことだとは思うのですが、これはまずもって品川区が主催する訓練を指すものなのか。","respondent":"平原防災課長","answer":"現在行っております防災区民組織による訓練、あるいは防災協議会による訓練、あるいは、区が実施する訓練というと、どちらかというと職員訓練になるので、あまりそぐわないかもしれませんけれども、様々な訓練で何かご支援することがあるかどうかと考えています。","id":"exchange-017"},{"speaker":"こしば委員","kind":"質問","question":"そういったところの地域の訓練を底上げしていくことが多分、課題になっていくと思いますし、それを既にもう実践されている町会・自治会もあると思うのですけれども、その辺の底上げに向けた訓練を促すことについてのお考えなどを教えていただければと思います。","respondent":"伊藤災害対策担当課長","answer":"来年度以降はまだ検討段階でありますけれども、例えば親子世代をターゲットにしたイベント性を入れたものや、なるべく高齢者や障害者も参加しやすいような訓練体系を取りまして、いろいろな方が参加して。","id":"exchange-018"},{"speaker":"こしば委員","kind":"意見","question":"ぜひ、そういった親子の顔の見えるような訓練、全体の訓練もそうですし、また地域・町会の訓練のほうも、ぜひお示ししていただきたく。一部の役員が集まっているだけだと、その発想がなかなか生まれてこないというのが実情でもありますので、その辺りを柔軟にまたお示しいただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"特に木密地域ですから、そういったことの防災訓練にも特化しておりましたし、また、今のご説明を伺って、地区防災というのはまさにこういうことなのかというのを体感しての今日のお話でしたので、改めまして、実際にお越しいただいておりますので、所感も含めて伺いたいのと、実際、今回の二葉三丁目の防災訓練をご覧いただいて。","respondent":"平原防災課長","answer":"感想といいましょうか、感じたところとしましては、やはり非常によくできた訓練ですが、一方で、二葉三丁目の課題ではないのですけれども、全区的に広げていくには、やはり相当、高度なものが必要なので、一朝一夕にはなかなか。","id":"exchange-020"},{"speaker":"西村委員","kind":"確認","question":"安否確認不明者保護の訓練をしたときに、シャッターの下りた花屋の中に救助が必要な方がいて、警察に通報を区民の方がするところからの訓練なのですけれども、近所の方々が、パトカーも来ますし、何があったのかとベランダからどんどん出てこられるというほど実践的だったというのは私自身も思っておりますので、こういったふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"避難所のトイレのことが先ほどから出ていますけれども、本当に、水や食糧の備蓄と同時にトイレの問題というのは本当に重要な問題だと思うのですが、避難所のトイレは、簡易トイレや仮設トイレ、そしてマンホールトイレということで、もう既に足りているということだったのですけれども、それは、何というのですか、これがこういうくらいでというところで。","respondent":"平原防災課長","answer":"マンホールトイレのガイドラインですけれども、国土交通省が下水道の直結方式のものを推奨しているということは私どもも承知しておりますが、ただ、これは一部、やはり都市部で特に課題となっているのですけれども、大規模な工事がなかなか難しいということもあって。","id":"exchange-022"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"だけど、ハード面でやはり公園のない町会というところは、そういうところがないと、より困難になってくるということであると思いますので、そこのハード面のところでの防災公園を全ての町会に造るというのも、区としても方針としてしっかりと持って、何というのですか、この防災計画の中でも位置づけてやることが必要ではないかと思うのですけれども、その点も伺いたいと思います。","respondent":"平原防災課長","answer":"続きまして町会組織ですけれども、コロナ禍で訓練が止まってというようなところで、改めてもう一度やり直しになっているようなところもありますが、そういったところ、ソフト面というお話がございましたけれども、しっかりとまた支援していますが。","id":"exchange-023"},{"speaker":"鈴木副委員長","kind":"質問","question":"もう一つ、やはり災害のところで本当に最も大事になるのが、下水道と上水道の耐震化というところではないかと思うのですけれども、これもかなり東京都も頑張ってくれているのだと思ったのですけれども、下水道では被害率が前回２８.７％だったのが６.４％になりましたし、上水道も断水率が４６.２％だったのが３０.２％ということで、かなり下がってきているというところなのですけれども。","respondent":"平原防災課長","answer":"東京都は、２０３０年までを目途といたしました強靱化の計画を立てておりまして、その中で様々なものが定められております。そういった中で、今ありましたような耐震化といったところも進めているところなのですけれども、０％という数字ではなかったかと思ってあります。","id":"exchange-024"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"以前、水道局に伺ったときに、かなりの巨大地震にも耐えられる、技術的にはできているのだということも伺いましたので、そういうところで、ぜひ進めて、水道が止まらないということになったら本当に、かなり災害のところではよくなるのではないかと思いますので、ぜひ進めていただきたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"令和５年度区内一斉防災訓練の実施","agenda":"令和５年度区内一斉防災訓練の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけなのですけど、これから品川区内で一斉防災訓練をやりますということで、防災行政無線で流しますけれども、やはり、もう少しボリュームを落としてもいいのですけど、ウーとか、ああいうので、皆さんが、あれは何なのだろうというふうな、私はそういう対応を聞くとか、これはいつもこんなに音が出ないよねとか、そういうことも流したほうがいいように思うのですが、やはりいろいろな。","respondent":"伊藤災害対策担当課長","answer":"今回の地域の総合防災訓練でも、訓練を実施する際に総合防災無線等を流して、地域の方々に訓練の実施、また中止などを呼びかけさせていただきました。防災行政無線本来の目的であるＪ－ＡＬＥＲＴや、他の緊急地震速報等も流しています。","id":"exchange-026"},{"speaker":"せりざわ委員","kind":"質問","question":"聞き逃したのかもしれないのですが、４６か所でやるということで、５２か所、もともと避難所というのが一覧であると思うのですけれども、やらないところの理由というのはどうなのでしょうか。","respondent":"伊藤災害対策担当課長","answer":"ただ、やはり区内一斉防災訓練ということで、同じ時間、同じ時期に訓練を実施するということが非常に重要だと考えていますので、できる限り同じ時期に開催していただけるように、今後も働きかけてまいりたいと考えています。","id":"exchange-027"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"ご答弁のとおりで、やはり一斉防災訓練なので、基本的にはやはり、どんな理由があっても一斉にやっていただくというのをベースにしたほうがいいのだと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/556800?Template=document&Id=6644#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":26929,"voices":70}},{"id":"r05-20231110-10","meetingId":"r05-cm11","date":"2023年11月10日","dateIso":"2023-11-10","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"定められた傍聴ルールに従うというのは当然だと思うのですけれども、現在のルールですと、第１０条、「規則に違反するときは、議長はこれを制し、その命令に従わないときは、これを退場させることができる」とあったと思うのですけれども、今のご説明ですと、具体的にはどういうことでしょうか。それはもう少しお伺いしたいです。","respondent":"渡辺議長","answer":"今、私が考えているのは、せんだってのことは、今までではなかなか想定外の行動だったので、対応し切れなかったと。次回、本会議開催の冒頭に、傍聴規則の案内を、私の口頭で行おうと考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"個人に対する中傷や暴言というのは本当にあってはならないことだと、私もそのとおりだと思っています。うまく言えないのですけれども、傍聴規則を読み上げるだけでは、今のような行動を自粛しようというふうになるのかなというのは、私は疑問に思ったのです。そんな感じなのですけれども、どうでしょうか。","respondent":"渡辺議長","answer":"その際は、退席を含めた対応をしますという断りを、直近であったものでという断りで、様子を見る形で、次回は入れようと思います。そうすることで、会場にいる方の理解と、各議員の理解を得られるかなという考えです。説明を冒頭に持ってくるという考え方は以上です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"提案","question":"議長が議場の秩序を維持していくという大事な役割なので、今ある規則をどういうふうに具体的には当てはめていくかというのは、ある程度、議長の裁量になると思っているのですが、今こういった表明があって、実際にこれから運用になっていくと思うのです。その上で、何か提案が出てくるようでしたら、改めて提案させていただきたいと思います。","respondent":"渡辺議長","answer":"特にこの間の振り返りの中では、やはり人格否定や、特定の個人を恫喝するようなことに値するときが退席というのを、私の中ではイメージしております。これはもう誰もが、万人が許されないこととして思われる範疇だと思いますので、そういった考えです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"議長がせっかく注意したのに聞いていなくて、そのまま入ってくるという方もいらっしゃると思うので、それがいいかどうかは分からないのですが、傍聴者には様々な方が見えるので、良識のある人を守る意味でも、事務局にはお手数ですけれども、何か紙ベースで、来られた方にこれは守ってくださいというものを手渡ししたらどうでしょうか。それは判断ですけれども。","respondent":"渡辺議長","answer":"それで、あるたびに発言も私もないと思いますので、それを聞いていようが聞いていまいが、特に一線を越えるようなことは、説明があろうがなかろうが許されてはいけないということで進めたいと考えていますので、ぜひともまた、お気づきの点を含めて、ご協力をお願いします。","id":"exchange-004"},{"speaker":"西村委員","kind":"意見","question":"それは区民の皆様に理解していただく、紙の配布なのか、何か方法というのは新たに必要かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"やはり、たくさんいる中での全員に対する呼びかけということは、その人本人に、なかなか個人に自分のことだと伝わらないようなことというのもあるのかとも思いますし、集団心理で、全体が騒乱してくると、なかなか抑えも利かなくなってくるというところもあるので、そういった事態にならないようにということでの一巡の考え方などというのは、今後も様子を見ながら、常に考えていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"先日、各常任委員会で行政視察を行ったのですが、私は文教委員ですけれども、非常に充実した視察だったのです。委員会資料や議事録同様、区議会のホームページに上げていく必要があるのではないかと思うのですけれども、そういった検討をこの場でできるのだったら、ぜひしていただきたいですし、必要なところで審議するというのであれば、ぜひ検討をお願いしたいと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。どこの会議体でこれが検討材料になるのかということだけ確認させていただきたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"せりざわ委員","kind":"意見","question":"さっきのところで私も発言すればよかったのですが、議会の傍聴について、反対も何もないのですが、傍聴ルールのところで、先ほど、多分本会議をベースにお話しいただいていたと思うのですけれども、やはり委員会も結構乱れているところがあって、本会議は議長裁量でというところで、第４回定例会にはルール改正は多分間に合わないだろうからというお話も頂いていたと思うのですが、これは常任委員長。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":9993,"voices":40}},{"id":"r05-20231121-10","meetingId":"r05-cm11","date":"2023年11月21日","dateIso":"2023-11-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"の議事日程(1)(2)および追加議事日程","agenda":"の議事日程(1)(2)および追加議事日程","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"局長からもご発言がありましたが、一般質問２日目の２人目、当会派の木村議員なのですが、ご本人からの要望で、２０分間立ったままでの発言が難しいということでございまして、着座でお願いできないでしょうかです。演壇までは自力で歩いていけるです。どうぞご了承願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"死者の４割が子どもという深刻な状況に誰もが心を痛めているのではないかなと思うのですけども、品川区議会として、昨年の３月にはロシアのウクライナ侵略に対しても抗議をして、撤退を求める決議をしました。皆さんいかがでしょうかです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"意見","question":"我々も同じような方向性でいろいろ考えていまして、共産党にお声がけできていないのが恐縮なのですが、しっかりまとめて、議会全体で同じような方向性で結論を出したいと思います。そのように進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":5958,"voices":34}},{"id":"r05-20231127-6","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"区民委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山本委員","kind":"質問","question":"順調に進んでいるという理解ですので、進めていただいてありがとうあります。現状、進んでいる中で、実際の集会所の移転に向けて、何か問題等がないかというところをお聞きしたいというのが一つ。具体的には、その建て替えまでの一定期間を暫定的にマイスクールとして活用されるということかなと推測しているのですけれども、そういった見通しについても、現状、分かるところでお教えいただければと思います。","respondent":"西村委員長、宮澤地域活動課長","answer":"跡地活用が企画部の所管になりますので、お答えいただける範囲でお願いできればと思います。修繕等をしてやっていけばですが、跡地活用に関しましては、企画部のほうで検討して、マイスクールというところで、本日補正予算の審議を含めて、文教委員会のほうで説明されているというふうに伺っております。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"状況として問題なく進んでいるということで、確認できましてよかったと思います。跡地活用については、そういった条件があることを理解しましたので、文教委員会等、ほかの機会を通じて、会派としても確認させていただきたいと思ってあります。","respondent":"宮澤地域活動課長","answer":"契約の部分です。３０年の契約でございまして、駐車場や駐輪場を含めた月額の賃料につきましては、３３９万８,３４０円という形になってあります。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"その金額が、区として妥当だというふうに判断されたその根拠とか理由を、簡単でも結構ですのでご説明いただけませんでしょうか。","respondent":"宮澤地域活動課長","answer":"金額につきましては、区の中で締結している、賃貸借契約をしている物件等と、ただ大きさや位置というのが同じようなものではございませんが、そういったところと比較して、また近隣にもやはり同じような大きさの貸物件というのはなかなか見当たらないところではありますが。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"今回初めて、そういう施設を民間企業から借りるということでございまして、それが無駄なく、割高ではなく使われているかというところは、一つ考えるべきところでもあると思いますので、その点については、私もまた今後ともその勉強をしていきたいと思いますし、無駄のない賃料の契約締結等、今後あるときには心がけていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ＪＲ西日本のいわゆる住宅部門の、ある一定のやはり富裕層と言っていいのか、ある程度のそういう物件であるということは確認できたのですが、そういう点において、そういった認識でいいのかどうかというところと、これもたしかその当時、課長にも確認したのですが、この持ち主というかオーナーは、ＪＲ西日本という私が調べたものと、地元の方たちが言っている企業とは違う企業だったのですけれども。","respondent":"宮澤地域活動課長","answer":"ＪＲ西日本の担当者とお会いしたところでのお話というところになって、ＪＲ西日本になるのですけれども、東京のほうであのような物件を構えて、末永く賃貸借の収益を上げていくというふうに伺っている中で。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"要するに安定性という点も含めて、区のものが入っているわけですから、あまりそういうのは好ましくないというところで、先ほどもありましたが、決して安くはない家賃を払っているわけで、そこについての安定性については、区はしっかり大丈夫だという認識があるのかということと、これも前回聞いたかな、町会への協力については、当然地域センターが入るわけですから、そこについては働きかけ。","respondent":"宮澤地域活動課長","answer":"地域センターの町会への支援というのはいろいろ行っておりますけれども、様々な事業が頻繁にありまして、ウェルカムセンター原にて地域のイベントというのも行われていきますので、そういった中を含めて、居住されている方の町会等への加入も含めて支援できたらと考えています。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"移転後の跡地の活用が決まったということで報告はされていて、これは企画部だというのでそこは伺わないですけれど、前回８月の委員会のときに、私の印象に残っているのは、もう４３年経っているのだと。だから私がそのとき質問したのは、大体この４０年ぐらいで老朽化というのであるならば、ほかの地域センターではどこがあるのですかという質問をたしかしましたよね。何かよく分からないのです。","respondent":"宮澤地域活動課長","answer":"地域センター自体につきましては、これから先も地域の人たちの町会・自治会の支援も含めてですが、まず、地域に最も身近な区役所としてこの先もサービスを提供していくという中で、４３年を迎えて老朽化の兆しも出てきた、老朽化も進んできたというところの中で、今後１０年。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"今の説明だと、何かよく分からないですね。それと今、課長の答弁で、１０年、２０年、３０年後を考えた、というふうにすると。つまり、何が言いたいかというと、途中でいろいろ事情があって、なぜなら民間のマンションなのだから、いろいろ事情があって「すみません、退去してください」とか「契約をこれで終わりたいです」といったら、何のためにこうやったか分からないではないですか。","respondent":"宮澤地域活動課長","answer":"その３０年後につきましては、３０年経ってからというところになりますが、引き続きというところで契約は可能だというところです。それは状況に応じていくというところにはなるかと思いますが、３０年は保障されていくものです。","id":"exchange-008"},{"speaker":"藤原委員","kind":"確認","question":"は若い議員たちに３０年後どうなったかを見てもらって、きちんと議事録にも残っているので、そういう意味で３０年後がどうなるかという思いがあるのですけれども、ただ、もう１回だけ確認しますが、老朽化もありますが、やはり、防災備蓄倉庫の話も出ましたけれども、その地域のために、大きいところをこれだけ金額をかけて借りても、これは、区民の、特にここを使用する町会の方々。","respondent":"宮澤地域活動課長","answer":"区民集会所が大きくなることや、防災備蓄倉庫ができること、またそれ以外にも、障害者向けの駐車場であったり、授乳室も設けたりとか、様々なサービスの使い勝手がよくなるように、機能を強化しておりますので、それらを含めまして。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"課長、そういうことをいい意味でどんどん答弁の中へ入れてください。障害者の方の駐車場ができるのですとか、そういう意味においてということを強く、こういう委員会で答弁してくだされば、地域で質問を受けたときに、きちんと「皆さん、こうなるのですよ、こうなるのですよ」と。賛成ですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"えのした委員","kind":"質問","question":"例えばこれ、マンションはよく修繕とか大修繕をやると思うのですけれども、そういったところでお金がかかった場合には、賃料には全く影響してこないのかどうなのか。契約内容が分からないのですけれども、そういったところまで、３０年なので、長い期間ですとそういったことも考えられるので、その辺についても区としてはどのようなお考えですか。","respondent":"宮澤地域活動課長","answer":"月額の賃料につきましては、３０年間変わることのない金額で契約をしているというところです。ただし、地価の変動であったり、物価等々で、社会一般的に相応の、何か変動が起きた場合には、相談という形にはなっておりますが、基本的に賃料は変わらずです。","id":"exchange-011"},{"speaker":"えのした委員","kind":"確認","question":"多分含まれているのだろうなということで、それは確認できたので、やはり契約年数が長いので、その時代に合った、それが例えば地域の近隣のほかの賃貸物件と比較して、やはり下がってくる、上がってくるということがあれば、区としてもやはりそれに応じて、契約内容をＪＲ西日本と協議してやっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、防災備蓄倉庫のことで、防災機能の強化というところに今回力を入れている部分だと思いますので、その確認だけさせていただきたいのですけれども、こちらの建物自体は地上５階建てということでよろしかったですか。その中の一、二階を、今回地域センターに、という理解だと思うのですけれども、その全体の確認。","respondent":"宮澤地域活動課長","answer":"すみません、今回浸水ハザードマップ等々含めて、浸水被害を想定してというところは確認していないところですが、２階部分にできるということと、道路を挟んで反対側にはグラウンドを含めたウェルカムセンター原があるという所で。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"必ずそうなるかどうかは分からないのですけども、過去の実績等を見たところと、あとは今後の雨ですとか集中豪雨ですとか、様々な状況を見ていただきながら、配置等も検討いただきたいと思います。今現在がどうというところではありませんので、状況をよく確認していただきながらというところだと思うのですけれども、一言お願いできればと思います。","respondent":"宮澤地域活動課長","answer":"防災備蓄倉庫につきまして、所管となる防災課とも連携しながら、また、地域センターが入っておりますので、そこでも、日頃からの防災への備えというのも検討しながら、併せて進めていきたいと思います。","id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"どこかを取得するにしてもお金はかかってくるものなので、それはそうなのですけれど、３０年間契約で、やはり地域センターなどは地域に定着して愛着を持たれてというものになるので、それ以降買い取るということに、取得できるということになっていったりしないのか伺いたいです。この区民使用料のところだけ、金額を教えていただきたいのです。","respondent":"宮澤地域活動課長","answer":"３０年間賃貸借をしていくというところでありまして、その先買い取るとかどうこうというところに関しましては、ちょっと今現在では検討はないです。区民集会所の使用料につきましては、会議室タイプの第一・第二集会室につきましては、大きさが今よりも大きくなります。","id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"分かりました。地域にとって大事な施設ですので、私も反対するものではないのですけれども、やはり今後、今、ほかの委員からも出ましたけれど、どうなっていくのかちょっと分からないというところはありますので、ここは注視していかなくてはいけないなというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"せらく委員","kind":"質問・要望","question":"それで、先ほど出ました集会所の使用料のところなのですけれども、広さ等でちょっと上がってきているというところで、広さ以外に附属の設備などで、移転後にグレードアップする部分がありましたら教えていただきたいと思います。","respondent":"宮澤地域活動課長","answer":"区民集会所の中身の部分の設備につきましては、今回移転するということで、机と椅子等に関しましては新調する予定です。併せて、プロジェクター等の設備というのは引き続き設けて、音響設備も新たな物を設置する予定です。","id":"exchange-017"}]},{"id":"topic-02","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これも繰り返しになってしまいますけれど、前回の補正予算は２億３,０００万円余を組んでいて、決算額が５,１００万円余ということで、不用額が１億８,０００万円弱出たということで、執行率が２２％ということで、どうしてなのですかという質問に対して、たしか答弁の中では、運送事業者の数が、国が出しているものをそのまま使って、それが実態と合っていなかったというような。","respondent":"小林商業・ものづくり課長","answer":"そのときは、大体この申請期間１か月で３００件ぐらいだったのですけども、今回この期間も少し多めにというか、できるだけ年度内に執行できるようにということも踏まえてですけれども、１.５か月としておりまして、その申請期間のペースが１.５か月ということで。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"それと、運送事業者等燃料費高騰対策支援金のほうですけれども、今のお話だと期間が長くなったから申請件数がそれぐらい見込めるのではないかということと、実態も見据えたということですが、これ、業界の聞き取りというのは、今回は、前回もしたのかどうかというのは確認してないのですけれども、業界からどれぐらいの事業者がいるのかという聞き取りなどはしたのですか。","respondent":"小林商業・ものづくり課長","answer":"１,１００件というのが、これは関東運輸局からの聞き取りですけれど、それと合わせまして、昨年も実施するに当たりましては、各団体、トラック、タクシー、そういったところも含めまして、個別の事業者周知といいますか、いろいろご連絡もさせていただいたところです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特にトラック協会からも、我々も、随分前ですけれどこういうご要望もいただいていて、金額が１億５,０００万円以上売り上げている団体でも４０万円ということで、どれだけその効果があるか分からないけれども、やはり品川区から、行政がそういうところをサポートしてくれるという気持ちがうれしいということで、実質的には当然ありがたいということもあるのですけれども、ぜひ、漏れのないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"省エネルギー対策設備更新助成金と運送事業者等燃料費高騰対策支援金の、両方かぶる部分なのですけれども、こちらの申請につきまして、オンライン申請を原則として書類申請も可能ということなのですが、現在、２２２件の中で割合はどうなっているのかというのを教えていただけたらと思います。","respondent":"小林商業・ものづくり課長","answer":"ですので、我々としましてはやはり、行政手続のＤＸ化という意味ではオンラインをできればやってほしいですけれど、事業者の中にはやはりそこがまだできていないということもありますので、今回もこの両面でということでやってまいりたいと思います。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらはぜひお願いしたいなというところと、昨年度と同じスキームということだったのですけれども、関東運輸局からの聞き取りで、昨年１,１００件程度ということだったのですが、そちらの事業者数の変化みたいなところも、特に昨年と変わりはないのか、その辺り、どのような形で確認していただいているのかというところ。","respondent":"小林商業・ものづくり課長","answer":"私、先ほどから、所管業界、所管団体というのは個別にというお話をしておりますけれど、例えばですけれども、個人タクシー協同組合でいきますと、その中で支部単位というのもございまして、例えば品川支部とか城南支部とか、幾つか支部があるようでございまして。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"今の周知がきちんときめ細かくされているのですかというのは、これはするべきだと思うのですけれども、もう一つは、やはり申請の複雑化はないのですよね。すごく簡素ですよね。窓口がきめ細かくきちんと対応してあげる体制は取っているのですかということが質問なのです。今の決まりだと火葬するわけです。どんな方でも火葬するわけですから、火葬場等への助成というのはどうなっているのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"火葬場につきましても、そういう意味では一つの業種、業界ということではありますけれども、全業種ですので、そういう意味では、特定の何か業種を排除してというような意味ではございませんで、そういう中で対応可能かなというふうに考えてあります。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"ほかの委員の方からも様々ご質問いただいておりますので、私からはそれ以外のところで１点追加で聞ければと思うのですけれども、こちらは全業種対象ですが、現在、申請されている中で、どのような業種がそれぞれ使われているのかというところの割合、傾向等があれば教えていただきたいというところと、あと、対象者、区内中小企業と、そして個人事業主ですが。","respondent":"小林商業・ものづくり課長","answer":"実際にどういう設備が導入されているか、買換えをしているかということでいきますと、冷凍冷蔵庫など厨房設備、調理機械というものが多くございまして、また、続きまして多いものが製造業ですけれども、サービス提供場所、工場等への業務用の空調設備。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"分かりました。そのような傾向があるのですね。ほかの委員からも質問がありましたが、それ以外のところの対象となる事業者の方々もいらっしゃると思いますので、そういった方々にもぜひ使っていただけるように周知をしていただければと思いますし、こういった状況を踏まえて、また、来年度以降も引き続き支援ができることをご検討願いたいです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"えのした委員","kind":"質問・要望","question":"この運送事業者等燃料費高騰対策支援金のほうなのですけれど、これも各団体に個別周知しているということで安心したところですが、やはりいつも周知、周知と言っていますが、なかなかその情報というのは自分で取りに行かないと入ってこないのかなというところもありますので、そこをもう少し丁寧に、これ、今年の交付要領の最後のほうに、フォローアップという。","respondent":"小林商業・ものづくり課長","answer":"我々のほうで窓口に来られた方、経営相談にいらっしゃって、実際その場では申請しなくて、ちょっと家に持ち帰ってということもありますけれども、その際にもできるだけ電子申請でよろしくお願いしますということはお願いしておりますので、そういったことを引き続き。","id":"exchange-026"},{"speaker":"えのした委員","kind":"質問・要望","question":"安心したところですが、やはり一度、事業者の方が役所に出向いてくるという、そこも例えば電話ですとか、オンラインですとか、お互いにその辺ももう少しオンラインで申請が簡単にできるような取組も、要望としてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"せらく委員","kind":"質問","question":"先ほど、電子申請と紙での申請の割合をほかの委員がお伺いしたところなのですけれども、やはり、行政ＤＸ化というところでオンライン申請を進めていきたいというご答弁がありましたが、オンライン申請にたどり着くまでの経路といったところはどのように想定されているか、伺えますでしょうか。","respondent":"小林商業・ものづくり課長","answer":"その際に、こういう電子申請の手続きのほうもちょっと、ということでありましたら、手続きをご案内して、分からないということであれば、改めてご説明の機会つくらせていただくか、あるいは、急いでいるのだということであれば。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"そういったところのホームページの改善だとかも進めていただいて、行政のＤＸ化、オンライン申請化、増えるのではないかと思ったのですけれども、ご見解を伺えればと思います。","respondent":"小林商業・ものづくり課長","answer":"ホームページの改善も随時やっていくというのに合わせて、我々の、紙の情報としまして産業ニュースで区内の事業者にお配りしているものがありますけれど、その中にはＱＲコードをご案内しながら、ここをたどっていただけると、というのをご紹介しつつ。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"助成金、支援金を出していただけるということで、しかも一般財源ということですので、よかったなと思うのですが、先ほどほかの委員からもありましたけれども、やはり納期が年度内ではないというものにはちょっと柔軟に対応していただきたいなというふうに思うのです。来年度も引き続きというところの意欲というのをお聞かせいただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"ただし、先ほど申し上げましたように４か月で２００件ペースで来ておりまして、恐らく当初、もともと予定していた１月末ぐらいまでに、恐らくこの１００件もそれぐらい来るペースで申請が上がってくるのではないかなというふうに考えてあります。","id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"業種が絞られているというところでは、先ほどのほかの委員からの質問でも、特に、こうしたガソリン等を使う業種ということだったのですけれど、特にというよりは、そのほかの業種も、エネルギー代から食費から様々、全てが高騰している中ですので、少しずつでもいいですから業種を広げていくという検討をしていくべきではないかなというふうに思うのですけれども、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"引き続き、いろいろ経済の状況あるいはその物価の動向などを見ながら、経済の下支えに何が必要かということを引き続き考えていきたいと考えております。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今回は全て一般財源でやっていただいたということで、やはり健全財政ですし、急がなくていいものを今、一旦止めて、生活や仕事を支えるということが必要だと思いますので、ぜひ引き続き業種を広げて、こうした支援も継続を、状況を見てしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-03","title":"令和５年陳情第４８号、持続が困難な小規模事業者を支援するための陳情","agenda":"令和５年陳情第４８号、持続が困難な小規模事業者を支援するための陳情","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"陳情の理由の2)「新たなる事業資金の貸付」のところでご説明をいただきまして、これは現状、品川区で様々な支援制度があることを私も理解しておりますが、一般的に事業者が使える小規模事業者向けの融資制度の枠、それから足元の物価高騰等の緊急融資制度の枠に対して、現状使っている方々がどれぐらいの金額で使っているか、要は、さらに追加的に利用できる枠がどれぐらいあるのかというところ、一つ。","respondent":"小林商業・ものづくり課長","answer":"２点目、品川区の融資あっせん制度を使ってどれぐらいの融資が通っているのかですけれども、実際に否決しているというもののほかに、金融機関を乗り換えるので自分のほうで一旦取り下げますというものも含めた数字になってしまうのですが。","id":"exchange-033"},{"speaker":"山本委員","kind":"質問","question":"緊急融資制度のところでも、上限１,０００万円の枠でやっているということなのですけれども、これも、その足元での利用率、大体どれぐらい使っているのかというところも追加でお聞きしてもいいでしょうか。","respondent":"小林商業・ものづくり課長","answer":"通常のいわゆる融資あっせんのメニューに加えて、プラスアルファで今、上乗せしている緊急の部分、１,０００万円の物価高騰等総合支援資金というものがありますけれど、こちらにつきましては、現時点での平均実施としましては８００万円から８５０万円ぐらいの間。","id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"要は、陳情理由の1)のところでは、様々なところから、区の事業も書かれていますけれど、様々なところから借りてきているわけです。先ほども区以外のところでの金融機関とのやり取りなどで借りている部分もあるかと思うので、免除そのものは困難ですというような説明もあったのですけれど、この返済に対しての支援というのは、区としてできることはあるのでしょうか。伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"例えばコロナのときに資金を借りて、それから一定期間が経って、実際に元本の支払いや元利の支払いの金額が少し増えてきたというあたりで、その返済計画の見直しが必要な事業者に対しましては、品川区としては借換専用資金という形で一旦お金を借り換えていただく形で。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この、国がやっている物価高騰対応重点支援地方創生臨時交付金というのは、もう、この間追加でまた、案が出されたのですけれど、これまで品川区にはどれくらい来ているのか、これからどれくらい来るのかというものがあれば教えていただきたいのです。要は、こういうものも使ってどんどん支援できるのですよねというのをお聞きしたいのですけれど、伺います。","respondent":"小林商業・ものづくり課長","answer":"１点目のご質問に戻りまして、返済の借換専用資金のような、借換えもできないようなケースがあるのかどうかですけれども、先ほど申し上げたような、融資の審査率というところでは９割以上、その中にはほかの金融機関から借りますというような件数も含めてそれぐらいですけれども。","id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ漏れる方がいないようにしていただきたいなということなのです。それで、陳情理由3)のところに、緊急小口は、品川区で言えば社会福祉協議会、そしてあとは東京都ということで、私たち共産党もずっと求め続けているのですけれども、こうした中小企業の固定費の補助というのもやはり今少し踏み込んで進めていただきたいなというふうに思っているのです。","respondent":"小林商業・ものづくり課長","answer":"景気情勢の中で、どういったものが企業経営に一番影響が大きいのか、与えられるところなのかというところを引き続き注視しながら、経済の下支えの中で何が必要かということを引き続き検討してまいりたいと考えています。","id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それでさらにインボイスも強行されているという状況では、本当に踏んだり蹴ったりだなという、もう崖っぷちから落とされる勢いですという声も本当に寄せられていますので、ぜひ、固定費補助に踏み切るべきだなというふうに私は思います。先ほど言った物価高騰対応重点支援地方創生臨時交付金、これはある、そして話は聞いている、けれども使っていないということなのでしょうか。そこを伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"現時点で、これは恐らく東京都、例えば区政課とかを含めてですけれども、国なりというところで、品川区のほうに幾らの金額でという形での正式な連絡なり調整がまだ済んでいないといいますか、現在協議中ということで認識しています。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"すみません、ではこれから来るということなのですね。ぜひそういうもの、いろいろメニューがどんどん追加されていると思いますので、ぜひ積極的に使っていっていただきたいなと思いますし、本当にこのままでは、中小企業のこの品川のまちが本当にどんどんシャッター通りになり、商店街も厳しい状況になってくると思います。支えていくことにさらに力を注いでいただきたいなという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"えのした委員","kind":"意見","question":"本日結論を出すで、不採択にします。本当に、物価の高騰、エネルギー価格の高騰によって、中小事業者の経営は困難な状況だと思うわけで、支援が必要だと思います。先ほどの議案にも賛成させていただきました。そして、先ほどの理事者のご答弁どおり、品川区では様々な支援制度に取り組まれております。理解をしましたので、不採択にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出す、態度は不採択です。理由を述べます。陳情者のおっしゃるように、様々この物価高騰において、安定的な事業活動に影響が生じているということは、我々も事業者の皆様からお話を伺っているところです。利息の引き下げに関しても、３年間は無利子、その上、４年目以降も低い金利に抑えているということもやっていると。以上のことから、今回のこの陳情に関しては不採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"山本委員","kind":"質問・要望","question":"本日結論を出すで、結論は不採択でお願いいたします。私も長くなりますが、理由を述べます。これは要望です。そのような困っている方々へ、ではどうしたら周知できるか、どうしたら届くかというのは私も考えていきたいと思うのですけれども、区としても、ぜひ工夫をご検討いただきたいということと、ご相談にいらした方々への丁寧な対応に努めていただきたいというところで、こちらも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"結論を出すで、採択でお願いしたいと思います。それで、この新たな資金の貸付。そうした部分では区としては、本当にこれを進めていただきたいなというふうに、もうずっと私たちも求めてきたことですので、もうこれは大賛成なのです。それを支援するということ、してほしいというところは、ぜひ応えていただきたいなと思いますし、私は議会として応えていきたいなと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、職員の方々の対面でしている大変さは分かりますが、本当に丁寧に、そして思いやりを持って、区の職員は法令・条例に基づいてそれを担保に動いていると思うのですけれども、やはり人として寄り添っていただいて、ご相談、相談を受けても結果というのは出てしまうかもしれないが、その辺は対面でやっていくわけですから、思いやりを持って接していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由といたしましては、区内の事業者の皆様、あと、生活する皆様も今、物価高騰、エネルギー価格の高騰ですごく大変な思いをされていることは理解しておりますけれども、区で提供している支援が今あるという、ご説明の中でもありましたが、そういう現状でそういったところをしっかり使っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238887?Template=document&Id=2974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":40113,"voices":136}},{"id":"r05-20231127-7","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"厚生委員会","time":"午前１０時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件抜き出しています。","topics":[{"id":"topic-01","title":"では、(1)第８３号議案、品川区国民健康保険条例の一部を改正する条例の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(5)の第９０号議案","agenda":"では、(1)第８３号議案、品川区国民健康保険条例の一部を改正する条例の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(5)の第９０号議案","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"ほかの指定管理者も同様なのですけれども、今回公募によらないということで、これまでの指定管理者を選定するということになっていると思うのですが、この公募によらない特別な理由というものは、この場合はどのような理由なのかを１点伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"この現行の指定管理者を更新した理由としては、先ほどの説明でも少し申し上げてはいるのですけれども、平成３１年３月の開設以降、高齢者を含む多世代の身近な交流の場として、様々な自主事業としての交流事業を盛んに実施してくださっています。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"この平塚ゆうゆうプラザについては、モニタリングのところでも、これは９月のときにご報告いただいたのですけれども、そのモニタリングのところで、収支のところに、障害者や高齢者の施設は人件費が書かれているのですが、ここは人件費が書かれていなくて、なぜ人件費というものが書かれないのかということでちょっと伺いたいということと、委託料は２,１８７万円余と書かれているのですけれども。","respondent":"川原高齢者地域支援課長","answer":"複数ご質問をいただきました。１点目が、配点の選考基準の評価項目ごとに点数が出せないのかというご質問に対しての回答です。こちらについては、品川区の指定管理者の基本方針に係る基準に基づいて、総合の評価のみという形でしています。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"施設運営費の大きな支出というものは人件費になるのかなと思うのですけれども、その辺のところが、大体人件費という形でなるのか、その辺のところを伺いたいと思います。それと、モニタリングで、地域ミニデイ卒業グループの元気ゆうゆう体操クラブについて書かれているのですけれども、多分地域ミニデイをされているということですよね、ここで。","respondent":"川原高齢者地域支援課長","answer":"そうです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"多分運動支援員が１人いて、あとはボランティアの方でやるという、そのような体系でというものが総合事業を始めるときの説明だったと思うのですけれども、今もそのような形で、このゆうゆうプラザでもやっているのか、その点も伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただいた地域ミニデイの部分も、やり方、運営の方法については、以前から大きくは変わっておりませんで、高齢者や地域のボランティアの方を介護予防の事業に配置させていただいているのですけれども、そのボランティアの金額というところのご質問ですが。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなボランティアの方の、募集したら必要な数だけ応募があるという、そのようなことになっているのか、ちょっとその点も伺いたいと思います。それから先ほどの、多分モニタリングのときも私申し上げたような気がするのですけれども、人件費はぜひ、この次は入れていただけるようにお願いをしたいと思います。これから改善をしていただきたいと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"鈴木委員のお話にあったように、人件費のことはぜひ進めていただきたいと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"第８３号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第８３号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら新設の措置ですので、ぜひ進めていっていただきたいと思います。私のほうは１点だけ、質問というよりは希望なのですけれども、この届出を世帯主がしなければいけないということで、周知する方法、先ほどホームページや出産育児一時金支給などというときということでしたが、あと母子手帳交付時など、知らないでもらえなかったということがないように、広く広報に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"例えば出産育児一時金を国保から出すことになるので、そこのところで、これが漏れていたら、何というのですか、この申請が漏れていますよというようなことや、そのような形で漏れのない取組というものは、本人のところに申請してくださいというような形でできることが幾つもあると思うのですけれども、その辺のところの、もしも漏れてしまった場合はどのようにされるのかについて伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"ただ、財源としましては、区のほうでの４分の１の部分が負担という形になります。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは健康保険法の一部改正ということで、今回も、国民健康保険も免除ということが出されたと思うのですけれども、社会保険のほうは、健康保険料と併せて厚生年金も、本人も事業主も免除されるということになっているのではないかと思うのですが、それで免除されても、年金受給時は払ったこととみなして受給できるということで、社会保険のほうはなっているのではないかなと思うのですけれども。","respondent":"池田国保医療年金課長","answer":"今のご質問ですけれども、実はこちらの出産時の保険料の減免につきましては、先に実施されている国民年金の保険料のやり方をまねしたというか、それを継承した形でやっておりまして、実際にはもう２年、３年以上前から、国民年金の保険料については、申請によりますけれども。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"子育て世帯の負担軽減、次世代の育成支援ということでうたっているので、子どもの均等割も無料にすべきなのではないかなと思うのですけれども、それは国会では議論にならなかったのか、分かっていたらお聞かせいただきたいですし、この子どもの均等割の無料化という方向もぜひやっていくべきではないかなと思うのですが、区のほうとしてもそのようなことを声も上げていただきたいと思いますし、もし、国。","respondent":"池田国保医療年金課長","answer":"それとお子様の、要するに出産した後の保険料が、今未就学児までが５割減額という形になって、その後無料になるのかとか、年齢拡大の話とかということでのお話かと思うのですけれども、こちらについては、実際には、私ども品川区としましても、また特別区としましても。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今の課長の答弁で、少し矛盾なのではないかと思うのです。それから、１８歳まで無料化するのに必要な財源はどれぐらいかということで、何回かこれまでも伺って、随分前は１億５,０００万円という、たしかそのような額だったと思うのですけれども、今の段階で、１８歳まで国民健康保険料を無料にするとしたら幾らぐらいかかるかということが、計算されていて分かったら教えてください。","respondent":"池田国保医療年金課長","answer":"そしてもう一つは、国民健康保険料の増額もあるかもしれません。ちょっとはっきりとしないところで、来年の３月ぐらいにはまた新しく積算したいと考えているところです。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これからも求め続けていきたいと思っていますので、ぜひ計算はしておいていただきたいと思います。それで、本当に全国の市長会でも、ずっとこの子どもの国民健康保険料の無料化ということは、今課長が言われたように、どこでも求め続けているので、これはぜひ強力に求めて実現をさせていただきたいし、区独自にも無料化ということを検討していただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"提案","question":"この３施設についても、特別な理由がある場合は公募によらずということで今回も公募せずに、これまでの事業者ということでの提案ですけれども、その特別な理由というものは福祉施設の継続性ということなのかなと思うのですが、それであれば、私は特別な理由というところに、その理由もしっかりと明記していただきたいなと思うのですけれども、その点を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"３施設とも、区と同じ課題認識の下、区全体のことを考えていらっしゃるご提案をいただいたものです。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"心身障害者福祉会館から伺いたいのですけれども、今の移動支援のところでは、本当にぜひそうしていただきたいなと、もっと使いたくても人が足りなくて、実際使える時間まで使えないということをいつも伺っていますので、ぜひ移動支援の従事者を増やしていただいて、そのところで従事者の派遣をするというところで、ヘルパーステーションも開設をしていくということは、本当に期待したいと思います。","respondent":"松山障害者支援課長","answer":"正確には少し難しいのですが、概要で申し上げます。生活介護、５０人定員で、今現在４７名の方が通所されているです。医療的ケアが必要な方は実際１名ですが、そうですね、今２０名ぐらいは重度の方が通所されています。高度障害の方は７名ぐらいだと認識をしております。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"トータルで何人ぐらいの方が、その心身障害者福祉会館の職員体制になっているのか、全体で何人ぐらいということを教えていただきたいと思います。それからあと、心身障害者福祉会館の虐待の報告件数というものはあるのか、相談件数ですね。相談というものがあるのか、調査に入ったことというのはあるのかも、伺いたいと思います。取りあえずそこで、心身障害者福祉会館は以上でお願いします。","respondent":"松山障害者支援課長","answer":"虐待についての相談件数ですけれども、それはございません。全体のはちょっと計算をしないとならないので。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"提案","question":"大丈夫です。相談件数がなくてよかったと思います。発達障害者の９月のモニタリングで、収支のところが赤字になっていたと。それから、先ほど連携体制の強化ということで、様々、この発達障害に関わるところで連携していくということで提案をされていて、それを本当に進めていただきたいと思うのですけれども、具体的にどのような形で連携をしていくという提案なのかも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"発達障害者支援施設の財務状況の評価についてです。こちらは施設というより、法人全体の財務評価になりまして、ただ４０点中２４点ということは６割、６割ということなので、過半数は超えているので、低いということではないかと考えています。安定して運営をしているものです。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"提案","question":"本当にこの連携というものはすごい大事なことだと思うのですけれども、このような場合は、何というのですか、品川区のほうから働きかけて、ここにそのようなことで担ってくださいという、そのような区としての方針というものが必要なのではないかなと思うのですが、発達障害者支援施設ぷらーすのほうからも提案という形になったのか、それとも区のほうから働きかけて今回の提案になったのか。","respondent":"松山障害者支援課長","answer":"区としても、発達障害者支援施設を、きちんと中心的な役割になるということを明示させていただきまして、その後、連携は必要だという認識は区としても持っておりましたので、モニタリング等では、発達障害者支援施設の現指定管理者である社会福祉法人げんきとは。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"確認","question":"世話人について、この資格を問われないということが、もっと本当にきちんと資格が問われるべきなのではないかなといつも思っているのですけれども、結局この勉強会というものがその中でされているということは評価されるものですが、上大崎つばさの家では非常勤の方ということで、人員体制としては、有資格の方はいらっしゃらなくて、資格のない方が世話人の勉強会などに参加されながら。","respondent":"松山障害者支援課長","answer":"世話人の状況です。世話人は、職員体制の中で夜間支援を含めまして８人の方がいらっしゃいます。その中で常勤が３人、それから非常勤が５人という人数です。その常勤の方の中には、介護福祉士の資格を持っていらっしゃる方もいらっしゃいます。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先に、議会といたしまして、１人１００点として４名で計算して４００点、そしてその評価の点数を決めているものというのは、この後ろに別紙である指定管理候補者選定基準の評価項目と配点のところという理解でよろしいでしょうか。それがもしこの内容でよいとしたら、財務状況の評価の、この１人持ち点の１０点分というものは、その別紙についてのどの項目に当てはまるかということも、併せて教えてください。","respondent":"松山障害者支援課長","answer":"こちらのほうにつきましては、報告書については財務状況等の評価というものを加えさせていただいているのですけれども、こちらの評価項目の配点につきましては、もちろん、これ以外１００点満点ということで、１人１００点満点ということで評価項目をつくっているものです。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"提案","question":"そうなってくると、１人が１００点満点で評価をして、提案内容評価のところの３６０点のようなところは点数が合わないと思うのですけれども、ごめんなさい、もしかしたら皆さん違うかもしれないですが、採点表というところも１００点というものは、１人の持ち点の１００点というものは、この別添えのところの表記されているところの１００点で評価されて、それでここに合計されているのかなと。","respondent":"松山障害者支援課長","answer":"この別添えの中の３「管理を安定して行う物的能力および人的能力を有していること」の中の、「福祉サービスを安定的に提供できる経営基盤を有しているか」、この中に、含まれていました。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回、指定管理全般のことで言わせていただいたのですけれども、今のところでいうと、この点数というものはすごくよく分かりやすくて、大体平均６点ぐらいで出ているのかなというところで把握ができるのですが、ほかのところの項目が満点の３６０点にまとめられてしまっていて、どこが高くて低いのかというようなところの理解ができないというところが現状でありまして、特に気になるような項目でいくと。","respondent":"松山障害者支援課長","answer":"独自に福祉部だけ、あるいは課だけということではならないのではないかと考えております。そのところ、企画のほうには伝えていこうと考えています。","id":"exchange-021"},{"speaker":"ひがし委員","kind":"質問・要望","question":"もう１点聞かせていただきたいことは、品川区で統一して、この評価の基準を使われているということだったのですけれども、ほかの区のところなどを調べてみると、点数の差がなかったり、項目が少し違ったりという市などもあるのですが、これは東京都全体でこの項目を使っているのか、それとも品川区がこれを使っているという理解だったとすると、配点のところなど。","respondent":"松山障害者支援課長","answer":"区全体で品川区の指定管理者制度活用に係る基本方針、あとはその実施要領というものがあります。ですから、東京都ではなく、品川区として決めている、大枠決めているものです。","id":"exchange-022"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区が決めているということで理解をしますと、この内容の項目について、例えば５点のところがあったり、１０点のところがあったり、１５点のところがあったりと、確かにこの１５点が入っている経営の実績などというところはすごく大切な項目だから１５点なのだろうなということは理解しているのですけれども、逆に言うと、家族の要望・意見などのところの５点は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"筒井委員","kind":"確認","question":"今回公募方式によらず、現行の指定管理者を選定されたということで、その品川区指定管理者制度の活用に係る基本方針の規定に基づいたということなのですけれども、まず確認として、これ今回の３施設の指定管理者は、今まで、今までというか、令和６年３月まで、５年間今までやっていたということでよろしいのでしょうか。","respondent":"松山障害者支援課長","answer":"品川区指定管理者制度活用に係る基本方針が令和３年度に改定されまして、１５年間は公募によらず、理由がある場合は継続、そのまま公募せず、公募によらずに指定管理者としての選定ができるという規定がありますので、その規定に基づきまして行っているものです。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"それとも、令和４年度末に指定管理期間の終期を迎える施設以外はずっともう、ずっと延長できるということなのですか。","respondent":"松山障害者支援課長","answer":"基本方針によると、１５年までということで指定期間としてはされております。そのため、心身障害者福祉会館については、第１期目は終了したということで、あと２期、３期が残っているです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"逆に言うと１５年まで延長できるということで、その指定管理者の方も、１５年までできるのかなという期待を抱かれてしまうのかなという、今回きちんと選考などしておられるので、緊張感を持たせることもできるのですけれども、もう指定管理者の運営側も、どうせ１５年できるだろうというように見込んでしまうのではないかと思ってしまうのではないかなという懸念があるのですが、もうその点の歯止めというか。","respondent":"松山障害者支援課長","answer":"今回の指定管理期間は令和６年４月１日から令和１１年３月３１日という５年間ですので、また議決いただければ、５年後にはまた予備委員会、選定委員会ということで、外部の有識者も入れてきちんとご審議いただいて、指定管理者候補者として選定し。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"ちょっとまた逆説的になるのかもしれないのですけれども、その１５年たってまた公募をかけなければいけないという状況があるかと思うのですが、結局それ公募で集まる指定管理者の方が現れるのかという、５年後のことなのでどうなるか分からないのですけれども、区としてほかに何か当てがあるというか、何となくこのような事業者があるなというような想定、５年後もし公募に応じなかった。","respondent":"松山障害者支援課長","answer":"そのためには、やはり指定管理、あるいは品川区を魅力的に、今、実際にこの事業をやってみたいというような事業者が今後でてくるように、やはり私たちもサービスの向上を図っていくという必要があります。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"提案","question":"要望なのですけれども、先ほどひがし委員の評価基準や配点についてのことにやはり提案内容の評価のところが３６０点というところですごい大きくあって、ボリュームがあって、財務状況は４０点切り分けられていますけれども、もう少しこの提案内容の３６０点のところを切り分けて、地域交流とか、利用者対応とか、そのように分けていただいたほうが分かりやすいのかなというところと、あと何というのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問・要望","question":"先ほどの評価項目の表のお話を聞いていて、１点ちょっと確認をさせていただきたいのですけれども、配点で５点、１０点、１５点とばらつきがあるという点で、これ、例えば３番の「福祉サービスを安定的に提供できる経営基盤を有しているか」、５点掛ける２となっているのですが、これはこの１行にまとまっていますけれども、実際に私は見たことがないのですが。","respondent":"松山障害者支援課長","answer":"それぞれ項目について、重要だと思われるものについて２倍ということになっております。","id":"exchange-029"}]},{"id":"topic-03","title":"第９１号議案、診療報酬等の返還請求に関する民事訴訟の提起","agenda":"第９１号議案、診療報酬等の返還請求に関する民事訴訟の提起","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これが令和２年１月までの間、看護職員の人員配置基準は満たさなかったということなのですけれども、それ以後は解決して満たした状況で、運営されているということなのか、そのところも伺いたいと思います。それが返還しないということは、病院側の理由としては何かあるのか、その点についても伺います。","respondent":"豊嶋生活福祉課長、池田国保医療年金課長","answer":"どこに該当するかということは、そこまでは把握はできておりません。人数については、生活福祉課分については２名の方が入院をされておりました。現時点では、１名の方は既に退院をされておりまして、１名の方は現在も入院中です。国保の被保険者につきましても、２名の方が入院していたというような形での返還請求という形になります。","id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問","question":"そのような形で、実際加算されていないのに請求していたという不正請求なのに、なぜ返還命令に応じなくて、長い間、９月に返還命令に応じなくて、このような民事訴訟にせざるを得なくなったのか、その病院の言い分というか、何かそのようなものはあるのか、伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"もう１点、訴訟費用についてですが、こちらについては、今後ご議決いただいた後に集団提訴という形になろうかと思いますので、その辺りは手を挙げる他区、それから東京都と十分に協議していきたいと考えております。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ちょっと確認なのですけれども、時効はいつまでということはお分かりでしょうか。","respondent":"池田国保医療年金課長","answer":"こちらのほうですけれども、請求してからの時効については、これは民法第７０３条ということで、１０年間になります。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"実際その報酬の返還分プラス、例えば損害遅延金のような形の請求もされるご予定でしょうか。","respondent":"池田国保医療年金課長","answer":"遅延金についても、請求について考えているところではありますけれども、こちらのほうも各区統一でというようなことも、課長会のほうでは申合せをしています。","id":"exchange-033"}]},{"id":"topic-04","title":"第９４号議案、指定管理者の指定","agenda":"第９４号議案、指定管理者の指定","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"事業費としての提案というものはあったのか、現事業者より高い事業費となるということが提案としてあったのか、その点についても伺いたいと思います。それから、区民の健康増進につながる具体的かつ実現可能な提案ということもあるのですけれども、これは具体的にどのようなことなのか、そのこともお聞かせください。取りあえず、以上お願いします。","respondent":"若生健康課長","answer":"こちらについては、そもそも事業者についてはこれまでも取り組んでいただいているところなのですが、気軽に楽しく利用できる施設といたしまして、フリー料金、これは品川健康センター５００円、荏原健康センター４００円、このフリー料金内で。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"提案","question":"事業費なのですけれども、この事業費が、安い提案というようなところは、選ぶ基準として加味されることがあるのか、その点を伺いたいと思います。それから、指定管理者の利益というものはどのような状況になるのかも伺いたいと思います。インストラクターは正規の職員でやっているのか、その点もお聞かせください。","respondent":"若生健康課長","answer":"むしろ、区のほうで補填をさせていただいているような状況ではあるのですけれども、今後、今年度以降は、見込みとしては利用料のほうが戻ってきておりますので、還元も一定程度出てくるということで見込んでいるところです。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、これは２社でやらないとできないというものなのか、ちょっとそこのところは、住友不動産だったら施設の維持もできるのではないのかなという思いがするのですけれども、それは、なぜこの２社が一緒に管理するということになっているのか、その点も伺いたいと思います。","respondent":"若生健康課長","answer":"それから収入基準額についてですが、こちらについては年度当初の協定のほうで積ませていただいて、利用料金に対して、利用人数を当初見積もりまして、それに対してどのぐらいの来客が見込めるか、どのぐらいの利用があるかというところを、区のほうである程度算定しています。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"本件の指定管理の選定に当たって、その利用料金５００円にするということは区側の求める要件だったのか、それともそういった条件をつけずに公募をかけたのか、その辺り、利用料金についてどういった条件や評価でこれが行われたのか、ご説明ください。","respondent":"若生健康課長","answer":"利用料金の設定に関しましては健康センターの条例で規定しておりまして、その条例に基づいて事業を実施していますので、こちらについては指定管理の公募の要領にもその表記のままで、これは条例を改正しない限りは、利用料金というものはそのまま５００円。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"ではその利用料金という前提の下、皆さんプレゼンをやったということだと思うのですけれども、今回決まった住友不動産エスフォルタ・ＮＴＴファシリティーズ共同事業体ということで、ＮＴＴファシリティーズ、特に財政状況もよくて、資本金１２４億円、従業員数５,１００人ということで、かなり大手なのですが、今回ほかの応募してきた事業者も、会社の規模というか。","respondent":"若生健康課長","answer":"ほかの応募事業者の財政、規模ですか、そういったところになりますが、ちょっと具体のところは申し上げられないところなのですけれども、やはりこれだけの施設を運営するには、それなりの事業規模のところですとか、体力というか、財務的にもしっかりした事業者でないと。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。会議要旨などを見ると、環境、ＣＯ２排出量とか、光熱費削減とか、そうした環境配慮ができるかどうかということがポイントになったのかなと思っているのですけれども、今後、例えば品川健康センター、荏原健康センター、その施設を環境配慮型のものに改修していくということも想定しての、こうした環境配慮にポイントを置いたというようなことなのでしょうか。","respondent":"若生健康課長","answer":"健康センターについては、もう荏原健康センターは今移転して、仮という形で運営しているところで、一定程度環境に配慮した形にはなっているのですが、品川健康センターのほうは、従来建ててから２４年くらいが経過していて、それなりに施設も傷みが出てきているところで。","id":"exchange-039"}]},{"id":"topic-05","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"この期間が今、令和５年の４月から令和６年の３月までということなのですけれども、これまでもされていたと思うのですが、これまでされていた期間というものは、令和５年の３月までだったということなのですか。そこの確認をお願いしたいと思います。それで、東京都は年間１６万円、１６万円ぐらいでしたか、そこの東京都の制度そのものも教えていただけたらと思います。取りあえずお伺いします。","respondent":"若生健康課長","answer":"公衆浴場への支援、こちらは同等の補助を昨年度も、１２月の際に補正予算のほうで提案させていただきました。その際も、令和４年４月から令和５年３月分までということで、１２か月分、休業月は除くという形で、同様の形で支給をしています。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それはよかったと思います。本当に公衆浴場というものはだんだん少なくなっていっていて、今ある浴場はぜひ存続していただきたいと思いますので、このようなことをするのはすごく大事なことだと思います。都全体でも、前回のところでは１３区ということで、さらに増えているのかと思うのですけれども、都全体の状況が分かったら、それも教えていただきたいと思います。","respondent":"若生健康課長","answer":"都全体の浴場の支援ですが、私どもで把握しているところで、７月２０日時点で都内の調査がございまして、その中で把握したところですと、２３区では２３区中１６区、区外のところでは、一部条件あるのが１市のみが補助となっているというような状況を確認しています。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それがこのような形で出されるということは大事なことだと思いますので、このような状況が続く限りは、ぜひこの制度は、来年３月だけで終わりというのではなく、続けていただきたいということで要望もさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"今回、公衆浴場に対して、電気、ガス等の物価高騰の影響を受けたということで、支援を一月当たり１０万円行うということなのですけれども、その１０万円を交付するに当たり、なぜ公衆浴場という特定の業種に対して交付をするのか、ほかの飲食店などもこの物価高騰で大変な影響を受けておりますし、また、私の聞いたお話ですと、アニメーターなどもすごい電気を使うので。","respondent":"若生健康課長","answer":"いずれの業態にも当てはまるところとして、やはりこういった燃料が大量に使用するというところで、そういった物価高騰、特に光熱費の高騰というところが非常に経営に対して打撃が大きいと聞いておりますので、そういったところをまず区としては重点を置いて支援するという考えで。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"やはり、特にそのお仕事において燃料などの料金が大きいところ、その事業をするに当たって、燃料費というものが非常に重要なところを占めるという業種だからこそ支援するという理解でよろしいのでしょうか。","respondent":"若生健康課長","answer":"やはり物価高騰というように、公衆浴場はそのような形でやっておりますので、必ずしもそれは燃料だけを絞ってというわけではないですが、やはりその中でも大きい割合を占めるというところでは、やはり燃料費の支援というところが区としては考えなければいけないということで。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、この支援金はどのようなスキームで支払うのでしょうか。申請があったら支払うのか、一括で組合などに支払われるのか、お願いします。","respondent":"若生健康課長","answer":"こちら補正予算のほうが議決されましたら、まずご案内を全ての事業者、浴場のほうに、これは書面を通して周知させていただきまして、申請については各浴場事業者のほうから直接区のほうに申請をいただきまして、それで一括して。","id":"exchange-045"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら区民の保健衛生の向上のみならず、地域のコミュニケーションの場ともなっていますので、現在も引き続き支援していただきたいと思います。大きく賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"令和５年請願第１７号、パンデミック条約締結及び国際保健規則改正に係る情報開示を求める請願","agenda":"令和５年請願第１７号、パンデミック条約締結及び国際保健規則改正に係る情報開示を求める請願","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"今回パンデミック条約と国際保健規則改正の情報公開を求める請願をお受けしました。２、議員、有識者、その他一般国民から意見を聴取する手段を早期に開始していただきたい。利害ですから、利する側と害する側が両方存在するわけですが、利する側は参加しても、害する側は参加できません。そして、ＷＨＯに最も献金しているのが、利する側の製薬企業の団体であることが、ＷＨＯのホームページで確認できます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"加盟国は公平性を考慮し、備えを促進し、連帯を確保し、国家主権の尊重を含む国際的な合意を求めるとともに、来年の５月のＷＨＯ総会において成果物を提示することを目指していますということで書かれていまして、我が国としては、パンデミックの予防、備えおよび対応、このＰＰＲ、これを強化するために、国際的な軌範や規制を強化することが重要であるとの立場であり、交渉の結果は予断しないものの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"こしば副委員長","kind":"質問","question":"それで、国権の最高機関たる国会というものは、当然民主的な選挙で選ばれた議員より審議がされるわけですから、当然そこには民主主義が担保されていると思いますので、そもそも論、中身をいろいろと説明のほういただきましたけれども、本来この区議会の厚生委員会の場で話す、議論する場にふさわしいかというと、若干そうではないのではないかという印象は、やはり説明を受けましても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"１２月の頭には７回目が行われます。ところが今回、国民の生活に影響が出るかもしれない条約について、一切公表がないのはどのようなことでしょうかと私も思います。不安をあおるというなら、なおさら広く告知し、国民を安心させるべきではないでしょうか。中身がよい悪いといったことよりも、こういったことを広く知ってみんなで議論していただきたいということを求めている請願であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"筒井委員","kind":"質問","question":"記憶に新しいことかと思います。ですから本当に、なぜ今の今までにこのような議論が日本で進んでいなかったということは、非常に問題かと思います、その国会での審議を進めさせるためにも、国会議員に伝えるためにも、また政府に対して意見を伝えるためにも、やはりその条約の賛成反対以前に、賛成反対を意思表明する前提の、もっともっと情報提供、周知が必要かと考えております。私からの意見は以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"確認","question":"おぎの委員に１つ確認なのですけれども、この理由のところにある、先ほどから理由のところにも先進国、途上国というようなお話があるのですが、日本はどちらに該当するのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これはもう、このＷＨＯの話合いの中で、その枠組みで話し合われているということでよろしいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"意見","question":"ただ、先ほど言いました国連加盟国１１か国、反対をしている国がある、そちらの国が、ベラルーシ、ボリビア、キューバ、エトアニア、エリトリアなど、いわゆる、どちらかというとベネズエラ、ジンバブエなど、供給される側の国が反対の署名を国連に提出していますので、実際この枠組みの中で、その枠組みを必要としているのかというものも、発展途上国側の意見だけではなく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問","question":"要旨の部分と理由の部分が結構、個人的に差があるというか、やはりまだ草案の段階というところもあり、そして日本としてのスタンスもまだ決まっていないような状況だったりするところで、ここの理由のところは、何というのですか、まだ本当にこれからどうなるか分からないというようなところは正直感じます。ただ、要旨は賛同できると、個人的には考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"意見","question":"そうですね。今、完成のものはまだ出てきていないので、どこの国でも待っているものは草案です。ただ、草案の段階ですが、決まってからではもう遅いので、広くほかの国のように議論していくことが、日本国内でも重要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"ひがし委員","kind":"意見","question":"ただ、現状で書いている懸念することや危惧することというところは、本当にこのままのとおりだとするなら確かに心配かなというようなところは、すごくお気持ちも分かるなというところなので、その皆様に調べるタイミングと、あと説明の仕方というところ、この決まっていく段階の中で、今すごく国の中でも議論してくださっているというところで、超党派の議連としても協議をしてくださることだと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"鈴木委員","kind":"質問","question":"それで、本当に今回このような形で、今ＷＨＯがパンデミック条約と国際保健規則の改正を検討するということは必要なことだと思いますし、世界的にこのような体制を取っていくというようなことは必要だと思いますので、ここのところで書かれている懸念だったり、何というのですか、先進国の援助義務だったり、そのようなことに対しての懸念というか、否定するようなということそのものが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ちょっとこの要旨と一歩踏み込んだ話になってしまうのですけれども、おぎの委員に確認させていただきたいのですが、この懸念されていることは、このとおり、この理由に書かれているとおりのＷＨＯの条約が可決されて、日本も合意した場合に、最も危険なのはワクチンなどを強制的に日本国民が接種させられるという、そこが一番問題だというお考えでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"意見","question":"後進国への援助を含め、先進国がやっていくという、そちらの責任に対しては、もちろん日本も先進国として援助をしていくべきだとは思いますが、ただ後進国での希望とのギャップ等が出てきているようでは、それはただの押しつけになってしまいますので、この辺含め、国連などでしっかりと、こちらＷＨＯでも審議していただいて、その内容を、今回はこちらの請願の趣旨としましては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"もう一定の皆さんのご意見も出ましたし、態度表明もほぼほぼ出ている状態だと思います。これで意見陳述のほうは必要がないのではないかと判断しますが、皆さんいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"私も今、こんの委員と同じように、おぎの委員の説明でこの趣旨も理解はできましたし、また意見については先ほど私がお話ししたとおりであります。ですから、これ以上の意見陳述は求めなくていいのではないのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"意見","question":"私はこの請願は反対ですけれども、意見陳述は常に聞くべきだと思いますので、意見陳述をしていただいてよいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"筒井委員","kind":"意見","question":"こうした状況でしたら、最初に意見陳述を聞きたかったと思うのですけれども、私としてはせっかく請願を出されて、お越しいただいているということなので、意見陳述の申出を受けたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"おぎの委員","kind":"質問・要望","question":"議会運営の慣例にのっとり、来ていただいているので意見陳述を私は求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そうですね。区民の方の思いがあっての請願ですし、わざわざお越しいただいて、恐らく話す内容もしっかりと考えてきていただいたというようですので、私は区民の声はしっかりと委員会で聴くべきだと思いますので、ぜひお話を聞ければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。ただ、この危惧されている点などについては理解できるところもありますので、その点については先ほどお話あったように国会を中心として国でしっかりと議論をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"鈴木委員","kind":"提案","question":"結論を出すということで、この請願に対しては不採択でお願いしたいと思います。先ほど、第３条のところのことも言われておりましたけれど、そのテキストというのは、加盟国から出されている提案全てを暫定的に書き込んだものであって、今後成案づくりを主導するＷＨＯの検証委員会はその案を採用しないという旨を既に表明しておりますので、主権の侵害ということには当たらないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"おぎの委員","kind":"意見","question":"本日結論を出すで、お願いします。こちら、今まだ素案の段階ですので、内容等含め、決まったものはございませんが、広く国民に周知して議論していくことが非常に大事だと私も考えます。こちらのほう、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"意見","question":"というところで、現状においては、まだはっきりとしたことが言えないというところで、不採択といたしますが、議会としても今後注視していく必要は十分にあると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"}]},{"id":"topic-07","title":"令和５年請願第１８号、補聴器購入費助成制度を求める請願","agenda":"令和５年請願第１８号、補聴器購入費助成制度を求める請願","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"今おっしゃっていた、アンケートの内容というのはいつ頃に決まって、この委員会でもぜひ内容というのは共有していただきたいなというふうに思うのですけど、その予定とかあれば教えてください。","respondent":"川原高齢者地域支援課長","answer":"そのやり取りを経てからお送りをいたしますので、実際の発送は早くても年内か年明けあたりになるかと予想しています。このアンケートの内容の状況につきましては、集計次第、具体の中身を確認いたしまして、またこちらで、実施するかに関しては検討してまいりたいと思います。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問・要望","question":"このアンケートの内容というのもぜひ知りたいなと思うのですけど、どういうふうにそのアンケートの内容を決めていくというのは、今のご説明ですごくよく分かったのですが、この助成を金額上げるとか、非課税ではなくて課税者にも、みたいなことの話をするとき、そのアンケートでどうやって使用していて金額が足りなかったのかとか、今ずっと使っているとか、そのアンケートの内容が分からないと。","respondent":"川原高齢者地域支援課長","answer":"こちらの委員の皆様への公開については、今いただきましたご意見を踏まえまして検討させていただきたいと思います。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問","question":"申請をした人の中でも、何割かの方は、課税者だったから助成がされなかったとか、高度難聴ということもあるのかなというふうに思っているのですけど、今後の見込み、この今決まっている予算というのは３５５万円余でしたか、予算が当てられていて、人件費とかを乗せると大体８０人ぐらいがカバーできると以前説明いただいたと思うのですけど、今度の見込みはどのぐらい増える予定なのかなというのがもし。","respondent":"川原高齢者地域支援課長","answer":"それが８０人分の約半数を少し超えるぐらいですので、今後の見込みとしては、その支出のケースに関しては、その方が医師の診察を経て、補聴器店で見積りをもらうまで、人によってタイムラグが出るので、必ずしも一律ではない形なのですけれども、これから支出を予定している方。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ただ、予算額がやはり、これから先オーバーしてしまうのではないかなという、知られれば知られるほど、やはり受けたいという方も多いのではないかなというふうに思いますし、前回お話しいただいた非課税の高齢者の割合も４万人近くいらっしゃるというところでいくと、その分の３分の１の方が耳の聞こえづらさを感じていて、３分の１となると１万２,０００人、今の８０人の規模の予算だと。","respondent":"川原高齢者地域支援課長","answer":"それで次の予算の組立に対しての、という内容よりかは現行の制度できちんと実施が、効果が図られていたかというのが中心の内容のアンケートとして今は考えているところです。","id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問・要望","question":"７月から実施されて、この補聴器の補助制度というのは、荏原医師会の先生方からの要望としても、たしか平成２７年度ぐらいから要望されていて、長い間ずっと要望されていてやっと実現したし、また認定補聴器技能者の皆さんからも、もうずっと要望されていたものだったと思うのですけど、改めてこれが品川区でも実施されるようになったことを受けて。","respondent":"川原高齢者地域支援課長","answer":"それで、ようやくその実施に結びついたというところで、非常に喜んでくださっていたというところが、私も実感をしています。","id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、東京都からもし半額が出るとなったら、８０人というのはその倍の人数を受入れ、助成ができるというふうなことになるのかなと思うのですけど、そういうことも含めて、もしそれでも足りなかった場合は、補正を組んででも申請者は全員助成しますよという姿勢なのか、その点についても伺います。","respondent":"川原高齢者地域支援課長","answer":"東京都の補助事業の助成に対することなどのご質問です。委員のご指摘のとおり、補助率は２分の１ですので、歳入が約半数、半分、見込みがあるところではありますけど、現在申請をしています。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ、さらにこれを拡大していただきたいというふうに思います。そういう方が、やはり非課税だけということになると対象にならないということに関しては、対象として課税者までというのは、もうぜひ、この高齢者の実態からも必要ではないかと思うのですけど、その点は、高齢者の生活実態というふうなところからしたら、区としてはどう考えられているのかを伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"現行では非課税の要件にはなってしまうのですけれども、今後実施するアンケートでも、その方の購入金額も踏まえて、予算額に例えばそれが見合っていたかであるとか、購入者で、両耳ではなくて片耳のみ購入する方もいらっしゃるので。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、各会派から、請願に賛成しない会派も含めて、住民税課税まで対象にしてほしいという要望というのは出されていると思うのですけど、そういうふうに各会派から、多分、全会派から出されているかなというぐらいな思いがしているのですけど、そういうふうに、各会派から出されていながら、来年度まだ予定がないということで、住民税課税者までやりますよというような方針が取れないのは。","respondent":"川原高齢者地域支援課長","answer":"高齢者の社会参加やフレイルのほうの促進からも、現在は現行のスキームで実施をしていますので、現在のところは実施の予定はございません。今後の見込みに対しても、現在も引き続き検討をしています。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に、これだけ強い要望が各会派からも出されていますし、それから高齢者の実態からも必要だというふうなところで区も認識されているということですし、それから、額的にもそんなに、区の予算でできない額ではないですし、そういう点では、もう来年度、今から検討して来年度やるというふうな可能性というのはあるかどうか、その点も伺いたいのですけど、そういうところで、ぜひ……、言いましたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要望のような形になってしまうかもしれないですけれども、まず、この請願の趣旨、すばらしいなと思いまして、何かというと、２行目のところに、区民としては大変感謝いたしているというところで、やはり、こういった事業が始まったことで、区民の皆さん、大変喜ばれているということで、すばらしい取組だなといった、事業が始まったなというふうに、まず思っております。","respondent":"川原高齢者地域支援課長","answer":"今後のそういった拡充であるとか増額につきましても、現在は全くまだ、引き続き検討しているところでございまして、都の補助事業の内容であるとか来年度の状況も確認するのと、あと、他の自治体も本当にいろいろな要件の設定が異なってきますので、そこも含めて来年度。","id":"exchange-080"},{"speaker":"こしば副委員長","kind":"意見","question":"結論を出すで、今回の請願については、先ほど課長からの答弁にもありましたとおり、アンケートの内容についてまたこれから出てくると、そういった情報をしっかり吟味した上でまた判断をしていくのがいいのではないかと考え、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほど質疑はしませんでしたけれども、先月の決算委員会で我が会派から、民生費のときにこの補聴器の購入についての質問をさせていただきました。そのときに、制度のはざまをつくらないで誰もが対象となるように、そうした体制を求めたところ、区としては、今時点でという答えではありませんでしたけれども、それを検討していきますという前向きなご答弁をいただいておりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すで、お願いをいたします。結果としては不採択でお願いします。先ほどもお話をさせていただきましたが、補聴器の助成というところ、この制度始まったこと大変評価しておりますし申請も増えているということで、今後も使いたい方が使えるように、予算拡大そして対象者、課税者も含めてというところは、ぜひ前向きに検討していただきたいというふうに要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すで、請願に対しては採択でお願いしたいと思います。予定がないということであれば、これは議会でこれを採択して、議会としてそれを求めていくということ、議会がここで採択をすれば区はやらざるを得なくなるわけですから、ぜひ採択をして、これを実施させていくということでお願いしたいなというふうに思っています。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すということでお願いします。そもそも私としては、助成とかには所得制限などかけないほうがよいという考えであり、またこの補聴器が認知症予防等に効果があるというのならば、課税者までの拡大を検討していっていただきたいと考えておりますけれども、一方で税金を使うわけですから、しっかりとそのアンケート等々で効果の検証をしっかりとしていただくと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すで、お願いします。９月末で１５０件申請があったということで、非常に区民の関心が高く、ニーズはあるのかなと思います。１５０人の中でも結局、高度難聴であったり、課税者だったので漏れてしまった方というのもいらっしゃるということで、漏れてしまった方は本当に必要としていたのだろうなと思います。それで、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"意見","question":"先ほど、鈴木委員のご発言のとおり、アンケートと課税者への拡大とはどこまで関係があるのかなというところを思いつつ、ただ、やはり、ほとんどの委員の方は、不採択と言われた委員の方は、アンケート結果を注視というようなことが多かったので、一刻も早くアンケートを実施して、集計をして、それを助成につなげるということをするのが、この委員会含め議会の役割だと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"}]},{"id":"topic-08","title":"令和５年陳情第４４号、品川区立重症心身障害者通所事業所「ピッコロ」移転・拡張に伴い、現在通所できない呼吸器利用者が通所可能になるための整備を求める陳情","agenda":"令和５年陳情第４４号、品川区立重症心身障害者通所事業所「ピッコロ」移転・拡張に伴い、現在通所できない呼吸器利用者が通所可能になるための整備を求める陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"現在のところは生活介護で、人工呼吸器の対応する施設はないと。ただ、八潮南の増改築含めて、これ、今後、人工呼吸器を対応したような施設を増やしていく。つまり、八潮南以外でもいずれ増やしていく可能性があるというような認識でよろしいでしょうか。","respondent":"川崎障害者施策推進課長","answer":"こちら、先ほどもご説明させていただいたとおり、病院とは異なるので、やはり人工呼吸器を使用するというのは、かなり看護師の職員配置、手厚い人員配置というものも求められますので、どの事業所についても、やはりその人材確保というのは大変難しい状況ではあります。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"決まっていればでいいのですけど、どれぐらいの人員の対応を見込んでいらっしゃいますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"こちら、開設が令和９年度になりますので、まだ詳細のところは、現段階では決まってはおりません。ただ、やはり重度の障害者ではありますので、手厚い人員配置というところで考えていく体制ではおります。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問","question":"令和９年となると、まだまだ先かなと思うので、その間の期間に、八潮南の増改築、ピッコロの移転というものの前に、どこかで、人工呼吸器の対応というのを生活介護で考えていらっしゃるという計画は今のところはいかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"現時点では人工呼吸器対応というところで検討はございません。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"やはり、人工呼吸器対応の生活介護の施設があれば、そこで通所できたり、そして、それが活動、仕事などを、そのあることによってできるという方も多くいらっしゃるということで、そういった団体の方からのお話も伺っているので、ちょっと令和９年というところは一つの計画としてはあるとはいえ、少しやはり先だというところを考えると、やはり検討を進めていく必要があるのかなというふうには思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"医療的ケア児者の直近の人数というのを、先ほどの一般質問で聞いたのですけど、そのところで、医療的ケア児者の直近の人数が、１８歳以下が３０人で１９歳以上が４人ということだったのです。これは、４人という人数はあり得ないのではないかと思うのですけど、その点、どうしてこうなったのか伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"もともと前提が、医療的ケア児者の人数については、令和５年２月末現在で、重症心身障害児者等在宅レスパイト事業および障害児支援等の利用者のうち、医療的ケアを要する人数が１８歳以下は３０人、１９歳以上は４人です。","id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だからこれは結局、両方足せないということですか。そこを突き合わせないと、なかなか全部の人数というのは見えてこない部分があると思うのですけど、全体の人数が見えてこないと、今計画つくっていますけど計画の中にも反映できないと思いますので、保健センターとかも突き合わせをしながら、全体の医療的ケア児者の人数というのは把握していただきたいなと思うのですけど、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"病院に入院されている方もいらっしゃいますので、非常に、把握するのは困難ではあります。ただ、保健センターとは、この令和５年２月末現在の数字は突き合わせている、突合しているものです。","id":"exchange-093"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから少なくとも、１９歳以上は人工呼吸器の方が１０人、人工呼吸器というふうに限定しないとなかなか分からないというのが実態ということなのですかね。それなので、ぜひその連絡会は、もっと情報を共有しながら、課題も明確にして、その課題に対してどういうふうに区としては取り組んでいくのかというところの計画を、ぜひ明らかにしていただきたいなと思うのですけど、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"参加される人が医療従事者という方もいらっしゃいますので、なかなかコロナの間、開催するのは難しかったのですけれども、このたび、また１２月の上旬に開催を予定しておりますので、かなり、お子さんから大人まであると幅広い議題にはなってしまいますが。","id":"exchange-094"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国のほうは医療的ケア児ということでの対応ということですけど、でも、医療的ケア児支援法の中には、やはりその医療的ケア児が１８歳に達し、また、高等学校を卒業した後も適切な保健医療サービスおよび福祉サービスを受けながら日常生活および社会生活を営むことができるようにすることも配慮して行わなければならない、支援に対して、そういうふうなことが法律の中にも明記されていますので。","respondent":"松山障害者支援課長","answer":"先ほど申しましたように、令和９年度に移転拡張予定のピッコロにつきましては、人工呼吸器を使用するなど、医療的ケアの程度が重篤な方についても受入れができるよう整備を進めているところです。","id":"exchange-095"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことは本当に、区として早急に取り組まなければならない、区の責務というか、私はそんな思いがするのですけど、そういうご相談を受けてる方から、この方は１８歳まではずっと、高校まで本当に休まずに通い続けてきたのに、もう今、７年たちますけど、いまだに通うところがないために、もう家に閉じ籠もらざるを得なくて、もう本当に、今年こそ何とかしてほしいという願いを伺っているのですけど。","respondent":"松山障害者支援課長","answer":"様々、その方のご事情によって、過ごし方は変わってくるものと考えています。先ほど申しましたように、令和９年度に移転拡張のピッコロについては、人工呼吸器のご利用者が受け入れられるように今、具体的に整備を進めているところです。","id":"exchange-096"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、そういうことで、初めに、人工呼吸器受け入れますよ、酸素吸入の方も受け入れますよという明確な方針を持たないと、後で、これもできていない、これも施設として足りなかったというふうなことになるので、そこのところは、ピッコロがそうやって拡大されるというのは、一つの大きないい機会でもあると私は思うので、そこの方針を明確にした上で整備をしていただきたいと思うのですけど。","respondent":"川崎障害者施策推進課長","answer":"先ほどの答弁の繰り返しにはなるのですけれども、移転拡張するピッコロというのは病院とは異なります。ですので、高度な医療支援の対応というのは難しいところです。","id":"exchange-097"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今のだと、人工呼吸器の方は受け入れるかどうかまだわからないという、そういうことですか。いつまでたっても希望を持つことができないのです。それなので、人工呼吸器は受け入れます、酸素吸入の方も、酸素吸入だからといって断らずに受け入れます、そういうことでピッコロというのは整備しますというところで、確認させていただきたいのですけど、その点は確認できないですか。","respondent":"川崎障害者施策推進課長","answer":"ですので、重度の方もご利用いただけるような整備というのはもちろん、体制は構えます。ただ、人工呼吸器を使用となると、やはり、看護師の手厚い配置というのがありますので、今後、運営する法人の体制にもよります。そこの部分も含めて、今後十分検討していくことになります。","id":"exchange-098"},{"speaker":"鈴木委員","kind":"質問","question":"そうしますと、人員、ハードの部分というのは人工呼吸器の方も受け入れるという、そういうところで整備をするけれども、あとは人員体制が、ここを委託される事業所がそういうことで配置をしますよということで、区との協議が整えば人工呼吸器の方も受け入れる。区としては人工呼吸器の方も受け入れるという方向で事業者と話合いを進めていくと、そういうことでよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"看護師の配置につきましても、全国重症心身障害児（者）を守る会のところで、やはりノウハウがありますので、高度な医療的ケアに対応できるスキルのある看護師を確保ということで、お話は進めているところです。","id":"exchange-099"},{"speaker":"鈴木委員","kind":"質問・要望","question":"守る会のスキルというのは、ほかの自治体でも話を伺って、本当にかなりの重度の方まで受け入れているというのは実態としても伺っておりますので、そういう守る会が、ここのピッコロの委託を受けていただいていますので、そういう点では、区はそういう方針を持てばできるのではないかなというふうに思いますので、ぜひ今回のピッコロでは、人工呼吸器の方ということも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"ひがし委員","kind":"確認","question":"この状況について区として課題として考えているから、このピッコロが拡大することに向けて、令和９年度になりますけど、そのときには、落ち着いていれば人工呼吸器を使っていても、きちんとした場所の確保と人員の確保に向けて区としても取り組んでいるという認識でよろしいでしょうか。その１点を確認させてください。","respondent":"松山障害者支援課長","answer":"確かにおっしゃられるとおりで、健康状態が落ち着いていればというところで、区としては、人工呼吸器の方を受け入れるような具体的な整備を進め、あとは人員配置というのも確保に向けて協議をしているところです。","id":"exchange-101"},{"speaker":"ひがし委員","kind":"確認","question":"その点が確認できて安心しました。特に、この設備面ですか、ストレッチャー型の車椅子が入るだとか、電源の確保というところはもう重要だから、ここについても整備をしているということでお話は聞いております。それで、ソフトの面だと、やはり人材の確保が難しいということで、そこについてやはり予算というのをしっかりとつけていかないと難しいのかなというふうに思います。その１点について。","respondent":"松山障害者支援課長","answer":"委員おっしゃられるとおり、やはり医療的ケアの実施というのは看護師が行うのが基本になっています。なかなか人工呼吸器レベルですと、喀たん吸引の研修を受けた職員の方であっても、そこまではなかなかケアができないという現実があります。","id":"exchange-102"},{"speaker":"ひがし委員","kind":"質問","question":"ということはまだ具体的なところというのはこれからで、看護師の人数とかというところもこれからということですか。","respondent":"松山障害者支援課長","answer":"２０名に拡大した場合については、どの程度、医療的ケアの必要度がある方がどのくらい入られる、通所されるかによりますけれども、看護師としては今、現在、生活支援より多い状態になっておりますので、今後も看護師の確保は不可欠ということになっております。","id":"exchange-103"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点については要望をします。その点について何かあれば一言お願いします。","respondent":"松山障害者支援課長","answer":"医療的ケア者の人数把握についてのご質問です。なかなか、全体を統一するようなシステムは今ございませんので、それぞれのところの所管がどの程度把握し、それを個人の突合がどの程度できるかということになってまいりますので、可能な限り把握することに努めたいと考えています。","id":"exchange-104"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、区として、この人数はどのぐらいなのだろうと思ったときに、聞いて分かるか、せめてこちらが調べられるような状況になっていただくと、必要性とニーズと必要な政策というところも導けるかなというふうに思いますので、ぜひ皆さんで協力してやっていけたらなと思います。こちらは要望で終了とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"こしば副委員長","kind":"質問","question":"結論を出すで、今回の陳情については不採択でお願いします。実際その現場で働く方、看護師の方の負担、またストレス等も考えると、やはりこういったことは医療機関で行うべきところが大きいのかなという認識をいたしました。そういうことを踏まえまして、これからまたさらにこの八潮のほうの環境整備も進めていくですので、こちらのほうに期待をしたいと考えまして、今回の陳情については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"こんの委員","kind":"確認","question":"本日結論を出すで、お願いします。先ほどの質疑を聞いていまして、品川区としては受入れの課題と思っている点が確認され、ただ、そのことについて受入れのために体制整備をされている、また、運営事業者とも協議をされている。こうした、受け入れるための体制づくりは現在も進められているということがよく分かりました。よって、これは不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回結論を出すで、お願いいたします。それで、不採択でお願いいたします。今後も、まだ計画をしっかりと含めて注視をしていきたいと思っているのと、先ほどお伝えしたように、移動中の安全の確保だったり、バイタルサインの異常の早期発見、あとは人工呼吸器の正しい使用ができる人材確保というところ、大変重要だと考えていますので、その点に向けても、前向きに協力しながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは本当に切実な要望のご相談をいただいているので、それを取り上げてきたのですけど、令和９年ということで４年後になるので、その方は１０年間以上、もう本当に家に閉じ籠もらざるを得ないという状況になるのだなというのを、改めて本人の立場に立って考えているところなのですけど、このピッコロのところで、何としてもこれを実現させていただきたいと強く求めておきたいと思います。陳情には賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"筒井委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いします。理由といたしましては、区としても課題を認識されている、そして、今後その整備をされて、方向性としては受入れの方向性ということであります。ただ、人材確保の課題や、その直ちにというのが現実的に困難という事情もありますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すで、お願いします。医療的ケア児は今、通所できる場所がある。でも１８歳以上は、今のところ、人工呼吸器の方とかですと、やはり都の介助のところだったりとか在宅であったりとかということで、本人が希望しているのであればいいのですけれども、仕方なくそうなっているなら整備を進めるべきだとは思っていました。もう既にやるということですので、これに関しては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはり、今のところ人工呼吸器の対応できる施設がないというところで、在宅を希望するか通所を希望するかというのを、どちらでも選べるという体制にするということは非常に大切なことなのかなと思いますし、ただ、その人員がというようなお話も複数の委員からも出ておりますし、そういった事情もあるということは承知の上ではありますけれども、議会としても、こういった整備を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3676#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":83190,"voices":357}},{"id":"r05-20231127-8","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"建設委員会","time":"午前１０時００分～午後 ４時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を128件抜き出しています。","topics":[{"id":"topic-01","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出等 建設委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出等 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"住宅確保要配慮者入居促進事業のほうなのですけれども、今年度、利用が増えているということで、利用が増えた要因をどのように分析されているのか、伺いたいと思います。それと、第二戸越幹線のほうでは、今回、この工事が遅れた理由ですね、そこのところを伺いたいと思います。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"住宅確保要配慮者入居促進事業ですが、こちら、事業開始が令和３年１１月２９日からということで、昨年度は、まだ事業の周知がいま一つだったというところだと思うのですが、徐々に事業が周知されてきまして、それで今回。現在掘削している場所が細砂層でして、ポンプで圧送する圧送管が締め固まって詰まってしまう、閉塞してしまうという状態が起きておりまして、それにより思ったような進捗が出ていないという状況です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、第二戸越幹線のところで、掘り出した土を圧送する際に詰まってしまうということで、こうしたことは事前に想定することができなかったのかどうかというところを伺いたいと思うのですが、今回、工期が延びてしまって、５億円、さらに予算がかかるということにもなっておりますので、そうするとやはり区民の税金がさらに使われてしまうということになりますので。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"なぜ金額を変更したのかですが、生活保護受給者は生活保護扶助の一つである住宅扶助を受給しており、代理納付も進んでいることから、他の属性の方々に比べると、賃貸人にとって入居を可とするハードルが幾分低いと考えられるため。ただ、現在も少しずつではありますが進んでいる状況でございまして、細砂層を抜ければ進捗が戻ると考えておりますので、改善に向けて対策するとともに、可能な限り早く終われるように努めていきたいと考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"第二戸越幹線のほうは、しっかりと進めていっていただきたいと思います。住宅改善工事助成も区民が利用できるように補正予算を今回組むべきだったのではないかと思いますが、いかがでしょうか。なぜ補正を組まなかったのか、伺います。","respondent":"竹田住宅課長","answer":"住宅改善工事助成ですが、こちらは毎年当初予算のほうで増額しておりますので、今回、１０月に打切りとなったですが、昨年も１０月でございました。当初予算で対応しておりますので、補正のほうは今回しなかったという結論です。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"昨年も１０月で受付終了になってしまっているということでは、当初予算として増額しているということですけれども、やはりそれでも足りていないということだと思いますので、そこは補正を組んで利用できるようにしていくということが必要だと思いますが、改めて伺いたいと思います。","respondent":"竹田住宅課長","answer":"事業によって希望の多い・少ないというのは年によって増減がありまして、こちらの事業は２月末までを想定している事業なのですけれども、年度によっては２月末まで執行されている年もありますし、たまたま今年度と昨年度は人気のため早めの終了になったと考えておりますので。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"年によって増減があるということなので、年度途中で受付終了になってしまったら、その分、補正すればそれで対応できると思いますので、そこはぜひやっていただきたいと。これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"住宅のほうです。区と登録不動産事業者が連携とあるのですが、どんな連携をされていて、不動産事業者の方の役割、それと、１件に対して１００万円ですか、１件に対して補助額１００万円と言っていたと、間違っていたら言ってください。その金額の目的というか、何に使われているのかということ。令和４年・５年というばらつき。その方々のご理解というのはどのような傾向になっているのか、教えてください。","respondent":"竹田住宅課長","answer":"連携ですが、区内に大きな不動産団体が２つありますので、そちらの不動産団体にご協力いただいて、会員の方に周知、そして登録事業者になっていただいているです。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"別に悪いことではないです。いいことなのですが、やはりこれは住宅施策という形で、しっかり来年度の予算にはとっておかないと、柱をつくっていかないと、また途中で補正、補正、補正。補正で可能なものについてはいいのですけれども、ただ、もうちょっと柱みたいものをつくって、品川区はやるぞという、やりますよ、安心してねというようなメッセージが必要だと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"そういった中で、賃貸人の方には、今後、対象の方がたくさん増えてくる、また、高齢者の方は若い人に比べて長くお住まいになるという傾向がありまして、一つの調査によりますと、平均１３年ぐらい、一つのところにお住まいになるというような調査結果も出ていますので。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、ぜひ来年度の施策の中には住宅対策というのをしっかり立てて、それなりの金額ですか、予算を立てていただきたいと要望したいと思いますが、後でそのお考えをお聞きします。１点、下流部シールドの件なのですけれども、これ、よく分からないのです。令和６年度に予算はなかったけれども増やしたということで、インフレスライド、いろいろあるとはいえども、この見立てがどうだったのだろうなと。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"福祉のほうも件数が増えていると聞いておりますので、福祉部門とはしっかり連携して、お住まい探しに困る方がないように、区としても連携して取り組んでまいりたいと考えております。金額に関しましては、受注者が決まった段階で、施工方法についてもう少し詳細な検討をしたり、インフレスライドといったものは、当初はなかなか想定できないところもありますので。","id":"exchange-008"},{"speaker":"田中委員","kind":"提案","question":"これは取水工等の工事の関連が要因で９１日延伸するというものでありましたが、今回はそことは違うシールド工法過程で、土質が当初よりも違うものが出たために、管が詰まり、延長せざるを得ないという状況だったのですけれども、８月１６日に専決処分をした時点で、要は取水工の関連で専決処分せざるを得ない、その時点ではまだ今回の土質の状況というのは分からず。","respondent":"北原河川下水道課長","answer":"今回の閉塞する事態に至りましたのが、最初が８月１７日という形になっておりまして、その後、いろいろな対策をしてきたのですけれども、今回どうしても年度内が難しいということで延伸をさせていただいているものでございまして。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、この表を見ると、第１四半期だから、６月末までぐらいには完了する見込みだというご判断なのかなと思えるのですけれども、その辺の見通しと、また、工事のそもそもの必要性は、ゲリラ豪雨対策で、被害を起こさないためにも、一日も早く第二戸越幹線が必要だということで工事していただいているわけですが、再び延期されてしまうことに伴う全体の影響度というのはどのように受け止めていらっしゃるのか。","respondent":"北原河川下水道課長","answer":"委員おっしゃいます延長に伴う全体の影響というのはもちろんあると認識していますので、今後、工夫ができないかというところは、検討していかなければいけないと考えているところです。","id":"exchange-010"},{"speaker":"田中委員","kind":"提案","question":"インフレスライド分だけでいうと、いわゆる変更の場合は、５％以内は専決処分でということでありますけれども、ちょっと詳細が分からないのですが、５億５００万円のうちのインフレスライド分がどれだけなのかということで、それも要は５％を超えるので議決が必要だと捉えて、我々としてはご提案いただいたものに対して捉えるべきなのか、あるいは超えるからなのか。","respondent":"北原河川下水道課長","answer":"今回、補正を行いまして、そしてその後に契約変更、増額の変更を行いますので、その金額が、令和５年の１月１２日に議決している金額に対して５％を超えれば、再度議決が必要になることになりますし、専決処分になった場合も別途ご報告するという形になります。","id":"exchange-011"},{"speaker":"田中委員","kind":"提案","question":"今回は債務負担行為ということでもあるのですが、令和６年度でのまた、当然、慎重審議を我々はしていかなくてはならないわけですけれども、今後、いろいろ質疑をするに当たりまして、シールド到達に関わるコストとインフレスライドは全く別の観点の予算でありますので、今後はぜひ分けていただいて、議会での質疑がより密度の濃いものになるように、そういうご報告、ご提案をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"住宅確保のほうは、事業概要、資料にもあるとおり、高齢者、障害者、ひとり親世帯、それから先ほどありましたように生活保護の方もその対象ということで、令和４年度と令和５年度、１０月までになりますが、それぞれ対象者の件数を確認させていただきたいと思います。それから、シールドのほうは、今、田中委員から詳細な質疑がありましたので、大体これまでの流れの中で承知をいたしました。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"入居促進事業の属性別の内訳ですが、令和４年度の高齢者が５８、令和５年度が５７、それからひとり親世帯が、令和４年度は１、今年度も１、それから障害者が、昨年度が２、今年度が２、低所得者は、昨年度が８０で。シールドが大体９６０ｍぐらいあるのですけれども、そのうち６００ｍを超えたぐらいのところでこういった現象になってあります。今、少しずつ改善されてきてはおりますが、どこまで続くかというのは、分からない状況にあります。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"これは、実働の店舗数・事業所がまだ少ないのだろうなというのをご相談いただいている中で感じているところですので、なぜ今からご答弁いただくような店舗数にとどまっているのか、また、今後ご協力いただく事業所・店舗数を増やすにはどのようにしたらいいのか、また、店舗数がもし増えるという、今後そのような努力の成果が表れるとしたら、先ほど西本委員のお話にもありましたけれども。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"そういったところで登録数に比べて少し少なくなっているですが、今後増やす方策としましては、今、各店舗の入り口等に貼っていただくステッカーを制作しておりまして、図案のほう、どれでいくかというところで最終的な検討をしています。西品川一丁目の大崎ガーデンタワーの前の付近になります。","id":"exchange-014"},{"speaker":"まつざわ副委員長","kind":"質問","question":"当事者と不動産屋だけが知っていても、やはり大家がこの事業を理解していないと、なかなか物事というのは進まないと思っていて、例えばこういった予算は、これは現在は賃貸人とあっ旋を行った不動産屋に協力金を支払うという形ですけれども、例えば大家への周知という部分に、何といえばいいのですかね、もっと広報に努めるというか、そういった予算分というのはこれには入っていないのか。","respondent":"竹田住宅課長","answer":"ただ一方で、大家の意思決定に大きな影響を及ぼしているのは、建物の管理を請け負っている不動産事業者というところもありますので、当面は不動産事業者のほうに積極的に働きかけ等を行いまして、不動産事業者を通じて大家にもご理解いただくというような形を。","id":"exchange-015"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"は不動産業者で、例えばチラシなんかをつくって、そこが大家に理解できるようなことが区で後押しできればいいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"令和５年請願第１６号、リニア新幹線の建設中止を求める請願","agenda":"令和５年請願第１６号、リニア新幹線の建設中止を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、このリニア新幹線、２度目の工事停止という状況ですけれども、７月の時点で、現在と同じ１２４ｍ掘り進んだところで止まっているという状況です。それと、この間、同様の大深度地下工事で陥没事故が起きた調布市の外環道の問題を把握すべきだということで言ってきましたけれども、それは把握されたのかどうか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目の今回の停止の理由ですが、公表されていますとおり、曲線区間での掘進が続く中で、一部に局所的に土がたまってしまいまして、その大きな圧力がスキンプレートを押し、変形させたものと認識しております。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"工事のマシンが壊れてしまったというところでは、点検した際に見つかったということで、もしこれ、点検しなかったら、このまま進んでいたとしたら、どういった事態になってしまったのかと思うのですけれども、区でそうしたところ、想定しているところがあれば、伺いたいと思います。そうした補修をやるために住民が立ち退かされているという状況ですので、補修工事の内容をご説明いただければと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今回７ｃｍ程度のへこみが発見されたですので、点検は予定どおり行ったのかなと考えています。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"調査掘進の間もあるかな。区はほかのところで起こっていることも把握されているかどうか、伺いたいと思います。ほかにも広島ですとか様々なところで起こっていて、振動やら騒音やら、生活がままならないということが起こっておりますので、品川でもそうしたことが起きてしまうのではないかと危惧されますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"ご質問の１点目ですが、今回のシールドが住宅街に出ていってしまったら、地上への影響があるのではないかですが、区といたしましては、そのような事象にならないように、ＪＲ東海に対して引き続き安全対策を求めているものです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"今、外環道のところでも、陥没や空洞が発生した後もトンネル工事などを進める中で、川の沿岸で新たに地面がへこんだりとか小さな陥没が起こっているという状況ですので、さらに地盤が壊されているということになって、今補修をしている住民の方だけでなく、ほかの住民の方も暮らしに不安を抱えているということになってしまいますので、やはりこれは中止すべきだと思いますけれども。","respondent":"大石まちづくり立体化担当課長","answer":"中止することを求めるですが、区といたしましては、リニア中央新幹線は３大都市圏の大動脈輸送を二重系化し、こちら、ＪＲ東海が国土交通大臣から認可を受けているものですので、ＪＲ東海の責任の下に実施されている事業であることから、区は引き続き必要な安全対策を確実に行い。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"なので、やはり中止すべきだということだと思います。そして、そのために、朝の時間帯は通学時間、通勤時間でもあると思いますので、そうしたところで７時半から８時半までは運行を停止するということですが、夕方の下校時など、そうしたところは停止しない理由を区のほうでは聞いているのか、伺いたいと思います。そして、工事車両が６００台通行することで、道路の状況に悪影響はあるのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の中で２４時間の施工を行っていくということは近隣住民の皆様にも周知しておりまして、その中で、２点目の質問になりますが、朝の７時半から８時半というのは、登校時間ということもありまして、運搬はしないというところになってあります。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"事業者のほうで工事車両が１時間当たりどれだけ出るのか説明しているという話でしたが、当初の工事説明会では１時間当たりというのは出ておりませんので、住民の方はあまりイメージできないのかなと思いますので、そうしたところも区として把握をしていただいて、やはり道路の状況にも影響は出るということですので、実際に請願では。","respondent":"大石まちづくり立体化担当課長","answer":"交通に影響が出ることに対しての区の認識ですが、先ほども申したとおり、区といたしましては、ＪＲ東海のほうは、しっかりと影響が出ないように、どういった形で出していくかというのは検討されていると思いますし。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区としても住民説明会を求めていただきたいと。やはりこの工事、２回もストップしているという中で、住民にはそれが直接は一度も説明されたことがないという状況ですから、ぜひ区としてもそれについて説明会を求めていただきたいと思いますが、いかがでしょうか。そうした姿勢でいいのかと思うのです。区としてもそうした対応でよいと考えているのか、これが丁寧な説明と言えるのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"区としてそのような対応でいいのかというご質問もありましたが、説明会の開催というのは当然事業者が最終的に判断するものでございまして、区といたしましては、そういった説明をして区民の不安払拭を果たすことが本来の目的ですので、説明会の開催ということにとらわれずに。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"不安を払拭することが重要なのだと。それはそのとおりで、心配な人がかけてくるだけで各計画地の方の不安が払拭されると、そう考えているのか、伺います。資料の中にも、必要の都度、お知らせをしているということで言われておりますけれども、その必要の都度とはどういうときなのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"２点ご質問いただきました。不安払拭につながるのかというお話ですが、先ほども申したとおり、質疑を受けることに対して、会を開くまたは個別で対応するというところが本来の目的ではないと私たちは思ってあります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、必要の都度というのは、進捗状況ですとか、工事をストップした場合も当たるのかどうか、そういう理解でいいのか、実際に今回お知らせをしているのか、伺いたいと思います。それで、不安払拭に向けて誠意を持って対応するよう求めているということなのですけれども、この間、工事が止まったりしているときに、実際に問い合わせても、まともな回答がないというのが実態なのです。","respondent":"大石まちづくり立体化担当課長","answer":"もう１点、まともな回答がないというのが実態だというお話があったのですけれども、区といたしましては、そのようなことが実際に起きているかどうかというのは認識していないのですが、そのようなことがないように、ＪＲ東海にはしっかりと丁寧に取り組むよう。","id":"exchange-025"},{"speaker":"のだて委員","kind":"意見","question":"今回の工事が止まったことは配布していないということで、必要の都度、チラシを配ったり、住民の方にお知らせされていないなと思いますので、やはり説明会を実施すべきだと意見を述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"見ましたけれども、本当に分かりづらいです。どこを見ればいいのかというのが分からない。これはＪＲ東海の話ですから、区はそれを代弁しているということに過ぎないので強く言えないのですけれども、だけど、区としては、ＪＲ東海の周知方法が果たして区民の皆様方にどれだけ周知徹底されているのかというのは、やはり疑問を呈してほしいなと思うのですが、その辺の周知徹底についての認識を教えてください。","respondent":"大石まちづくり立体化担当課長","answer":"もう１点、ＪＲ東海のホームページが分かりづらいというお話でございましたが、区といたしましては、最終的には事業者の判断になろうかと思うのですけれども、しっかりと住民の皆様が検索しやすいようなやり方ですとか、すぐアクセスできるようなやり方というのは。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"周知徹底のところでは、ぜひ言っていただきたい。皆さんもぜひ見てください。分からないですよ。検索の仕方が悪いよと言われればそれまでなのですが、区民の方々が分かるようにという工夫はやはり努力すべきだと思うのです。結果はどうであれ、しっかり分かるようにしてくれという要望はやっていただきたいと思います。その辺のご意見をお聞きします。","respondent":"大石まちづくり立体化担当課長","answer":"陥没等々発生した場合にも同様の場所での周知なのかというお話でございましたが、先ほど申しましたのは、例えば調査掘進の再開であったり、そういった事象が発生したときに周知する範囲ですので、重大な事故だとか、そういった事象が発生した場合は。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"こういう問題が起きるかもしれないというようなのがあるかもしれないので、そこはしっかり聞いていただいて、説明する場所のエリアというのが本当に今の状況でいいのかどうかという判断は、やはり品川区のほうで持っていただきたいなと思います。なので、それは今回の請願が出たということをきっかけに、ぜひＪＲ東海には申し入れをしていただきたいと、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"結論を出すでお願いします。不採択でお願いします。説明会のお話もありました。先ほど西本委員が言われましたホームページの見づらさというのは確かに十分配慮しなければいけない部分があると思いますので、引き続きＪＲ東海へは、さらなるそういった周知の徹底というか、もっと見やすさを求めるということは続けていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。いずれにしても、区民の生活を脅かすような、そういう工事はしてはならない。あくまでも安全第一で、そして地元の方々、区民の方々に丁寧な説明をしていただくように、区のほうでも取り計らっていただきたいと求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。リニア新幹線はそもそも様々な問題があり、必要ないと思いますが、シールドマシンのトンネル工事が何度もストップしています。建設を中止すべきです。説明会についても、二度も工事が止まっているということを含めて、住民に説明すべきですし、今回の工事ストップのこともチラシを配布していないということ、そして丁寧な説明もされていないと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。請願項目の２番は、住民説明はこれでも足りないぐらいだと私は思っておりますので、お気持ちは私も非常に共感するところがあります。ただ、１番目のところは、建設中止というふうには今の状況としては言い難いなということで、本日は不採択ということにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"前回も同様の方から陳情が出されたとの説明がありました。現場を視察してほしいということで、１月下旬に現場視察の方向だということです。ぜひそこに森澤区長も参加していただけるように進めていっていただきたいと思いますが、いかがでしょうか。新たな意見が出ているという書きぶりかなと思ったのですけれども、こうした意見が出ていることを区はどのように捉えているのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"区長の参加ですが、まずは事務分掌にのっとって、都市開発課のほうで対応していきたいと考えています。勉強会の幹事役の方からのご意見ですが、コロナ禍がありまして、コロナが明けて、こういった形で客足が戻ってきたと。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"Ｃ地区のあるところは、東小路もあって、昔ながらの飲み屋街があるというところで、そうしたところが有名というか歴史的なところにもなっているということで、テレビなどでも紹介されますけれども、こうした東小路の歴史的・文化的価値を区はどのように考えているのか、伺います。","respondent":"中道都市開発課長","answer":"ですので、今はコロナが明けたばかりというところで、ご商売のほう、非常に忙しくされているということは聞いております。一方で、安全というところの今後の権利者の方々の認識というものを、区としては注視していきたいと考えております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"東小路の価値ですね、そこを伺ったので、そこは特に認識がないということなのか、ご答弁いただければと思います。そうした中で再開発が進められようとしてきたわけですけれども、再開発でないと安全なまちづくりはできないということなのか、伺います。この間、繰り返し出されていますけれども、そうした必要な暮らしを奪うものだという自覚があるのかどうか、伺います。","respondent":"中道都市開発課長","answer":"再開発ですが、まずは地域の方々が今後どのようにまちづくりをしていきたいのか、いくのかというところを話し合っていただくことが非常に重要と考えています。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"まちの方々に話してほしいということなのですが、そうした中で、こうした再開発を永久に中止してほしいという声が出てきているということだと思います。この再開発によって暮らしが奪われてしまうということを品川区は認識しているのか、伺います。","respondent":"中道都市開発課長","answer":"再開発によって住み続けられなくなるですが、そこに住んでいる方々、権利を持っている方々につきましては、再開発事業というのは、その権利を今後の再開発が終わった後も維持することができますので、その中で、新しい建物の中で住み続けていただければと考えています。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"るる説明がありましたけれども、再開発というのが権利は残せるというお話でしたが、再開発が進んでいけば、住み続けたいと願っても強制的に所有権を奪われてしまうものだということを区は認識していると思いますが、そこを伺いたいと思います。","respondent":"中道都市開発課長","answer":"所有権を奪われてしまうというところなのですけれども、従前に権利を持っている方々というのは、権利変換の中で、従後も権利を持つことは可能という認識です。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"従後も権利を持つことはできるというお話ですが、それまでには１回権利を奪われると。実際には権利といいますか、所有権を奪われるということになります。その後、実際住み続けられるかといえば、住み続けられない、借家の方は特に皆さん出ていってしまうということになってしまいます。こうした再開発はやるべきではない、私も中止すべきだと思いますけれども、改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"借家人の方々につきましても、家賃の部分につきましては、オーナーの方々とのお話合いの中で従後というのは決まってくるという認識ですが、当該地、一丁目一番地、そこに住み続けたいということではないかもしれませんけれども、周辺の地区に住み続けられるように。","id":"exchange-039"},{"speaker":"のだて委員","kind":"意見","question":"やはりその場に住み続けることはできないということですので、Ｃ地区での再開発はやめるべきだと述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"このＣ地区に関しては、一応エリアというのは決まっているのですけれども、この中で分割的に考えることというのは可能なのでしょうか。ここはやはり一体的に考えなくてはいけないものなのか。そうなってくると、安全というひとくくりでもくくれないし、いろいろな思いがあるので、ここは分割していろいろと開発を進めるという制度はないのでしょうか。そこをお聞きします。","respondent":"中道都市開発課長","answer":"区がここの地域を指定したというところではございません。ですので、地域の方々がこれを拡大するのか縮小するのか、そういったところは今後の話合いを継続した中で、またさらに練られていくのかなと考えています。","id":"exchange-041"},{"speaker":"西本委員","kind":"提案","question":"まだ自由度があるということですよね。だけど、あのままはいかないよねと。火事もありましたしね。ただ、従来型だと補助金の問題があって、恐らく商店街振興、ここは所管ではないのではっきり分からないかもしれませんけれども、そういうものとの組合せという形で、提案できないものなのか、そういう仕組みがつくれないものなのかと思っているのですが、何かございませんか。現状を教えてください。","respondent":"中道都市開発課長","answer":"なので、住民の方が仮に縮小したいといって縮小になったときに、では、それで必ずしも市街地再開発事業ができるかというところは、またそこは検討が必要なのかなと考えています。","id":"exchange-042"},{"speaker":"西本委員","kind":"提案","question":"ごもっともなご答弁といいますか。提案ですよ。こっちで決めるわけではないですよ。なので、品川区としての役割というのはありますけれども、住民主体のというところは分かりますが、住民は制度的なことは分かりませんので、そこをアドバイスしながら、住民の皆さんがもっと広い視野に立ってまちづくりを考えていただけるような、そういう仕組みをぜひ推進していただきたいと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"Ｃ地区におきましては、現在、まちづくりというようなご相談は区のほうには来ていないところです。一方で、地域の方々が都市開発課に来られましたら、そこの部分につきましては丁寧に対応していきたいと考えております。","id":"exchange-043"},{"speaker":"西本委員","kind":"意見","question":"意見ですが、やはり広い視野に立ってください。再開発という意味合いも変わってきているはずです。ゼネコン型の再開発は、成功しているものばかりではありません。ぜひそういうところを参考にしていただいて、住民ともっと、このＣ地区については夢のあるような、そういう地域にしようよなんていうふうに持っていけたらいいなと強く思いますので、ぜひお願いをして、意見として申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"都市計画の法的には、市街化調整区域のようなところは一定の規制が入るわけですけれども、品川区内は市街化区域ですので、このＣ地区も同様の地域ですので、再開発は永久に中止を求めるということも、法律上、できないと思いますが、確認でご答弁をお願いしたいと思います。永久に中止をすることができるのかどうかということです。","respondent":"中道都市開発課長","answer":"再開発を永久に中止ですが、再開発は、先ほど再開発の意義といったところをご説明しましたけれども、そうした様々議論を経て、再開発に見合う計画をつくっていきますので、区のほうで永久的に中止という決定はできないと。","id":"exchange-045"},{"speaker":"田中委員","kind":"意見","question":"そういった視点からは、私は地域の方の安全・安心を守るという視点からは、強制的ではありませんけれども、でも、より地域の、まさにここの人権ということもありますように、人権を守る、生命・財産を守るという視点からのまちづくりは当然必要だと思いますので、たまたま９月下旬の火災はそれほどの被害はなかったわけですけれども、木造住宅が密集する地域としては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"まつざわ副委員長","kind":"意見","question":"結論を出すでお願いいたします。不採択です。こういった陳情は私もよく建設委員会などでお聞かせいただきますけれども、そもそもまちづくりというのは、お話のとおり、住民同士の話合いというのが本来の在り方であって、行政はサポートする側と私は認識しております。その中で、品川区としては十分な話合いのサポートをしているという私の認識です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"来年１月に陳情者等と区のほうで現場視察されるということも今予定されているということで、こういうことも１つのきっかけにしながら、まさに将来のＣ地区のまちづくり、どのようなまちにしていくのか、こういうことを地域の方々みんなでお話をして、まだ決まっていない再開発、その方向に行くのか、別の方向に行くのか、まさに地元の方々でお話をしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。住み続けたい住民を追い出すこのＣ地区の再開発は中止すべきですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。先ほども質疑いたしましたが、行政として永久中止をするということはできないということでありますが、一方で、話合いもまた必要であると考えていますので、そういった視点からも不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"資料について伺いたいのですけれども、今後の予定として、クロス集計、また、自由記述欄の分析を実施するということです。クロス集計では、ルート直下での声ですとか、回答内容を公表するのかというところを伺いたいと思います。そして、１２月をめどに結果を公表予定だということですけれども、ここで公表する中身は、どういった中身になるのか、このときに自由記述欄についても公表されるのか、伺います。","respondent":"辻広報広聴課長","answer":"クロス集計の仕方なのですけれども、フェイスシートということで、その方の年代ですとか地域別のこともアンケートの中に入れておりますので、それを基に、設問ごとに、どの地域で、どういった意見が多いということを集計する予定です。そちらも公表する予定です。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"ある意味、目的といいますか、そのようなところを伺いたいと思います。クロス集計のところでは、どの地域で、どういう声があるかということを公表するということでしたので、ぜひクロス集計の分析をしたところも公表していっていただきたいと思います。そうすると、１２月にはクロス集計のところまでということでしたので、その後の公表は、どういったスケジュールになるのか、伺います。","respondent":"辻広報広聴課長","answer":"１１月以降のスケジュールですが、テキストマイニングを年内ぐらいまでに一定程度目途を立てられたら、年明けに全体のものを公表していくという、そのような予定になっております。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、陳情の中では、こうしたアンケートの経費の内訳を教えてほしいということで求められていますけれども、実際、公費で行われているものですので出していただきたいと思うのですが、予算の事項別明細を見ても、約１億円の委託費ということしか出ておりませんでしたので、ぜひご説明いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"アンケートに寄せられた声は、区長が国に直接届けるということになるのか、ぜひ届けていただきたいと思いますけれども、いかがでしょうか。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"今度は、回答の受領、後納郵便で戻ってくる分で１,２６１万６,０００円という内訳になっておりますが、全体での流れですので、この中で郵便料金が幾らになるかというのは計算はできないところです。アンケート結果ならびに国への働きかけについてですが、基本的には、国との調整ということになろうかと思いますので、この場で区長が必ず参りますと、なかなか断言はできませんが、これまで、前区長が要望に行った際。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区長にも直接行っていただいて、住民の暮らしを守る立場で、ぜひ国にも求めていただきたいというふうに思います。そうした被害を受けている人たちの意見を大切にしていただきたいというふうに思うのです。やはりそうした被害の下で、区民の安全安心な生活が壊されているということですので、やはりそれも国に伝えていただきたいと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"羽田新飛行ルート運用開始以降、区民の方からは、区のほうに直接様々な声を寄せていただいているところです。区では、これまでもそうした声を直接国に届けておりました。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"国にクロス集計も提出をするということで、ぜひそうした区民の直接の声を届けていただいて、羽田新ルートは、そういうことであれば、ぜひ中止をしていただきたい、そういう立場で求めていただきたいと思いますけれども、いかがでしょうか。そして、自由記述欄については、これは公開をするということでいいのか、そこを確認させていただきたいと思います。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"ただ、膨大な量で、個人情報が含まれているかとか、その辺りの観点のところもしっかり精査をした上でということになりますので、少々お時間をいただくことになるかなとは思っております。ただいま検討しています。アンケート結果の整理を今現在行っているわけですが、そうしたところをしっかり整理分析して、国のほうに区民負担軽減につながる取組をしっかり求めていきたいです。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"１つは、分析の方法として、テキストマイニングを使うというふうにおっしゃっていました。デジタル化はもうされているので、分析をする上ではデジタル化をしなければできないので、ですから、そのままできるはずなのです。その上で、区民の人たちの思いというのは、どこまで収集するのかということを確認させてください。区の考え方をまとめなければいけないと思いますが、いかがでしょうか。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"１件ずつ確認しないと、それが公開するのに適した内容のものかというか、本当に出して大丈夫なのかというのは、目検で見なければいけないかなというふうに考えておりまして、一定程度の時間をいただくかなというふうに認識しております。行く前の区民への公表ですが、要望書になるのか、どうなのかということは、しっかり今、検討していますが、その内容については、対国に対してまずは行うべきですので、その要望の内容も含めて、実施状況については。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"分析方法については、いろいろ検討されていると思いますので、区民の皆さんの気持ちがきちんと伝わるように、そうやって時間もかけずにお願いしたいと思います。やはりそこは、せめて議会で議論をするという場を設けてもらわないと、それを踏まえて、国のほうに申し上げるという形にしていただきたいと思いますが、いかがですか。","respondent":"鈴木都市計画課長","answer":"今回行った区民アンケートの結果に基づいて、それを踏まえて、要望、働きかけを行っているということは繰り返しご答弁させていただいているところですので、何かそのアンケート結果から、先ほど勝手にというお話もありましたが。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"これだけのアンケートをとって、皆さんにご足労をかけて、その責任のとり方があるではないですか。その前にしっかりと品川区の中で議論しないと、その結果をどう捉えるかとか、どう考えていくかとか、どういうふうに表現していくのかとか、そういう話合いというのは、やはり議会があるのだから、議会で事前に、国に言う前に、きちんと議論する場が必要なのではないでしょうか、それはいかがですか。","respondent":"鈴木都市計画課長","answer":"正に区民アンケートの結果、区民の声に基づいて働きかけを行っていくですので、そこはしっかり区として検討して、しっかりつくり上げて働きかけを行っていきたいです。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"押し問答になりますので、強く強く要望したいと思います。１番目は、もう当たり前です。２番目、当たり前です。４番目、当たり前ですよね、これ、詳細を出さないと、みんなの税金を使っているわけですから、詳細に出さなければいけないと思います。この１から４番目までに対して、品川区は、いやいや、そういうことではありませんからやりませんとか、反論があれば、おっしゃってください。","respondent":"鈴木都市計画課長","answer":"委員お尋ねのこの陳情裏面の４点についてですが、１番については、正に今、結果について集計中だです。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"この内容は、本当に当たり前だと私は思います。分かりますか。それで、この団体の方々が１軒１軒回っているのです。自分たちで一生懸命気持ちを把握しようということで動いているという動きも考えれば、本当にこれはありがたいなと私は思っていますが、ぜひこれからのアンケートの集計、分析はしっかり考えていただきたいと意見を申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"それを踏まえて、今回の区民アンケートをこれから集計されて、結果が公表されるわけですけれども、では、その区民アンケートの声と議会サイドからの声が違った場合に、区長としてどちらを重ずるのかなどというような野暮な質問はいたしませんが、今後、区長がアンケート調査をして、その結果を、今も少し議論はありましたけれども、議会サイドに対して、それをどういう形で求めてこようとされているのか。","respondent":"辻広報広聴課長","answer":"今回は、区民アンケートということで、羽田新飛行ルートのことも含め、区民の方の生の声を全員の方に細かくお伺いしようという趣旨で実施したところです。その結果に関しまして、先ほど申し上げましたとおり、きちんと集計をしまして皆様にご報告する。","id":"exchange-062"},{"speaker":"田中委員","kind":"提案","question":"なので、今回の区民アンケート、区長のお立場としては、しっかり受け止めていただいて、それをどうするかということに関しては、その後の対応については、議会に対してどういうご提案があるのか、報告があるのか、そういったことも踏まえた中での対応は、４０分の１の議員としては対応していこうと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"これから採決になると思うのですけれども、ぜひそれぞれの会派の方々のご意見をしっかりとお聞かせいただきたいと思います。なぜかというと、１から４番、先ほど私は聞きましたけれども、これに対して、どういうところが不備があったのか、どういうところは賛成するのかということをしてあげないと、陳情者の方々にもご理解いただけないと思いますので、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"まつざわ副委員長","kind":"質問","question":"先ほどお話を聞きましたけれども、１番から４番のお話です。１番に関しては、集計中であって、これからアンケートの結果が出てからでも、そういったことは品川区としても理解しておりますし、２番に関しても、十分に議論を尽くして内容は公平に公表するということであります。３番に関しても、国へこの結果を報告するということもお話を聞いております。４番に関しては、広報広聴課長からも聞きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。その責任の中で、しっかりと国に対して区民の声を届けるということを最後までしっかりと行っていただきたい。その後のことについては、私たち、また区民も、様々な感想、意見は、それは申し述べる機会もあるのだろうというふうに思っておりますので、そういった意味で、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"木村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。本当に地域住民の皆さんにとってみれば大変なことでありますけれども、国がやろうとしていること、あらゆることに対して品川区は何ができるのか、それに対してはしっかりとこれから議論をしていくべきだと思っています。現在は不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。今回の区民アンケートは、住民の皆さんが住民投票をやってほしいということで署名をしてきた。その中で区長としては、そうではなくて、アンケートをするべきだということでやってきたもので、住民の運動の１つの成果だと私は思っておりますので、アンケートを実施することはいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、採択でお願いします。不採択の場合にその理由もということで、皆さんにお願いいたしました。今のところは私のあとに田中委員がいらっしゃいますけれども、聞いていますと、この１番から４番のこの４つの項目に関しては、皆さん賛同していると私は見受けられました。そう捉えました。本当は採択という形で認めていただきたいところではありますが、意見として最後に申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すべきということで、理由は先ほど申し上げましたけれども、区民アンケート調査結果を踏まえた意見は議員として述べるべきではない、取り扱うべきではないという視点から、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問","question":"その下で、今、どんどん進められて、自分のところにも調査が入るのではないかということで不安を感じ、睡眠薬を服用されている。今、組合設立に向けてやっているということですが、令和４年７月に、この２つの再開発、都市計画決定をされたということで、今、１年以上たっているということになりますけれども、予定から進捗が遅れているのではないかと思うのですが、そうした理由を伺いたいと思います。","respondent":"中道都市開発課長","answer":"今まで準備組合が地域の方々に説明なりしておりますけれども、こうした中で権利を持っている方を追い出すといったことは発言はしておりません。その資料も区は確認しておりますので、そうした事実は特にないというふうな区の認識です。２番目の組合の設立などですが……。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"今、組合設立に向けての検討をしているというところで、実際に進めるかどうかというところも検討されているというご答弁でしたけれども、そうすると、進めない、中止をするということもあり得るのか、そういった検討はされているのかというところを伺いたいと思います。そうしたことがやはり追い出すことになると私は思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"もちろん都市再開発法の中で３分の２以上の同意がなければ、この事業は進まないですが、繰り返しになりますけれども、まちづくりに対してより多くの方の同意をもって進めていきたいというところで、今現在、お話合いまたは検討がされているところです。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"私は言えないと思いますけれども、そこを伺いたいと思います。先行して行われた２つの地区がありますけれども、この陳情の中では、本移転者ということで書いてあると思うのですが、これが地権者で戻ってきた人ということだと思いますけれども、区は、この人数を把握しているということですけれども、個人情報を理由に公開しないということで、なぜこれが個人情報に当たるのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"都市再開発法の中で手続が行われているものですので、区としましては、そこの部分は法令に遵守して進めていきたいというふうに考えてあります。法律の在り方につきましては、国のほうで議論されるべきものという認識です。","id":"exchange-073"},{"speaker":"若林委員","kind":"意見","question":"委員長、もう１回。今も傍聴人からの発言がずっと続いております。先ほど、委員長から退場に関するお話もございました。先ほど、私が手を挙げたきっかけは、議会に対して、正に看過できない発言だったと思います。ぜひ、この委員会の質疑が円滑に進みますように、適正な委員長としての職権を発揮していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"法令に遵守して再開発を進めていますということですけれども、法律なので、それを変更するのは確かに国でやることだと思いますけれども、その運用のところでは、区でも、ある程度できるところがあるのかなという気もしますので、そういったところは努力をしていただきたいと思いますし、そうすると、法律のほうに、この二者択一が、選べる自由がありますよということで書いてあるということなのか。","respondent":"中道都市開発課長","answer":"法令に遵守というところで運用の部分で努力をしていただきたいですが、区といたしましても、３分の２をクリアしたからすぐに事業を認可するというところではなくて、繰り返しになりますけれども。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"今、パルムのほうの地権者の数をご説明いただいたと思うのですけれども、駅前地区のほうも内訳がありましたら伺いたいと思います。その中で商店街が、パルムビジョン２０２２を作成されたということで、この中身、どういった内容が書かれているのか、伺いたいと思います。今後どうなっていくのかということがやはり心配されていると思うのですけれども、区の認識を伺いたいと思います。","respondent":"中道都市開発課長","answer":"再開発の中止という件ですが、まちづくりにつきましては、地域の方々で進められてきているものという認識ですので、区のほうで中止する考えはございません。","id":"exchange-076"},{"speaker":"のだて委員","kind":"確認","question":"組合とは交流をしているということで、合意されていると、区の認識のようですけれども、やはり正式には確認をされていないということで、やはり知らない人もたくさんいらっしゃるという下で、商店街もそうですし、住民の皆さんもそうですけれども、合意をしないうちにどんどん都市計画決定とか手続が進んでいくということが、やはり再開発の悪い部分。","respondent":"中道都市開発課長","answer":"発案者５名ですが、準備組合を設立する際は、総会を開いて、その中での合議制で準備組合を設立するというところ、または、その中での理事を務める方は地区内の権利者の方です。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問・要望","question":"事務局をＥＬＣ株式会社はしていたということで、そうすると、発案者には入っていないということなのか、そこのところを確認させていただきたいと思います。","respondent":"中道都市開発課長","answer":"一方で、今現在、区は、まちづくりニュースなどを発行して、今現在の状況を、どのようにまちづくりが進んでいるかというのは、過去数年からずっと周知は行っておりますので、よりそういったところで地区の様々な方に周知されるように努力していきたいと考えています。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方が住み続けられないということになって、住民合意がない中で進められるからこそ、こうした請願・陳情などが、これは武蔵小山だけではないですけれども、様々出てくるということになっていると思いますので、こうしたまちづくりというのは、やはり住民合意をしっかり徹底していくということがまちづくりの基本だというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"アーケードがなくなるかもしれないという具体的な話が出てきましたけれども、アーケードはなくなるのですかということと、それから、地権者の中の３分の２が同意すれば再開発は進みますよね。それ以上にということで努力されているという話は分かりました。現時点で、この該当する地権者の方々の合意はどれだけとれているかという把握はされていますか。","respondent":"中道都市開発課長","answer":"アーケードの件につきましては、アーケードは、今現在、商店街が権利を持っているというところで、こういったまちづくりを行っていく中で、やはりアーケードを触っていきますので、そこの今後の取り組み方も、きちんと商店街組合と協議をしながら、今。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"あの商店街は、やはりアーケードがあって本当にいいというところでもあるので、そこは地元の方々が意見交換しながら決めていくということだと思いますので、なるべく存続していただきたいなという、これは私の要望です。地権者の方が３分の２以上、本来は１００％賛同していただくというのが希望なのです。３分の２以上の方々が賛同しています。今後の進め方について、相関を教えてください。","respondent":"中道都市開発課長","answer":"すみません、一部修正といいますか、先ほど、３分の２以上の賛同という話をしましたが、やはりお話合いの中で、まちづくりに興味があるとか、そこはきちんと白黒つけている話ではないので、今現在、３分の２以上ありますということ、それをきちんと把握しているかというと。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"３分の２、まだはっきりした意思表示は確認されていないというところでありますが、ただ、これはしなければいけないでしょう、もうそろそろ。先ほども言いましたけれども、都計審ではもう決定が出ている部分もあるので、この地域については、建設委員会を含め、いろいろ議論をして、そういう方向性にというふうになっている状況ですから、あとはもう残されるのは何かというと、条件整備だと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"結論を出すでお願いします。午前中、大井町の話も出ましたけれども、繰り返しになってしまいますが、まちづくりというのは、住民の話合いが、もともとの基本でありまして、今回でも、昨年度４月から都市計画の決定から１年あいている中で、区としては、サポートできる範囲で、より多くの区民の声を聞くために動いているというお話も聞けました。引き続きできる範囲は丁寧にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。商店街の合意形成も曖昧ですし、住民を追い出す小山三丁目第１地区、第２地区再開発は中止すべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。課長のこれまでの発言や委員会でのご様子を伺うと、こういうことを言うような方ではないと確信しておりますので、そういった意味でも陳情者の方の何か誤解から生じたものではないかという思いがしますので、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、防災について様々書かれておりますけれども、品川区も、これまで不燃領域率が７０％になれば燃え広がらないということでご説明されてきたというふうに思いますけれども、その確認と、実際、この陳情の中で、戸越五丁目、六丁目、西大井六丁目は、不燃領域率が６０％または６５％を超えているところもあるというところで、燃えにくい街並みになってきているというふうに思うのですけれども。","respondent":"小川木密整備推進課長","answer":"今、こちらの陳情書の中にもあります各町目の不燃領域率に関しましては、６０％を超えるものもありますが、まだまだ道半ばというふうには認識しておりますので、７０％を目指して、引き続き建物の不燃化促進等について取り組んでいきたいというふうに考えてあります。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"そうした下で、やはり交通の円滑化のために住民の暮らしが壊されるということは、あってはならないことではないかというふうに思いますけれども、いかがでしょうか。","respondent":"小川木密整備推進課長、鈴木都市計画課長","answer":"最初のご質問ですが、やはり面的なまちづくりで影響が大きいというご質問等だと思いますが、こちらは、建物の不燃化を促進することで、個々の建物に関しても、燃えない、燃えにくい建物ができるわけですから、そういった意味では。やはり特定整備路線は密集地域、道路が狭い地域で進められているところもありますので、そうした狭い道路への交通流入も防ぐと。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"防災の面は、私の質問が悪かったのかもしれませんが、面的にと言ったのは、耐震化、不燃化をどんどん進めていけば、不燃領域率が７０％になって燃え広がらなくなるということで、面的な耐震化、不燃化を進めていくことこそ必要ではないかということで伺いましたので、ご答弁いただければと思います。","respondent":"小川木密整備推進課長、鈴木都市計画課長","answer":"面的なまちづくりの観点からですが、委員おっしゃられるとおり、面的なまちづくりの観点からも、この耐震化、また不燃化の促進は、非常に重要なまちづくりというふうな観点で捉えております。都市計画道路、道路ネットワークというものにつきましては、その道路単体の整備で円滑化を語るわけではございませんで、やはり都心部全体のネットワーク形成の中で交通の円滑化が整理されていくというところでございまして、当然ながら。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"この周辺の大きな道路、どこでも減ってきているという下で新たな道路は必要ないというふうに私は思います。立体的なパースとかも出してもらえないということで、住民への大きな被害もある中で、しっかりとした説明もされていないという状況ですけれども、区としては、こうした住民への被害、影響をどのように捉えているのか、伺いたいと思います。それまでは暫定活用が可能だということなのか、伺います。","respondent":"鈴木都市計画課長、小川木密整備推進課長","answer":"陳情にもあります買収用地の公園、福祉施設等の諸施設の設置ですが、基本的には、都市計画道路内、しかも事業中の道路内ですので、法的にも、一定程度の大きさの建物、一定程度というか。そこの用地に関しましては、今年度末までの許可期間をいただいておりまして、東京都との協議の中では、毎年度、１年間の許可の更新という形で使用するという形で取り交わしているものなので。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"商店街のところは、ぜひ継続的に暫定活用できるようにしていただきたいというふうに思いますし、実際この道路が、いつできるのかというところは、事業期間中、令和８年３月３１日ということでしたけれども、令和７年度中ということだと思いますが、そこまでにあと約２年ということですから、その下で、今、先ほどご説明いただいた用地取得率でも、１区間のみ５０％を超えているという状況です。","respondent":"鈴木都市計画課長","answer":"今後も、東京都と、あるいは地域と連携をして、防災性の取組を進めてまいりたいです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"ならないと思うのですけれども、そうした下で住民の暮らしが壊されていくということは、やはり区として住民の暮らしを守る責任があると思いますので、中止を求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"そもそも論から教えてほしいのですが、この補助２９号線、これ、もともとは都市開発道路だったのですよね。そうではありませんでしたか。なので、その中で規制緩和といういろいろな優遇措置があったと思うのですが、まず、そこから、そして、この補助２９号線を、東京都の考え方なので品川区はどこまでお答えになれるか分からないのですけれども、選ばれた理由は何かお分かりだったら、教えてください。","respondent":"鈴木都市計画課長、小川木密整備推進課長","answer":"用地の買収につきましては、これは当然ながら、道路を整備していくわけですので、その中に最終的には、やはり皆さんに交渉に応じていただいて、土地を譲っていただいて、１００％の中で最終的に道路が開通していく。今後の整備地域の見直しにつきましては、上位計画の見直し等の中で、今後、検討してまいりたいというふうに考えてあります。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"補助２９号線が選ばれた理由が、多分そういうことだと私も認識しているのですが、都市計画道路ですか、それを指定したときに、その沿道の方々に対しての優遇措置があったと思うのですけれども、どうなのでしょうか。そういう認識は、皆さん、どうなのでしょうか。私は、住まわれている沿道の方は、ある程度ご理解していただいているのかなと思っているのですが、いかがでしょうか。","respondent":"長尾建築課長","answer":"都市計画道路での優遇措置というお話ですけれども、計画道路、都市計画決定の段階ですと、建築の制限はかかっているのですが、現在でいうと、木造であるとか、鉄骨造であるとか、３階建てまで。","id":"exchange-093"},{"speaker":"西本委員","kind":"確認","question":"ですから、私は、条件付で、ここの補助２９号線沿いに生活されている方は、そういう条件で過ごされていたのではないかなと思うのです。建築するときとか。それを確認したいのと、そういう指定がある、そしてまた今回、名前は違いますね、特定整備路線という名前は変わったにせよ、いずれは返してねということではなかったのかなというふうに思うのですが、いかがですか。","respondent":"長尾建築課長","answer":"都市計画道路の範囲内にかかっている土地で建物を計画される場合は、都市計画法の第５３条の許可手続が必ず必要になってきます。その中で、先ほどお伝えしたような建築計画の条件がクリアできているかというところが確認されています。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"この経過は、やはりきちんと説明したほうがいいと思います。忘れているのではないかと思うのです。品川区がやるべきものではないと思うのですが、そこはやはり東京都のほうにも、そこからの説明が必要なのではないかと思いますが、いかがですか。","respondent":"鈴木都市計画課長","answer":"１点、先ほど、私、昭和初期の都市計画決定とお話ししましたが、修正させていただいて、昭和２０年代の都市計画決定がなされて、委員ご指摘のとおり、もともと計画の位置づけが全くないところに、東京都として道路を入れますよということではございませんので。","id":"exchange-095"},{"speaker":"まつざわ副委員長","kind":"質問","question":"結論を出すでお願いします。不採択でお願いします。いろいろな説明の中で、区としても必要と考える特定整備路線、この中において、陳情項目には当てはまらないと考えています。それで、３つ目の暫定活用につきましては、やはりなかなか道路の工事が進まない中、暫定活用は引き続き続けていただけたらと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。住民を追い出し、生活を壊す補助２９号線などの特定整備路線は中止すべきですし、買収用地の活用も進めるべきだと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。先ほども意見を申し上げましたけれども、原点に返って、なぜこの道路が選ばれたのかという歴史的経過が分からなくなっている部分があると思うので、しっかりそこを説明していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すべきで、不採択でお願いします。特定整備路線の必要性は厚く感じておりますし、これは基本的には都の事業でありますので、都が主体的に事業を進めるべきだと思います。区の立場では、特段何を言えるはずもないのですが、区民の声を都に伝えていただく中で、一人でも多くの、一刻も早い地権者の理解を得て事業が完成するように、側面からご尽力いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の陳情で、説明会を求めてほしいということですけれども、先ほどご説明があった中で、チラシですとか、ニュースレターが、チラシは配布されている分もあるというところですけれども、実際、このチラシが計６回配布されたということですが、昨年の９月が最終ということで、それから配布されていないのかどうかというところと。","respondent":"鈴木都市計画課長","answer":"委員ご説明のとおり、国が新飛行ルートの運用を進めていくということを公表して以降、国のほうで、オープンハウス型説明会、それから、区内では１３地域センターで行っていただいたところですが、区では、これまでも様々な方法で区民の方への情報提供、周知。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"運用実施の前には説明会をやってきたというところで、運用を始めたら、もう住民は関係ないと、言い過ぎかもしれませんけれども、そうしたことであるならば、それは許されないというふうに思いますので、ぜひ国としても説明していただきたいと思いますし、区としても、それを求めていただきたいというふうに思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今後の検討会の検討状況、今後、具体的な内容が明らかになっていくと思いますが、そうした中で、区民の方への説明は、やはりこれまでどおり、様々な手法を活用して、国のほうで丁寧に行っていただくように、区としては求めていきたいです。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、住民が知りたいのは、やはり品川区の上を飛ぶのか、被害がなくなるのかということが一番だと思いますので、そうしたところで、恐らく検討会の資料を見ても、それは分からないと思いますので、そうしたことが実際にやり取りができるように説明会を実施していただきたいというふうに思いますし、固定化回避検討会の中身としては、私は。","respondent":"鈴木都市計画課長","answer":"１点目の具体的な解決策というお話ですが、まず、国が今、実施している固定化回避検討会につきましては、現在行っている新飛行ルートを固定化せずに、違う方法がないかというところを技術的に検証していただいているところです。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした下で、やはり都心を低空飛行するという新ルートは、やはりやめることが一番の解決策だと私は思いますので、ぜひ区としても、中止をするという立場に立っていただきたいというふうに思います。この陳情では、教室型説明会、今の状況がどうなっているのかということも含めてだというふうに思いますけれども、求めておりますので、ぜひ実施をしていくべきだと意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"周知方法について、この(2)「品川区の皆さまへ」というものがありますが、これはもちろん分かっております。それから、この第５回検討会から約１年間以上なされていないというこの事実をどう捉えていますか。いつまで待つのですか、１年間以上。放ったらかしですか、品川区。いいのですか、これ。１年以上ですよ。品川区は何もアクションしないのでしょうか。お答えください。","respondent":"鈴木都市計画課長","answer":"固定化回避、委員ご指摘のとおり、前回、第５回の検討会の資料の中でも、次年度、令和５年度の夏から秋にかけてというところで記載されておりますが、もうすぐ１２月に入ってしまうというところで、その辺は、東京都のほうで定期的に行われている関係区市の連絡会の中でも。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"チラシを確認していただきたいのです。うがった見方をしてしまうような状況をやっているなというふうに私は個人的に思っているところがあるので、ほかの区はどうなのでしょうか。それは少し不信感があるので、ぜひ確認をしてください。品川区はそれでいいのですかということです。どうなっているのですか。私たちは、その生活を何とかしなければならないという思いがあるわけではないですか。","respondent":"鈴木都市計画課長","answer":"固定化回避検討会の実施時期については、委員ご指摘のとおり、夏から秋にかけて実施したいというところから大分遅れが出ているというところは、区としてもしっかり認識しているところでございまして、その辺りは、第５回目が昨年８月に実施されて以降。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"今は品川区サイドのお話だったと思うのです。この羽田新ルートの担当は建設委員会です。そこはある程度もう決着をつけてもいいのではないですか。もう１年以上もたっているわけですから、やはり区議会として、早く進捗状況を知らせよというのは、議会から発言してもいいのではないかと私は意見として申し上げたいと考えています。皆さん、それを踏まえての審議をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"まつざわ副委員長","kind":"質問","question":"継続でお願いいたします。国としてのオープン型説明会、そしてまた、１３地区の地域センターでの説明があるとお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"若林委員","kind":"意見","question":"継続でお願いしたいと思います。６回目の検討会がそろそろ開かれる時期、また、このたびは、先ほどもありましたけれども、区民アンケートに関連して、その声を羽田については、区が直接、国のほうに届けていくということもありますので、いわゆるこの説明の仕方については、しっかりと私どもも注視をしていきたい、こういう趣旨で継続で結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"木村委員","kind":"意見","question":"継続でお願いいたします。以前の空路に戻せというようなこともいろいろ言われておりますけれども、それと、現在との、私は両方うまくつくっていく、今のルート、新しいルート、そして以前のルートと、これをうまくかみ合わせた新しいルートをつくるべきではないかなと、これは勝手な私個人の意見でありますけれども、今回のこの陳情に対しては、継続でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。前回検討会が行われてから１年以上経過していますし、区民に説明がないということで、説明会を開くべきだということで採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、採択でお願いします。なので、品川区議会としても、早く説明をしろと、どういう状況か進捗状況を説明しろと強く申し上げるのは非常に大切なことではないかと思いますので、私は、今後、品川区としても強く態度を示していかなければならないということを強調させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。やはり全体の国政の立場で、こういう自治体間をまたぐような事業については、特に、空港に関しては国政マターだと思いますので、国会あるいは国土交通省においての判断だと思いますので、そちらにぜひ直接思いをお伝えいただけたらというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"この資料にも、お休み石がベンチということですけれども、これ、ちょっとひと休みできるということで設置をされているということで、区としても、このベンチの役割は認識をされているのかなというふうに思いますけれども、その点についてご答弁があれば、いただきたいと思いますが、今回、区内で２８９基、設置されているということで、先ほど、区民の声から。","respondent":"鈴木都市計画課長","answer":"１点目のお休み石をベンチとの認識を区として持っているかですが、先ほどご説明したとおり、やはり区民の方が、まちを歩く、移動する過程において、街中でひと休みできるようなスペースが必要だというところで設置を進めてきているところです。","id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、どういったところに設置するのがいいのかなと考えると、急な長い坂のところとか、ずっと上り続けることがしんどいというところとかに設置していっているところもあるのかというふうに思うのですが、この間、住民から要望があったところは、そういったところもあるのか、どういう場所の傾向があるのか、伺えたらと思います。","respondent":"鈴木都市計画課長","answer":"平成８年度から行っていまして、実際、要望いただいて断った事例がどれほどあるかというのは、詳細にまでは、私、把握してないのですが、例えば区道で歩道がないところで、その道端に置いたら休めるのにという声をいただいても。","id":"exchange-114"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり様々な区民要望があって、この間、設置をしてきているということだと思いますけれども、先ほど、バス停のところにはどうかということで伺ったので、そこだけ伺えればと思いますが、やはり様々、場所の条件としては、課題があるところもあると思いますが、こうした安心して出歩けるという面では、高齢者だけではなくて、陳情にもあるとおり、小さいお子さんがいる方ですとか。","respondent":"鈴木都市計画課長","answer":"品川区独特の取組、独自の取組で、２８９基の区民の方が休んでいただける整備というのは、他区と比較しても、非常に、そうしたスポットの整備が行われてきたのかなという認識です。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問","question":"積極的にお休み石等を設置をしていただいているということはすごく理解をしておりますが、設置する条件として改めてお伺いしたいのですが、６１基が公園、広場等にあるということで、ここは設置しやすい場所だなと思いますが、道路に２２８基ありますが、道路といっても、どんな道路でもいいわけではなくて、いわゆる歩道だと思うのですが、歩道であれば設置できるということで。","respondent":"鈴木都市計画課長","answer":"恐らく歩道がないところの設置の申請を行っても、そうした占用許可、やはり通行上支障があるということで、占用の許可が下りないのかなです。","id":"exchange-116"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味で、すごく積極的に設置いただいているということは理解している上で、先ほどの議論にもありましたが、バス停のところに設置をという、確かに声はあるかと思いますが、やはりバス停がどこに設置されているかが大前提で、要は、バス停が歩道にあるところであれば設置しやすいですし、歩道のないところにあるバス停には、これは設置はしたくても、していただきたいという要望があったとしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"木村委員","kind":"質問","question":"今、区内には、２８９基の椅子があるということをお聞きしました。これ以上は、品川区内では増えるという予定はないのか。何となくそういう人を見ると、私もほっとするわけですけれども、そういう方々のためにも、１基でも多くつけられるようなお考えを、今、２８９基と言っていましたけれども、それ以上増やす予定はないのか、そういう点についてもお聞かせください。","respondent":"鈴木都市計画課長","answer":"今後の設置増についてですが、基本的には、事業立ち上げ当初、一定、毎年計画的に増やしてきたというところの、例えば、今後、毎年５基、１０基という予定は今のところないのですが、基本的には、もうしばらく維持管理、修繕のほうに力を注いでいきたいですが、一方で。","id":"exchange-118"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。陳情には品川区は圧倒的なベンチ不足と書いてありますけれども、平成８年度から、他区以上に、このしながわお休み石という部分で２８９基、区民の皆様の要望から始めたこのお休み石の設置という部分に関しては、ベンチ不足ということはないと感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出したいと思います。平成８年度からということで、思い返してみれば、本当に一時期、お休み石というご相談もたくさんいただいた記憶がありまして、つけられたところ、設置できなかったところ、本当に様々です。今後もこういう方向性で進んでいっていただきたいなと思いますけれども、ここには区のほうで精査をしというような表現もあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"今は、改築というか、それをしている時期だということで、やはり２８９基ありますので、当然それは、いずれにしても老朽化してきますから、それを改築しなければいけないということは当然ながらありつつも、必要があったら要求をしていただいて、できれば区民の皆様方と一緒に設置をするというのは、これからも続けていただきたいなというふうに思っております。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。内容は、趣旨採択で。区のご尽力は評価した上で、陳情者、設置条件がどういうところにできるかできないかということは理解されない上での、ただ、健康面、高齢者の方等々の対応ということで設置を求められておりますので、趣旨としては、その方向性に合っていると思いますので、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"田中委員","kind":"意見","question":"苦渋の決断として、条件はどうしても、設置条件の中では最大限やっていただいているという判断をしますので、不採択で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"事故があったところは補修されたということで、よかったと思いますので、今後、気をつけていただきたいと思います。今回の転倒事故や和解に至る経緯を伺いたいと思います。損害賠償額については、慰謝料や休業損害等ということで書かれておりますが、その内訳を伺いたいと思います。","respondent":"森道路課長","answer":"令和３年９月から令和４年８月頃まで通院を繰り返されたというふうに聞いています。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"今のご答弁で聞き逃したと思うのですけれども、事故が起きた、その相手方から申告があったという理解でいいですか。","respondent":"森道路課長","answer":"何割かという話は、保険会社のほうで設定をされて、その金額を区としては受けて、それでご提示したというような形になっています。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"結構報告されないで終わってしまっているケースが多いと思うので、積極的に何かあったら言ってくださいというのは、言い難いところがありますが、その辺の対応はどうされる、やはり言われたらやるという形なのでしょうか。その前に、区道の点検は常にやっていただきたいという思いはありますけれども、でもやはり、結構こういうケースは多いのではないかと思うのですが、対応の方法はいかがでしょうか。","respondent":"森道路課長","answer":"いただいた上で、区のほうでしっかりと対応を誠実にするところですけれども、必ずしも補償が出るということでもございません。","id":"exchange-126"},{"speaker":"田中委員","kind":"質問・要望","question":"我々健常者は、ちょっとした段差は避けられますけれども、高齢の方とか、車椅子の方は、ちょっとした段差も大きな障害になってしまう中で、今回のような事故が起きてしまうと、やはり歩道の在り方、レンガ敷きが、特に商店街の見栄えの観点で積極的に取り入れた時期もあったかと思うのですが、一方で、そういう事故があったりで、経過すると段差がより激しくなったり、あるいは。","respondent":"森道路課長","answer":"あるいは、レンガ状ではあるのですけれども、そういった段差がつかないような、アスファルト敷きに色をつけたり、レンガの模様をつけたりということもありますので、今後はそういった技術もしっかり使いながら、安全な歩道を整備していきたいと考えています。","id":"exchange-127"},{"speaker":"若林委員","kind":"質問","question":"参考までにお聞きしますが、例えば１m2辺り、今お話に出ているレンガ状のもの、インターロック、通常のアスファルト等の舗装、これ、維持管理費は大分違うのでしょう。","respondent":"森道路課長","answer":"すみません、管理費として、１m2辺りというものを計算してはいないので、明確にお答えはできないのですけれども、肌感覚といたしましては、インターロッキングブロックのほうが高かろうというふうに考えておりますし、道路管理をするだけの視点でいきますと。","id":"exchange-128"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/216259?Template=document&Id=4394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":89654,"voices":346}},{"id":"r05-20231127-9","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"文教委員会","time":"午前１０時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件抜き出しています。","topics":[{"id":"topic-01","title":"第８０号議案、品川区児童相談所設置条例","agenda":"第８０号議案、品川区児童相談所設置条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"２点伺いますけれども、まず、資料の下の表で、令和６年度の一番右下、条例（案）上程というのがありますけれども、これは来年６月、どんな内容の条例になるのでしたかという確認が１つと、もう１つは、現在、建物は完成していまして、その中で、今年４月から準備業務を職員の方も入って行っていると思うのですけれども、その中で見えてきた現在の課題等というものについて伺いたいのですが、ハード。","respondent":"長谷川児童相談所開設準備課長","answer":"２点ご質問いただきました。１点目の、設置市事務移管に伴う条例提案の中身です。今、所管部署と協議をしておりますけれども、おおよそ１３本程度予定をしております。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"質問","question":"この設置条例に関しては異論ないところなのですけれども、関連して、条例上は品川区児童相談所という名前だと思うのですが、江戸川区なんかだと、はあとポート、荒川区は、子ども家庭総合センターのように、副題というか、親しみやすいというか、そういう名前をつけているのですけれども、この条例とは関係ないというか、あれなのですけれども、そういうことについては検討されているのでしょうか。","respondent":"長谷川児童相談所開設準備課長","answer":"愛称に関するお問合せです。区として今後検討すべき事項であるとは認識していますが、しかしながら、現時点においては、制定するといったところで考えているわけではございません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"設置条例ということで、子供の森公園内の設置なのですけれども、これについては、子育て世代の利用者等から見直しを求める意見も上がった経緯も過去にはありまして、設置場所や決定の経過とか、住民の説明と進め方の在り方などについては課題があったと認識はしているのですけれども、虐待防止を含めた、きめの細かで切れ目のない子育て支援を実現する上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、賛成です。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"第８１号議案、品川区立保育所条例の一部を改正する条例","agenda":"第８１号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"それと、暫定保育園のほうさん保育園のほうですけれども、こちらは１歳児園ということでよろしかったのでしょうかということと、あと、今年４月の荏原地域、６月の委員会で報告がありましたけれども、保育提供区域でいうところの荏原というところが、不承諾数が６３で、１歳児で半分の３１を占めているということで、この地域での待機児対策というのは十分ですという考えなのでしょうか。伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"３点ご質問いただきました。１点目です。一本橋保育園の民営化のタイミングですけれども、令和６年４月、来年度当初からの民営化を予定してございまして、改築工事実施後、移転をした後に民営化するというスケジュールで現在進めているところです。２点目です。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"期間限定の暫定施設として広報周知されていた内容ですので、賛成です。ただ、解体期間として、来年の４月から６月に予定されていると思われますが、こちらの解体工事の地域住民への配慮と周知を改めて徹底していただきたいと思います。こちらは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"反対なのですけれども、というのは、一本橋保育園のほう、施設の老朽化による改修、建て替えというのは必要なことなのですけれども、今回の改築というのは、ほかの民営化の園もそういう態度を示させていただいたのですが、区立保育園の民営化と。将来は、これは区も説明していますけれども、民設民営、完全に民間に渡すという流れの中での改築でありますので、認められないということで、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-03","title":"第８４号議案、品川区いじめ防止対策推進条例の一部を改正する条例","agenda":"第８４号議案、品川区いじめ防止対策推進条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"特に直接、条例には定めはないのですけれども、臨時委員にはどのような方を据えることを想定していらっしゃるのか伺いたいのが１つと、あと、これも条例に入れるのかどうかというのはあるのですが、やはり被害者とか家族にとっては、どんなことがあったのかというのは、すごく知る権利というのは尊重すべきだと思うのですけれども、その上で調査を行う対策委員会の存在というのは非常に大切だと思うのです。","respondent":"丸谷教育総合支援センター長","answer":"被害者、被害者のご家族のご推薦というようなことですけれども、いじめの事案に応じて、こちらの教育委員会のほうで、このケースであれば法律がよいだろう、場合によっては、このケースについては心理を厚く持たせたほうがいいだろうということで、こちらのほうでもある程度。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。被害者とか家族の知る権利というのはすごく重要視していただきたい、尊重していただきたいと、要望します。それと、ごめんなさい、正規の対策委員の職種についてお話がありましたけれども、これは規則とかにしっかり具体的に入っているものなのでしたか。そこだけ最後、勉強不足ですみません。確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"条例の中ではなくて、規則のほうで規定をしています。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問","question":"１点だけ伺いたいのですけれども、「次に掲げる事項について調査審議し」となっております。その調査の権限の中に、例えば、当事者からの聞き取りとか、そういうものは含まれるのか、その点について伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"調査の中には、場合によっては、被害に遭われた児童・生徒、保護者については必ず聞き取るようにということでこれまでも調査を進めてきておりますので、今後も丁寧に進めてまいりたいと考えております。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"保護者のご意見というのもとても大切だと思いますけれども、できましたら当事者、それもやはり両方の立場の意見とか、事実関係とかを聞き取るようなところも含めていただきたいと思います。これについて何か既にお考えのことがあったら、ご見解を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういったところで、心理の専門家や福祉の専門家、子どもに丁寧に対応できる委員というのを選定、進めていきたいと考えております。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひそのように進めていただきたいと思います。子どもたちの意見とか発言を誘導するようなことがあってはならないし、本当に公正な立場で、いじめをしてしまった側、いじめられたと思っている側の意見を丁寧に聴取できるような方をぜひ選定していただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"意見","question":"第１４条２項に(2)が加わったということですよね。２０条に規定するという。書いてあるのに、またここに、逆に、順番で言うと、１４条が先だからあれですけれども、何でそこに書いたのかというところ、当然してきたわけなのですけれども、その点を、法律の立てつけが不勉強で分からないのですけれども、そのことをお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"確かにこれまでも２０条にそのことは記載があったところなのですけれども、今回改めて１４条に役割として２点しっかりと明記することで、対策委員会の役割を明確にしたです。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"役割をはっきりさせたということで、万が一、いじめの行為が起きたときには、しっかりと対策委員会で調査することを宣言したというか、決意を新たにしたというか、そういう認識でよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"今のことと加えまして、今回、臨時委員を置くということで規定を定めるものでございまして、その意味については、重大事態が起こった際に臨時委員を置くことができるということで、次のほうにつながるような記載が必要ということもございましたので。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"意見","question":"先日、文教委員会で視察した寝屋川市や他自治体でも、いじめ対策委員会の条例や規則で臨時委員を設置できるようにしている自治体も多いので、現実に即した対応だと思われますので、公明党としては賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なのですけれども、今後は、子どもたちが楽しく安心して学びに向かえる学校づくり、あと、いじめに走る必要がない学校づくりなどの予防対策、また、小さないじめの芽や子どもたち同士のトラブル等が発生しても、子どもたち同士で話し合って自治的に解決できるような、子どもが主体の学校づくりというのをぜひ望みたいと思います。賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-04","title":"第８６号議案、指定管理者の指定","agenda":"第８６号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"改めて今回の公募によらなかった理由というところなのですけれども、特別な理由というところをもう少し中身といいますか、どんな理由なのかというのを伺いたいのが１つです。それと、そこの(3)番目の１期目の成果についてというところで、「強みを生かした保育・教育理念」と書いてあるのですけれども、それはどういう理念なのでしょうかというのを伺いたいと思います。","respondent":"立木保育課長","answer":"そうした中、社会福祉法人福栄会のほうにぷりすくーる西五反田の運営が移ったわけですけれども、移った後３年間の運営実績、こちらを毎年モニタリング等をさせていただいている中で、ＮＰＯ法人が培ってきたノウハウ、そちらを職員等。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"前の職員を引き継いでくる約束がありましたという話なのですけれども、それは別に福栄会だけに限らず、統合した事業者は、基本的には前の継続性とかを考えて、前の職員の方を雇ったりということは普通にあることなので、前回のときには公募すべきだったと私は改めて思うのですけれども、なぜ公募にしなかったのかというのを改めて伺いたいというのが１つ。伺いたいと思います。","respondent":"立木保育課長","answer":"認定こども園化につきましては、今現在は社会福祉法人化が実現いたしましたので、１つ課題としてはクリアされましたが、もう一つ、幼保連携型認定こども園に移行認可を受けるためには、今現在の施設ですと、園庭の部分が９０m2ほど不足しておりまして。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"５年目となる今回でいろいろやればよかったのではないですかと思うのですけれども、そこがますます分からなくなってしまったのですが、なぜ現在移行していないのであれば、急いで２年前に指定管理中に交代する必要があったのか、最後に伺いたいと思います。","respondent":"立木保育課長","answer":"認定こども園化に向けましては、区としましても、早期に実現をしたいと考えている中で、できる部分から取組をさせていただいたです。","id":"exchange-019"},{"speaker":"せお委員","kind":"確認","question":"幾つかお伺いしたいのですが、報告書の中で、委員の意見のところ、５ページです。すみません。もう１点だけ、細かいのですけれども、７ページの委員の意見のところの(1)で認証心理士と書いてあるのですけれども、これ、臨床心理士か公認心理師かとか思っているのですが、これ、私、ごめんなさい、認証心理士というところが知らないので、そこを確認したいのと、そこだけお願いします。","respondent":"立木保育課長","answer":"特別支援に関しての保護者の支援等に関しましては、今お話がありましたとおり、障害児者総合支援施設のほうは福栄会がやっておりますので、そういったところへの、例えば、なかなか難しいところではあるのですけれども、保護者の方への働きかけといいますか。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"ありがとうございました。先ほどの事故・けがの際のところなのですけれども、その内容をどのように、具体的に保育課で共有するのかというところをもう一回教えていただきたいのと、臨床心理士は園にいらっしゃるのか、それとも、区の巡回の方だけということなのか。そこもすみません、もう一度お聞かせいただければと思います。","respondent":"立木保育課長","answer":"報告書の様式がありますので、そちらのほうに詳細、発生原因ですとか、今後の対応についてというようなところをまとめてもらって、それを区のほうに提出してもらうというような形になります。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"障害児に関しては、保護者への支援をしていただいているということで、本当にありがたいのですけれども、やはり園の職員の認識と保護者の認識で少し違っているところがあったり、せっかく福栄会でグループというか、児童学園とつながっている、連携できるので、何かそういったところも仕組みがあればという。スムーズに連携できるようなところはお願いしたいというところで、そこはまた要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"確認","question":"１点だけ。７ページの認定こども園化についてで、先ほどからの話だと、この７ページでは、いわゆる人員体制は確認できたとなっていて、それはいいのですが、先ほどの話だと、課題はそこではなくて、園庭の面積が大きな課題なわけですよね。その辺の確認だけさせてください。","respondent":"立木保育課長","answer":"これも指定管理者にどうこうできるところではなくて、区のほうがしっかりこれは対策を立てていかないといけないという部分ですので、それを今、ぷりすくーる西五反田と、あと、隣の区有地であります西五反田保育園。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"そんな中で、今回、指定管理者、福栄会がやることによって、その先のいろいろな一体化も含めて、それこそ高齢者施設、シルバーセンターとかという話なので、そういうのを含めてやると、福栄会が指定管理でやられているのが非常にいいという意味合いなのですか。","respondent":"立木保育課長","answer":"そうした中でどういう形がいいのかというのは、これから区がしっかり検証、検討していかないといけないと思っていますが、今現在、例えば福栄会がやっていただいているということで、それに合わせた形での改築なりということではなく。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問","question":"でも、せっかく福栄会がやるのであれば、彼らのノウハウもいっぱいあるだろうし、いろいろな知識も持っていると思うので、そこはうまく連携をしていただくのがいいのかと。そういった意味で質問を先ほど。ぜひそこはうまく連携していただければと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田副委員長","kind":"提案","question":"それで、事故・けがの際の保育課への共有については、私どもも確認しております。たしか誤食ですよね。１件ありました。それで、それに関連しますが、提案内容の評価が、４５０点満点のうち３８２点、それから、財務状況の評価で何でこれが満点にならないのかと思ったのですけれども、その辺の減点理由が何か、お話を伺えるようでしたら、伺いたいと思います。","respondent":"立木保育課長","answer":"財務状況のところですけれども、今、細かいところはあれなのですが、毎年決まった予算の中でやっていただいている中で、なかなか苦労してやってもらっているところもありまして、そういった中で、お金をよりうまく使ってもらうというところで。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これまでもそういう発言をしていると思うのですけれども、資料提供をされるべきではないかと思います。それから、財務状況については、福栄会自身はすごく全体の財務状況などはホームページ上で公開されているということも承知しておりますけれども、これ、指定管理ですので、その辺について、満点にならないというのはよく理解できないので、今後、その辺についてはぜひ満点を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"確認","question":"この指定管理については異論ないところでありまして、お伺いしたいのは、幼保連携型認定こども園についての移行で、ほかの委員の方からもありましたけれども、隣の保育園との関係も含めて、それをすることによって、認定こども園へ移行ということを検討しているというのは、もう一回確認ですけれども、隣の保育園と一体化するかどうかは置いておいて。","respondent":"立木保育課長","answer":"具体的に、例えば、９０m2の確保の仕方なのですけれども、ぷりすくーる西五反田そのものを建て替える必要までは今のところないと思っておりまして、例えば、９０m2分を隣の敷地の一部を使うような形で何かできないかというようなところも含めたり、あとは、屋上の部分が、今。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"屋上の２方向は工事とか、いろいろ大変なことになるかと思うのですけれども、区が目指していると書いてありますので、そこを目指して、今お話のあったことも含めて、ぜひ検討を早急に進めていただければと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"理事者からご説明があったとおり、社会福祉法人の強みを生かせる点、人員体制についても確保されている内容を確認いたしましたので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"先ほど質問いたしましたが、安全確保とか、それから全体の財務状況というのは、やはり満点というのは難しいのかもしれないですけれども、満点を目指して、今後とも見直していただきたいという思いを込めて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"意見","question":"賛成です。令和２年度の期間途中の指定管理交代の必然性についての区の説明については、まだ納得できない点はありますが、通う子どもの保育・教育環境が大切ですので、施設の性格上、継続というのは理解できますので、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-05","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、マイスクールのほうは、こちら、対象の学年を伺いたいと思います。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"私からは、国立・私立に通っている方の人数ですが、小学校で約１,２００名、中学校で約３,０００名と把握しています。新しく開設するマイスクールの対象の学年ですけれども、資料２の(2)にありますとおり、区立小・中・義務教育学校に通う３年生から９年生の児童・生徒と考えております。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"学校給食のほうですが、区長が所信表明で、保育・給食・医療子育て３つの無償化については、いずれも所得制限を設けることなく、全ての子育て家庭の負担を減らすべく実施してまいりますと述べていらっしゃるわけですが、本当は国がやるべきだと思いますが、このように表明をされているわけですから、全ての私立、国立、都立、分け隔てなく、学校に通う区民の児童・生徒へも。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"特別支援学校以外に、国立・私立学校への支援の拡大ですが、こちら、教育委員会といたしましては、学校教育法のほうで、少し省略はいたしますが、学校の設置者はその学校の経費を負担するというものが定められておりますので。マイスクールの、今回、４つ目の施設となるわけですけれども、エリア的にもまだ不十分という認識もありますので、マイスクールの場所が増えていくといった段階で、１、２年生も通える範囲になるということがあれば。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"国の動きを注視していくということですが、注視だけしていないで、当初、品川区が無償化を踏み出したときというのは、２３区でもかなり少数だったのですけれども、２３区全部踏み出したという感じではなかったかと思うので、やはり実施することが周りとか国を大きく動かしていくということになりますので、ぜひ品川区から、もちろん国に実践、示していくという意味でも、注視だけではなくて、自ら国立、私立。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"荏原地区は今後、これ、いろいろとご検討願いたいというのは、要望で終了させてもらいますけれども、２点お尋ねします。既に終わっているかと思うのですけれども、当然これ、理解は得られていると思うのですが、この町会長会議の中でどういう質問があったのか、質疑があったのかというのをお尋ねしたいと思います。これ、何か違いが、横文字になって、どういう仕切りになっているのかと思って、その確認です。","respondent":"丸谷教育総合支援センター長","answer":"地域説明、町会長会議が１１月１０日にございまして、町会長に説明をしてまいりました。ほぼというか、子どもたちのための施設になるならということで、賛成をしていただいたという認識です。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々も一生懸命やりますけれども、そこは要望しておきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ただ、中には学校に、例えば週１回とか２回とか、別室に通えるといったような児童・生徒も多く含まれておりますので、学校と児童・生徒、家庭との連携の中で対応しているものと、また、今後は、例えば、校内に別室指導の支援員を、今、荏原五中で配置をしておりますけれども。","id":"exchange-037"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"仮にそのようなスペース的に、いわゆる敷地というか、その確保が難しくて、なかなか造れないのであれば、場所的な部分に関しては、私は例えば塾とかは区内にたくさんあるわけですよね。その教室、いわゆる学校の時間帯というのは、そんなに塾というのは繁盛というか、していないわけですよね。忙しくない時間帯ではないですか。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つは、西大井の指導体制なのですけれども、室長は現状は八潮などだと元校長先生でしょうか。ただ、その指導される方、指導員というか、実際に児童・生徒に接する方は、教員では、正規のもちろん東京都の教員ではないわけなのですけれども、どういった方が指導する体制になるのかということ、あと、何人ぐらい、３０人ですから、八潮と同じぐらいなのでしょうか。その点もお願いします。","respondent":"丸谷教育総合支援センター長","answer":"人数の規模ですけれども、今まさにその辺りを調整しているところでございまして、八潮と同等の人数を想定して募集をかけていきたいと考えております。","id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問","question":"ありがとうございました。ですから、余計にやはり正規教員でないということは、なかなか、逆に言うと、いろいろ校長先生の指導とかがあったとしても、余計に厳しいところがあるのではないかと思っています。集団でやるということは本当にプラスで、移動教室にも行ったり、そういったことをやるので、体制自体はいいと思うのです。ただ、そこの適応指導教室のことについて、最後、お尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"国のほうでも設置については求めているところですので、今後、国の動き等も十分に注視しながら、また、他地区でも不登校特例校を設置している動きが徐々に見られているというところも我々認識していますので、今後どういう形で進められるかというのは引き続き注視しながら。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。国や他区の動きを十分注視して、特例校についてはぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"せお委員","kind":"質問","question":"私から２点お伺いしたいのですが、給食費のほうなのですけれども、実施方法のところで、申請方法、申請書および奨励費の結果とあるのですけれども、奨励費というのは、区や都が準備しているのは存じ上げているのですが、私立や国立というのはあるものなのか。私が無知なだけなのですけれども、奨励費の結果というところを具体的に教えていただければと思います。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"私から、奨励費の件ですが、こちら、特別支援学校への就学奨励に関する法律というのがございまして、そちらでは公立、私立、国立がこの対象になるということで定められておりますので、私立、国立も奨励費があるということになります。とはいえ、学校施設ではございませんので、その施設に合った形での活動ということを工夫してやっていきたいと。今後、カリキュラムの検討等を進めていく中で考えていきたいと思います。","id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問","question":"このたびのマイスクールのほうなのですけれども、この間、決算特別委員会のときに、うちの会派の議員から、１、２年生に不登校が増えているということに対しての、１、２年生を対象としたところも増やしてほしいという趣旨の質問をいたしました。","respondent":"丸谷教育総合支援センター長","answer":"１、２年生の不登校児童への対応ということですけれども、マイスクールについては、現状、場所が４か所しかないということと、遠方から通う児童も出てくるということで、体力的にどうなのかというところで、今回も見送っております。","id":"exchange-043"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"できたら、それこそ地域を考えると、荏原地区へというのは、区全体として求めるべきことと考えていますが、それと併せて、それがすぐ実現が不可能であれば、学校の中で具体的にそういうことをどう進めるかというのを学校任せにしないで、ぜひ全体として検討していただければと思います。もし何か見解があったら、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒の問題については、単独の学校の問題ではなくて、区全体、もっと言えば、国全体の課題だと考えておりますので、国や都の動きも注視しつつ、品川区としてできることを引き続き検討して進めてまいりたいと考えております。","id":"exchange-044"},{"speaker":"ゆきた委員","kind":"意見","question":"特別支援学校給食費事業について、公明党として大変歓迎したい内容だと感じていますので、賛成です。ただ１点、品川区として、国立・私立の特別支援学級に入学した際の学籍までは把握していると聞いております。マイスクール西大井については、こちらも賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"特別支援学校給食費については求めてきたところですので、賛成をいたします。それから、マイスクールについては、先ほど要望もいたしました。まだ本当はもっともっとと思うところはあるのですけれども、この拡大が進んだということでは、一歩前進として評価をいたしますので、賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"第８２号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","agenda":"第８２号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考までに、今回の文言整理に関わる、就学前の子どもに関する教育、保育等の総合的な提供の推進に関する法律、この改正の内容は何だったのか伺いたいのと、また、今回、条例改正によって、区の事業の内容に何か変化が伴ってくるものなのか、伺いたいと思います。","respondent":"石井保育支援課長","answer":"今回の改正は政令指定都市に係る部分ですので、区の事業内容等に変更があるものではございません。","id":"exchange-047"}]},{"id":"topic-07","title":"令和５年請願第１５号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和５年請願第１５号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"親同士というか、そういった園と利用者、子どもがつながっていくというのはすごく大事なことだと思うのですけれども、ご説明はちらっとあったかとは思うのですが、区として、連合会の活動についてどういう認識というか、評価されているのか。実際、連合会の活動というのはどういうことが行われているのか、もう少し説明していただければと思います。","respondent":"石井保育支援課長","answer":"活動についての区としての受け止めなのですけれども、やはりこういった中で、保護者ですとか教職員相互の連携を図りながら、各園で実際にやっていただいている教育活動と相まって、幼児教育の下支えとしてとても貢献していただいているという認識です。","id":"exchange-048"},{"speaker":"吉田副委員長","kind":"質問","question":"本日結論を出すということで、採択を主張したいと思います。幼児期のこういう集団の中での教育というのは、いわゆる学校に入ってからの教育以前の、非認知機能を育てるという意味でも、この時期の集団教育は大変大切だと認識しております。なかなか厳しい運営だというのを伺っておりますので、この請願については採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-08","title":"令和５年陳情第４５号、品川区立学校図書館の充実に関する陳情","agenda":"令和５年陳情第４５号、品川区立学校図書館の充実に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それで、図書館運営支援スタッフの委託契約の内容について最初に伺いたいのですが、週に何日、何時から何時までという契約なのでしょうか。契約期間は何年間なのか。資格要件はどうなのか。仕事の内容は、大まかな、こういった仕事をやってもらいますという内容を伺いたいと思います。今実際に働いているスタッフの方というのは、正規雇用になるのか、非正規雇用になっているのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"仕事内容につきましては、細かくは、開いていない場合は開館事務だとか、閉じる場合の最後の閉館事務、貸出し処理、返却処理、本の配架、カウンター周辺業務、それから、本のリクエストに対する業務、レファレンスや授業支援業務、それから、教職員の相談対応、資料の登録。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。何時から何時という勤務時間の定めというのはなかったのかというのを伺いたいのと、あと、仕様書は単年度ということで、あと、契約内容とかも、私は例えば、週に１５時間というのも、必要に応じて、５年間の途中であっても、これは変更していいのではないかというか、こちらのほうで持ちかけて、それでのんでいただければ、変更も可能なのではないかと思います。どれも大事だと思います。","respondent":"吉田品川図書館長","answer":"具体的には、児童・生徒や教員に対する間接的支援、児童・生徒に対する直接的支援、それから、教育目標を達成するための教育指導への支援という大きな３点、これが役割として果たされるところと認識しています。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"司書教諭というのが今出ていましたけれども、そちらのほうについても伺いたいと思うのですが、学校には、専任ではないのですけれども、司書教諭という方が定められておりますが、その司書教諭の担当課というのはどちらなのかというのが分かりませんが、ぜひそちらのほうで答えていただきたいのですけれども、司書教諭という方は、図書館スタッフと連携して。","respondent":"中谷指導課長","answer":"司書教諭が司書のスタッフの方とどう連携しているかというところですけれども、やはり図書館の専門性が非常に高いという意味では、司書の役割というのは大変重要だと考えていますので、そこの専門的な見地を活かした上での。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"そうですね。陳情にもありますけれども、「小・中の教科書では、学校図書館の利用活用・情報活用教育にページがさかれ、授業での活用がもとめられている」ということなのですけれども、そういった点で、区教委としては、この学習指導要領にあるこういった図書館の新たな発展的な役割に照らして、図書館司書、運営スタッフの存在意義というのをどのように考えていらっしゃるのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"その辺の総合的なところで、司書を含めて、学校図書館の運営をしていければと考えているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりましたけれども、やはり図書館のスタッフが充実することで、もっと図書館を使った授業というのもすごく充実できると思うのです。指導要領の内容の実施に責任を持っているというのは指導課だと思うのですけれども、そちらのほうから見て、図書館司書、スタッフの役割、存在というのはどのように考えていらっしゃるのか、教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"支援スタッフとどう連携をして、子どもたちへの指導の充実に充てることができるかということが非常に重要になってくるところだと思いますので、たとえ毎日配置がなかったとしても、勤務されている曜日にスタッフとしっかりと連携をしながら。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"ここもまた大事だと思っていまして、子どもの居場所としての図書館の役割、教室には行けないけれども、図書館が開いていれば、集団活動が苦手な子とか、自分の世界で本を読むのが好きだったりすることもあるので、すごく大事だと思うのですけれども、週に２.５日という配置では、そういった子どもが学校に行ったときに、居場所になるような図書館が開いていないという場所、よくあると思うのですけれども。","respondent":"吉田品川図書館長","answer":"学校図書館の開館状況ですけれども、基本的には、支援スタッフのほかにも学校の先生、それから図書委員等含めまして、基本的には開いているものです。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"そうですね。ですから、少なくとも週に５日、朝から放課後までは開けておけるという状況が、仕事量からいっても必要だと私は思っています。ただ、私はこの状況ですと、居場所という点でも不十分だと思うのですけれども、居場所として、現状の２.５日で十分と言えるのでしょうか。私は言えないと思うのですけれども、いかがでしょうか。ここも伺いたいと思います。","respondent":"吉田品川図書館長","answer":"学校図書館の利用につきましては、各学校の利用の特色等もあります。各学校から毎年アンケートをいただいている内容も踏まえまして、今後も機会をうかがいながら対応を検討してまいります。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ随時、臨機応変に契約は見直していただきたいのですけれども、今回、一番下になるのですが、見直しということで、５年に一度の、今年見直しをかけまして、今年度から新たな契約がスタートしているわけですが、この新たな契約を結ぶに当たって、様々、要望もありました。議会でも議論がありました。結局、日数、時数は変わらなかったのですけれども、担当課としてはどういう検討を行ったのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、これは頑張っていただきたいと思いますし、契約自体が柔軟に、契約期間としては１年ということでもあるので、相手方にとってみれば、日数が増えるということは、それだけお仕事が増えるということでもありますので、決してマイナスな変更ではないと思いますし、ぜひ来年度からでも、契約の内容、相手方を変えろとは言いません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこをまず１点教えていただきたいのと、今の話の中で、実質２.５日ぐらい、週１５時間だとそうなると。仮に陳情されている方たちが言われている、毎日いる図書館、５日間になると、どのくらいの予算になっていくのか、分かる範囲で教えていただきたいのと、実際に今、契約をされている委託業者の方たちに、仮に５日間の体制をつくってくださいといったときに、実際、その業者が人的も含めて可能なのか。","respondent":"吉田品川図書館長","answer":"そういう方の中には、これ以上増やせないという方もいらっしゃるのだと伺っておるので、場合によっては、人が替わってしまう、新たに雇用しなければならない、もしくは、今いる人を替えなければならないという状況が発生するということは、昨年度。","id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"何でかというと、１０年後には、下手したら、これからの社会の流れからすれば、本自体が存在しているのかどうかというような話にも発展する可能性があるわけです。五、六店舗あったのです。ただ、一方で、ご答弁いただいた現実的な課題があるというのが今分かったので、そこをどうやって工夫して充実をさせていくかというのは、ぜひ引き続き検討していただいて、いい案を見つけていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"ゆきた委員","kind":"質問","question":"ただいま理事者のほうから、学校図書館支援スタッフの委託業者の募集要件で、司書資格を取り入れたというお話があったと思いますが、そのほかにも品川区の学校図書館運営をする上で、質の向上を図る上で、現状の中でどういった工夫、取組をなされているのか、もしあれば、教えていただければと思います。","respondent":"吉田品川図書館長","answer":"質の向上への取組につきましては、年にそう多い回数ではございませんけれども、全体における研修だとか、あとは、各事業者における研修制度、これを毎月やっている事業者もあります。そのようなところで、質の向上を図るというところを現在進めているところでもあります。","id":"exchange-061"},{"speaker":"吉田副委員長","kind":"質問","question":"他区の状況といいますか、他区の学校の図書館の状況とか、司書の配置状況とか、把握しておられるのでしょうか。もし把握しておられるようでしたら、少し特徴的な、例えば、何々区とか何々市は既に５日間配置しているとか、そうでもない、配置が少ない区もあるとか、品川区の、自治体における、どれぐらいの配置状況なのか把握しておられたら、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"一番多いところは１,５００時間を超えているようなところもありますし、品川区の２倍程度のところも当然あります。品川区は、大体１０番目から１３番目ぐらい、７３５時間につきましてはそのぐらい、真ん中辺りです。","id":"exchange-062"},{"speaker":"吉田副委員長","kind":"確認","question":"少し曖昧な聞き方で。真ん中ぐらいというのは、要するに２３区に限ってということでしょうか。それを１個確認させてください。","respondent":"吉田品川図書館長","answer":"大変失礼いたしました。２３区中、大体１０番目から１３番目辺りのところの年間委託時間数です。","id":"exchange-063"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"子どもの教育にかけるということですので、ぜひこの辺は手厚くしていただきたいと思っているのですけれども、ごめんなさい、私、こういう契約の契約金額の算定の仕方がよく分かっておりませんで、総合評価の中で、事業者のほうから積み上げとか、そういうので出てきて、それで決めてしまうということなのでしょうか。","respondent":"吉田品川図書館長","answer":"大きくは４つぐらいに、契約の金額の内訳が分かれます。人件費の部分、これは各事業者における人件費の部分と、支援スタッフにつきましては、ほとんどが人件費の部分になりますので、そちらの金額が、提案された金額がほぼ人件費の中にという形で受け止めているところです。","id":"exchange-064"},{"speaker":"吉田副委員長","kind":"確認","question":"そうしますと、契約はほとんど人件費ということになるという理解でよろしいでしょうか。確認させてください。","respondent":"吉田品川図書館長","answer":"契約の金額につきましては、ほぼ人件費の金額になります。","id":"exchange-065"},{"speaker":"吉田副委員長","kind":"質問","question":"人件費と時間数というのはすごく密接に関係してくると思うのですけれども、それは１人当たり何時間の、１時間当たりは幾らぐらいというような形でフィックスされてしまっているという契約のやり方なのでしょうか。ごめんなさい。契約金額、結構大切かと思うので、教えてください。","respondent":"吉田品川図書館長","answer":"会社によっても、当然、単価というのか、１人当たりの金額は異なっている部分でありまして、今回、５つ契約がありますけれども、それに当たっても、それぞれ金額はまちまちです。","id":"exchange-066"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"分かりました。もちろん人材の母数がたくさんいらっしゃれば、それにこしたことはないのですけれども、そういう現状もある中で、多少、ほかの自治体との競争といいますか、ぜひよい司書、資格はともかく、そういう経験のある方に来ていただきたいと思うのですけれども、その辺についての契約をするときの品川区としての要望とかをどのように話し合っておられるのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"先ほどもあった顔見知りのスタッフがいてというようなところもありますので、そういう優しいスタッフというのでしょうか、図書館も含めて、いろいろな意味で知見のあるスタッフというのを準備するよう、事業者にはお願いしています。","id":"exchange-067"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひ図書館の司書の充実、司書の充実だけではないような気もするのですけれども、その一つとして、図書館が子どもたちにとって行きたい場所、いい場所になるためには、その一つの条件として、司書の配置というのはすごく重要だと思いますので、ぜひ今後前向きに考えていただきたいと思います。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"せお委員","kind":"質問・要望","question":"児童・生徒が、望む方が誰もが通える、安心・安全に通える区立学校をまずつくっていくことが大事だと思っていますので、もちろん司書の方は今ゼロではないので、こういったところを充実させるというよりかは、先ほどご答弁でも、予算約２.５倍ということのお話もありましたので、そういった予算を、まずは特別な支援が必要なお子さんの支援員などを充実させていただきたいという思いもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"ゆきた委員","kind":"確認","question":"学校司書には資格が必要ではない中で、品川区で今年度の募集要件として、司書資格を条件として募集要項に取り入れている点や、学校図書館運営支援スタッフは、司書資格を持つスタッフが５６名中４９名、先ほど８７.５％の方が子どもたちの情報活用教育を支援し、資格司書がいることで、不足部分を補っている点から、質の向上に向けて施策を前に進めていることを確認いたしましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それで、ぜひ図書館司書は増やす方向で今後検討していただきたいと考えていますが、やはり今、５年間の総合評価の中の途中の年であるということで、契約は毎年ということですけれども、そこで急に金額を大幅に増やすということは確かに難しいかと思います。私の過去の発言録をたどれば、私の個人の発言については矛盾した発言になっておりますが、そこへのご批判は甘んじて受け止めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張したいのですが、実現、クリアすべき課題というのは、それはたくさんあると思う。それはどんな課題でもそうだと思うのです。私は学校教育の充実と、子どもにとって何よりも大事なことだと思いますので、ここで採択をして、議会の意思を示して、政治決断を促すべきなのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出す。何学級以上の小学校が幾つとありますけれども、小中一貫校は、２校分なので２人配置されていると伺っています。ですから、そういったことを含めて、２０学級以上云々というのがありますけれども、段階的にというか、毎日というところの趣旨は、いきなりというのはなかなか厳しい部分ではないかと思いますので、今回のこの陳情に関しては不採択としていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"結論を出すで、不採択です。ただ、この充実という部分に関しては、しっかり私は地域の方たちとの連携も含めて、やれることはまだいろいろあるのかと思いますので、その辺に関してはぜひやっていただきたいと思いながらも、今回、この陳情に関しては不採択でよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]},{"id":"topic-09","title":"教育目標および基本方針の改訂","agenda":"教育目標および基本方針の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これ、教育目標および基本方針の改訂については、いつの教育委員会で審議されて、もう決定済みなのかということというか、そこら辺の教育委員会の中での審議状況などを聞かせていただきたいというのが１つと、それと、この教育目標および基本方針というところに、いつも言っているのですけれども、子どもの権利条約という文言が一言も入っていないというのはいつも違和感があるのですが。","respondent":"宮尾庶務課長","answer":"当然、子どもの権利を尊重するという考え方は、私ども教育委員会には共通して持っている考え方ですが、少なくともこの目標、方針に関しては、特段、改めての表記というのはしていないというものです。","id":"exchange-075"},{"speaker":"安藤委員","kind":"提案","question":"最後、もう１点質問しますけれども、少なくとも人権というところがあるではないですか。だから、私は、基本方針の１、ここの人権のところに、少なくとも子どもの権利条約という、国際条約ですから、入るべきなのではないかと思うのですけれども、ここだけは最後１点、ぜひ検討していただきたいのですが、ご答弁を伺いたいと思います。","respondent":"宮尾庶務課長","answer":"今回につきましては、繰り返しになりますが、現行のものを継承するというような考え方に沿って行ってきたものですが、子どもの権利条約というところにつきましては、こちらの人権教育を含め、様々な場面で、考え方としては、我々、基本として持っておりますので。","id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。それから、小中一貫教育要領は、一般質問のご答弁にもありましたけれども、これ、２２年に改訂してから、私の記憶では、改訂というか、変更があまり進められてないと思うのですが、そちらについても今後、どのようにされていくのでしょうかということです。","respondent":"中谷指導課長","answer":"すぐにこれに決めていこうというようなスケジュール感ではなく、まず、議論をするというところを軸に置かせていただいておるのですけれども、こちらも行く行くは改訂ということで、中長期的に見る中での見込みとして、そのようなスケジュールで進めしています。","id":"exchange-077"},{"speaker":"高橋（し）委員","kind":"質問","question":"小中一貫教育要領も一緒にということでよろしいのですか。","respondent":"丸谷教育総合支援センター長","answer":"補足となりますけれども、小中一貫教育要領は平成２２年度に改訂を行いまして、その後、学習指導要領が改訂になった平成２９年、そこに合わせて、品川区立学校教育要領という、名称も新たに変えまして、現在、それを基に教育活動を進めているところです。","id":"exchange-078"}]},{"id":"topic-10","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の裏面ですが、子育てネウボラ相談、児童センターの中の相談員の方がということですけれども、これ、主な相談の内容というのですか、どんな相談がされるのかというのを知りたいということが１つと、あと、左下のその他の事業の乳幼児ショートステイというのは、令和４年度から始めているわけですけれども、この実績はそれぞれ何件ぐらいあるのでしょうかということと、あと。","respondent":"染谷子ども家庭支援センター長","answer":"センターという建物につきましては、現在、子ども家庭支援センターが１か所と、それから保健センターが３か所、区の中にあるかと思うのですけれども、その中で施設を一体的に運営するパターンと、施設自体は別々ではあるけれども、組織運営上一体的に運営するという。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところというのは、これ、いわゆる子ども家庭支援センターという名前がなくなって、子ども家庭センターになるということなのでしょうかということを確認します。それと、かなりいろいろな事業が、相当利用が伸びているということで、やはりすごく求められている事業ですし、その時々で気軽に相談できるところがある。こういった事業を通して、お考えがあるところを聞かせていただきたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"そういった中で、ご自身のお子さんの発育、発達の状況が、ほかのお子さんと比べてどうなのかとか、そういったところに関するいろいろな情報を、意見交換、情報共有したりとかする場が非常に減っているというようなことをお話として伺いますので、そういったところでも。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問・要望","question":"先に要望して、最後に質問したいのですが、やはり分かりやすく名称をという話がありましたけれども、抱えないで、あなたは一人ではないのですよと。最後、質問はこれで終わりにしますが、おむつの宅配の事業を新規でやるではないですか。それはこのどこら辺に位置づくのですかというところを最後に教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"おむつの宅配の事業につきましては、保健センター側で実施している事業にはなりますけれども、先ほどご説明をしたバースデーサポートをこちらで実施する、１歳の誕生日を迎えるタイミングで、おむつの宅配については、０歳児が対象になってくる事業かと思いますので。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問・要望","question":"子ども家庭センターの場合ですと、保健センターという関わりもあると思いますし、やはり子育てしている方からすれば、所管はあまり関係ないので、ぜひこういう切れ目のないネットワークをつくるという中の、０歳の境というのは、どちらが指導するのか分かりませんけれども、しっかりと続けて、横串を刺すといいますか、そういったこともお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"ゆきた委員","kind":"質問","question":"妊娠期面談では、オンライン面談が品川区ではありますが、児童センターのネウボラ相談員とのオンラインでの相談は、以前からも文教委員会の中で話が出ていますが、児童センターの子育て相談員とのオンライン面談について、区のお考えがあれば改めてお聞きできればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"子育てネウボラ相談員のオンライン面談につきましては、今回、令和７年度の開設を予定しております子ども家庭センターの検討を進める中で、地域子育て相談機関の役割は非常に大きくなってくるかと思いますので、その検討をする中でも。","id":"exchange-083"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ前向きに取り組んでいただければと思います。そこで、例えば、出張型のネウボラという今話があったと思うのですけれども、この出張型のネウボラが、各地域の保育園で定期的に巡回して、保育園のちょっとしたスペースで相談できる場があればという声もありますけれども、この件について、急なのですけれども、区のお考えがあれば、お聞きできればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"そういったところ、子育てネウボラ相談員が保育園に出向いて相談をお受けするのか、それとも、そこの保育園自体を相談機関とするのかといったところの考え方があるかと思いますけれども、なるべく多くの方がご相談いただけるような体制というのは。","id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"意見","question":"切れ目のない子育て支援ですので、そこで切れ目が、妊産婦と子育てネウボラと切れてしまうといけないので、今お話あったように、情報共有は現状では仕方ないのかもしれませんが、できるだけ同じ担当の方というのがうまくいければいいかと思うので、ぜひ今構築していくというお話だったので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ここに書かれている、例えば、ネウボラ相談だったり、家事・育児支援の利用だったり、件数も上がっていて、成果が出ていると思うのですけれども、これ、いわゆる利用されている方たちというのは、どこでこの情報を入手してここにたどり着いているのかというのを把握されているのか教えていただきたいのと、把握されているのであれば、どの媒体なのかあれですけれども。","respondent":"染谷子ども家庭支援センター長","answer":"例年、利用された方にお答えいただいているアンケートの中で、産後の家事育児支援の利用助成、本事業を知ったきっかけが何かというところの回答につきましては、一番多いのが、母子手帳交付時にお渡ししているパンフレット、こちらで知ったという方が４５％いらっしゃいます。","id":"exchange-086"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いきなりずっとホームページを毎日見ないですから、隣の高橋しんじ委員みたいにずっとホームページをチェックして、今日こんな情報がというのはないです、そんな普通の人が。なので、ぜひいろいろな、過剰になるぐらい、特にＳＮＳ世代の人たちなので、やっていただけたら、もっと皆さんがやっていることが役に立つものになってくるのかと思うので、その辺はぜひ徹底していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"せお委員","kind":"質問","question":"裏面の令和７年度の子ども家庭センターのことなのですけれども、この子ども家庭センターの主な機能の特に1)2)なのですが、相談全般という感じですよね。皆さん時間がない中で、そこが本当に大変で、それはシステムの構築とか、どういった検討になっているのかというのをあえてお聞きしたいです。そちらをお願いします。","respondent":"染谷子ども家庭支援センター長","answer":"現状、保健センター、それから子ども家庭支援センターのほうでご相談をお受けする中でも、やはり医療ですとか、障害者福祉の分野のほうにおつなぎをするようなケースもございまして、そういった場合につきましては、適宜、ご本人の保護者の方のご了承をいただくか、もしくは。","id":"exchange-088"},{"speaker":"せお委員","kind":"質問・要望","question":"全然違う話で、先ほど来から皆さんのいろいろな支援があって、それぞれ大事なのですけれども、少し分かりにくい部分があったりとかというので、保護者の方からご要望いただいたのが、フローチャートみたいなものがあるというというお話があって、フローチャートまではいかないかもしれないのですけれども、今こういう状態だとか、イエス、ノーとかでやっていただけると、本当に皆さん。","respondent":"染谷子ども家庭支援センター長","answer":"フローチャートという形なのかどうかというところも含めて、検討させていただければと考えています。","id":"exchange-089"},{"speaker":"吉田副委員長","kind":"質問","question":"先ほどのせお委員のご質問と重なるのですけれども、いろいろ、ネウボラネットワークというのは、制度としては本当に切れ目なくきちんと用意されている。それと同じように、ほかの、直接今関係なくても、割といろいろなところから相談が来るような方たちが欲しいと思ったら、配布できるようなところまでは検討していただけたらいいと思っているのですけれども、いかがでしょうか。","respondent":"染谷子ども家庭支援センター長、藤村子ども育成課長","answer":"先ほど令和７年度開設の子ども家庭センターの説明の中で、一体的運営ということで、具体的には、まずは母子保健と児童福祉の分野ですけれども、こちらを統括するセンター長。先ほど別の委員から、紙のものとデジタルでハイブリッドでというようなお話をいただいたところなのですけれども、紙でお配りしているものが少し多いというようなお話もありますので、そちらについても対応するために、アプリの中で。","id":"exchange-090"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"どうもきちんとした印刷されたものを見て、それでホームページとかを確認して出ていると、ここは信用できるところだなみたいなのがあって、やはり両方、どちらかになるというのは難しいのだということは、ずっと議論の対象になっていたのですけれども、ぜひその辺の心理といいますか、それも踏まえた上で、より多くの方たちが適切な情報を受け止められるように努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"つる委員長","kind":"質問・要望","question":"本当に親としての反省だとか、家庭教育の課題だとか、様々、本当にそういう意味では機能しているということを実感するところと、保護者としての反省だとか、これは複雑な家庭環境とか、家庭問題があるので、詳細は避けますが、今回、子ども家庭センターの中に教育委員会や学校も入った、本当に幅広な体制なので、今、確認させていただいた、そういう常日頃、相談に乗っていただく方に。","respondent":"染谷子ども家庭支援センター長","answer":"都といたしましては、３歳以上のお子さんにつきましては、例えば、幼稚園ですとか保育園ですとか、３歳以上になると、いずれかの所属ですとかに接点を持つというところがありまして、それ以前のお子さんに関しては所属がないという家庭も結構ある中で。","id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246913?Template=document&Id=5114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":81664,"voices":298}},{"id":"r05-20231127-5","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"総務委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず、(2)第８５号議案、浜川小学校校舎・幼稚園園舎改築その他工事請負契約の変更","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず、(2)第８５号議案、浜川小学校校舎・幼稚園園舎改築その他工事請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"一般質問でもさせていただきましたが、公共建築物ならびに設備工事に関して、適宜インフレスライド条項を適用してやっています。今回のこの議案に対して反対はしませんが、ただ、他の産業も、やはり物価高、それから人件費高騰ということで、建設業者、設備業者と同じような状況になっていますので、今後、そういう産業、また、そういう事業者に対しても平等な対応を行政としてとるべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"これはこれでいいと思っていますけれども、お伺いしたいのは、多分これは大変ご苦労いただいて、皆さんも業者の方といろいろ交渉していただいて、なるべく当初の金額からあまり上がらないような形で交渉していただいているのだろうと思っています。上がるときは、いろいろ資料をとっても、相当上がる上がるばかり出てきているのだろうと思っています。","respondent":"小林施設整備課長","answer":"使用資材の単価のご質問ですので、私のほうから一括してご説明いたしますが、今、委員からご指摘がありましたとおり、品川区の単価につきましては、基本的には東京都の単価を使わせていただいておりまして、その情報につきましては、月に１回必ず。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"ここで５％というと、多分利益がそっくり上がっている感じ。多分これぐらいの規模になると、５％取るのもやっとだと思います。だけど、それはそれで非常にぎりぎりの話をしているのだろうから、そういうお互いぎりぎりの中でやっているので、ぜひそこら辺はよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"すみません、あともう１点だけですけれども、一般の工事業者・建設業者は、民間では、最初に見積り、請負契約をしたら、そのまま値上げしてくれるということはほぼありません。ですから、清水建設が大きな売上減になったとか利益がすごく落ちた、様々な建設業界でそういうことが起きているということは、私はやはり自治体としてもそれは捉えていてほしいと思います。それだけ民間は苦労してやっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"スチームコンベクションオーブン他の買入れ、民間では非常に高額なものだと聞いております。ただ、いろいろな利点があって、合理化も、人件費も削減できるということですが、かなり高額だと思うのですが、今の様々な小中学校においても、このような設備というのはどんどん導入されているのでしょうか。お聞かせください。","respondent":"柏木学務課長","answer":"給食設備の関係ですが、今回契約しております機器につきましては、学校給食法に基づき定められている学校給食衛生管理基準にのっとりまして整備しているものですので、ほかの学校についても同様のものが整備されているものです。","id":"exchange-005"}]},{"id":"topic-02","title":"第７７号議案 品川区組織条例の一部を改正する条例","agenda":"第７７号議案 品川区組織条例の一部を改正する条例","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"総務部が区長室となり、税務課が企画経営部に移管されますけれども、区税に関することという中で、ふるさと納税に関することを行っていくと思うのですけれども、具体的にはどのようなことを職員の方はされるのでしょうか。","respondent":"佐藤（憲）企画課長","answer":"先日の決算特別委員会でも様々ご指摘を受けている面もありますので、既に検討や、来年度予算の検討もしているところですが、来年度、企画経営部というところで、企画経営部長の配下として、企画課と財政課がいる部の中に税務課も来ていただいて。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"それから職員の方も、仕事ですからそれぞれ割り振られたところはやるのでしょうけれども、こういうふうに細かく分けてきた根本的な理由を教えてください。そして、それぞれ改正してから課がかなり増えているのかなということは、それぞれそこに課長が今度配置されるわけですから、その課長もやはり相当増えて、何か所くらい増えたのか。","respondent":"佐藤（憲）企画課長","answer":"条例改正の理由にもありますが、新たな課題ということで、少子化、経済支援、コロナ後の体制強化、ＤＸ推進等々、行政課題は様々増えて多様化しておりますので、そういった課題に適切に対応していくために、組織を再編して、来年度以降、適切に対応していきたいと考えております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、細分化されて区民サービスという意味では力を発揮されるのかもしれませんが、片や、そういう課長級が増えてくると人件費が逆に増えてくるという、片一方は区民サービスだけど、片一方は、品川区でも行財政改革をやっていますけれども、こういうふうに予算が増えていくという、そこら辺もいろいろ検討しながらやっているのですか。その辺、教えてください。","respondent":"佐藤（憲）企画課長","answer":"そういった状況でもありますので、コロナ後の様々な課題、区民のニーズも多様化しておりますので、そこに対応するために、人件費率も見ながら、適切に人員増も図りつつ、行革も行いながらバランスよく進めていきたいと考えております。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ区民に分かりやすい、迷わないような取組は、今までどおりしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"今の須貝委員のところに追加で、数字が出てこなかったのであれなのですが、人件費はどれぐらい増えるのか、多分そろそろある程度出ているのかなと思うのですけれども、そこの数字をお示しいただければなと思います。","respondent":"佐藤（憲）企画課長","answer":"課長級ポスト増に伴う人件費ですが、詳細な資料を今持っていないのですが、１人１,０００万円として、ポストが８増ですので、８,０００万円。そこまで詳細な数字が今手元にないです。申し訳ございません。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"これは総務委員会でせりざわ委員長のご専門のところかと思いますけれども、やはりふるさと納税をどうするのかというのが一つ大事なところかと思っておりまして、移管は移管として１つの効果かと思いますが、ただ、移管するだけで、果たしてこれまでなかなか戦略的な対応がとれていなかったふるさと納税が、この間も世田谷区のほうでまた別の動きというか新しい動きとかがいろいろ出てきている中で。","respondent":"佐藤（憲）企画課長","answer":"ご案内のとおりこれまで総務部に配置していたところで、税務課としては基本的にふるさと納税には反対しつつもというところのスタンスでやっていたところですが、企画経営部に移管して、先ほどお伝えしたとおり、全庁的な視点と、税務課、企画経営部だけではなく。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば地域産業と連携するという視点とかもふるさと納税の場合はあると思うのですけれども、そこは企画経営部という、どちらかというと全体を見ることができるので、そちら側で各所管課と調整するような枠組みを考えていらっしゃるということでよろしいでしょうか。","respondent":"佐藤（憲）企画課長","answer":"ふるさと納税に関するご質問ですが、地域産業、あと福祉施策ですか、子ども食堂のように区民の方がより参加しやすいものについても横串を刺して、企画経営部が中心になって進めていきたいと考えております。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"人件費の部分はそれでそうだと思うのですけれども、課の数というのは、２３区、他の区と比べたらどうなのでしょうか。今回、新設する課が８あるということで、課は増えると思いますが、それは他区と比べると、どういうふうに考えたらいいでしょうか。","respondent":"佐藤（憲）企画課長","answer":"他自治体と比べた課の数というところです。今はっきりした数字でお示しできないのですが、２３区の課長職の情報については、我々の方でも分析しておりますが、ざっくりな感覚で申し上げるのですが、品川区の課の数は比較的少ない自治体なのかなと考えています。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"課が８課増えて、部長級も、清掃事務所のところが部長級から課長級になったということで、今、部長をやられている方はどうなるのかなというのが一つと、あと、人材育成についてですけれども、８課増えるというところでいうと、課長級をやってもらう人の人材を確保するのはどうするのかというので、今、既に区のほうでも課題だというところで、さらにまた増えていくといったときに。","respondent":"佐藤（憲）企画課長","answer":"３点目の人材育成をどうするのかですが、これは従来から人事課のほうでもお話しされていますけれども、人材育成基本方針を今改定している中で、また、予算編成も今しておりますが、研修の在り方をどうしていけばより人が育っていくのかということを含めて。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"１点、総務部が区長室というふうに名称が変わって、今でも組織としてはトップは区長でとやっている中で、ここに区長室というものが入ってくることの意義とか、区長室の中に様々な部分が、特に広報なんかは、ブランディングにおいて区長が全面に出ながら様々発信していくとかというところでは、区長のところに大きく課が寄っているように見えるのですけれども。","respondent":"佐藤（憲）企画課長","answer":"区長室は、その組織をベースに、これまで以上に区長が先頭に立って進める組織として想定しております。今回は情報発信やコンプライアンス対応の強化を図る組織を新たに配下といたしまして、区長の意向をより踏まえた区長視点で動く組織として想定しているところです。","id":"exchange-015"},{"speaker":"大倉委員","kind":"提案","question":"柔軟に、どのぐらい、スクラップアンドビルドとかを進めていくというところでは、そういう意味では、区長も、提案を様々していきながら、区長の判断で動いていく可能性も大いにあるというところや、これは一定期間、事業として効果を得られたので、これはもう終わりにしましょうとかという判断も、区長がスピード感を持ってとか、何かの判断をしながら進めていくという認識でいいのかだけ教えてください。","respondent":"佐藤（憲）企画課長","answer":"区長室設置に伴うスクラップアンドビルドと、区長の判断で進めていくですが、事業のスクラップアンドビルドは今年度から事務事業評価を行っておりますので、企画部のほうで主体的に取りまとめをしながら進めていくという基本線は変わらないところであるのですけれども。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ、大倉委員が切り出してくれたのですが、人事課長にお聞きしたいのですけれども、我々が聞いているのは、課長の成り手がいないという話、よく庁内でそういう話が出ていると聞くのですが、こうやって増やしていくのは大丈夫なのですか。そうすると、今後さらに次の担い手、次の課長、またその次の課長というのが、今度そろわなくなったら、また縮小するようなことになっていくのですか。","respondent":"崎村人事課長","answer":"管理職の担い手の確保といったところについては、来年度から役職定年制が導入されるということもありますので、管理職選考の受験勧奨ということについては、人事課としても非常に強く意識して実施していますし、先ほど企画課長からご答弁させていただきましたけれども。","id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"すごく細かいところですけれども、資料を見ると、人権啓発課のフォントが小さくなっているのですが、これは何か意図があるのか。１０ポイントぐらいなのが９ポイントぐらいになっているのは、何か意図があるのか、全くないのか。","respondent":"佐藤（憲）企画課長","answer":"人権啓発課のところですが、見づらいポイントで大変申し訳なかったのですが、現在、組織のほうは引き続き検討中といいますか、今回は、条例改正のところで分掌事務と部名についてですが、課に関しては今検討中でございまして。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"その目的は何ですかといったときに、区民の幸福（しあわせ）ですということなのだろうと思います。全国でもそんなにないと思っていて、初めてみたいなことをやるときに、これ、初めては別に何でもいいのです、私は初めては結構好きなほうなので、やっていただくのは構わないけれども、ウェルビーイングという部分と、区民の方にもっと期待してください、この組織改正でというのを、もう少し説明してほしいな。","respondent":"佐藤（憲）企画課長","answer":"今回、組織のご提案ですけれども、ウェルビーイングをどういう系統にして、戦略的にどう進めていくというところに関しましても、区として、企画経営部として、見せ方も含めて検討して、しっかりお伝えしていかなければならないと考えていますので、適宜適切にまたお示ししながら。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか具体的に答弁いただきたいのは、区民向けに期待してくださいとここで強く言うのか、区長が言っているのも分かって、さっき言ったように分かっているのだけれども、期待してくださいというのを全面に押し出すということでやっていきますよということ。せっかくこうやっていいことをやるのに、もう少し丁寧にやってもらわないと、あまりに軽視し過ぎではないかなと思っていて、そこら辺も答えてほしいな。","respondent":"佐藤（憲）企画課長","answer":"一方、委員ご質問の議会に向けてですが、先ほどの答弁と重なる部分がありますけれども、体系的にどう進めていくのかというところは今しっかり検討していますので、そういったものがしっかり固まった時点で、第１回定例会の施政方針になるのかどうかはあれですけれども。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはいいのだけれども、将来にわたって、２年後、３年後見ていてくださいと。私は職員の方々が、ウェルビーイングでも、同じ意識を持ってやらないと、とてもではないけれどもできないし、それがこういう心得とかそういうことだと、私は多分、少なくとも１年、半年でもいいけれども、まず止まるような気がしてならないので、そこは答弁は要らないので、ぜひそういう人材育成をしてほしいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"塚本副委員長","kind":"質問","question":"そういう中でいうと、ＳＤＧｓ推進だとか、さっきちょっと話題になっていた廃棄物の資源循環推進担当課長とか、こういうのは、どこかがゴールとか、いつ終わるとかというところではなくて、経常的にあるような作業というか仕事だと思うのですけれども、担当ということにするのか、何の課というふうにするのかというところの判断は、どういう考えに基づいているのかというのを最初にお伺いしたいと思います。","respondent":"佐藤（憲）企画課長","answer":"課長と担当課長の違いだと思いますが、委員からご紹介がありましたプロジェクト型というのもありますけれども、その課題により迅速かつスピード感を持って形にするというところに関しても担当課長というところで、部下を何人かつけながらも。","id":"exchange-022"},{"speaker":"塚本副委員長","kind":"意見","question":"そうすると、先ほどの石田秀男委員のお話とも関連しますが、ミッションが終わったときに、次のステップというところで、コストみたいな話になりがちです。その辺のところは、現在、どのぐらい検討されていますか。","respondent":"佐藤（憲）企画課長","answer":"今回ご提案している担当課長も含めまして、コロナ禍で生じた新たな課題、様々な課題に行政としてしっかり対応していくというところですので、まずは着手して、来年度、様々な実施計画ごとの改定も予定されていますので、その中で進捗を確認しながら。","id":"exchange-023"},{"speaker":"塚本副委員長","kind":"質問","question":"イメージとしてはここが区長直轄の事業というか政策を担っていくのだというふうにも普通は捉えるわけですけれども、そういうことで、いわゆる区民に対するメッセージ、区長としてここを直轄で力を入れて推進していくのだというメッセージが込められているという捉え方でよろしいですか。","respondent":"佐藤（憲）企画課長","answer":"区長直轄といいますか、区長の権限は区長部局全てにわたるところでございまして、今回、情報発信やコンプライアンスの組織も配置して、区長がそういった区長室というところで掌握をより高め、区長の意向をより踏まえて、区長視点で動く組織ですので、区長室だけ特化して直轄とか。","id":"exchange-024"},{"speaker":"塚本副委員長","kind":"質問","question":"ちょっと細かいというか、突っ込んだ話になりますが、例えば区政運営会議とかをやっているではないですか。そういう方々もやはり今までと同じように、区政運営会議とか何とかということで、意思決定の手続というか、スキームというか、そういうものは総務部時代とあまり変わらないのか、やはりそこは区長室なのだから、区長裁決で進めていくみたいな感じになるのかというのは、いかがでしょうか。","respondent":"佐藤（憲）企画課長","answer":"今まで区政運営会議という形で月２回ほど実施しておりまして、その運営の仕方を変える予定はございません。","id":"exchange-025"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"毎回言っていると思うのですが、インフレスライド条項は、今回も第１回・第２回変更ということになります。こういう仕組みがあるならば、他の産業においても平等な対応をしていただけたらありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-04","title":"専決処分の報告について（報告第３５号）","agenda":"専決処分の報告について（報告第３５号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"インフレスライドは、他の産業にも平等な対応をしていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-05","title":"専決処分の報告について（報告第３６号）","agenda":"専決処分の報告について（報告第３６号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"インフレスライド条項は、ここに適用されているなら、他の産業にも平等な対応をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-06","title":"専決処分の報告について（報告第３８号）","agenda":"専決処分の報告について（報告第３８号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"今回は排水施設の設置の取りやめによる変更もありますが、やはりインフレスライドに対しては他の産業においても平等な対応をしていただきたい。今回、ほとんどみんなインフレスライドで請負契約が変更されるというのは本当にまれな例だと思いますが、早く解消していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24465,"voices":130}}]);
